FUNCTION_BLOCK FB_VFFS_MultiLane_Control
VAR_INPUT
    bEnable                 : BOOL; // Master enable
    bStart                  : BOOL; // Start production
    bStop                   : BOOL; // Stop production
    bEStop                  : BOOL; // Emergency stop
    rFilmTensionSetpoint    : REAL; // Desired web tension (N)
    rActualFilmTension      : REAL; // Measured web tension from load cell (N)
    rFilmVelocity           : REAL; // Current film velocity (m/s)
    bRegistrationMark       : BOOL; // Photo-eye for film registration
    bWeigherReady           : ARRAY[1..4] OF BOOL; // Multi-head weigher ready signals for 4 lanes
    rProductWeightActual    : ARRAY[1..4] OF REAL; // Actual weight dumped per lane
    rJawPositionActual      : REAL; // Ultrasonic cross-seal jaw actual position (mm)
    bJawHomeSensor          : BOOL; // Jaw home position sensor
    rUltrasonicAmplitude    : REAL; // Actual ultrasonic amplitude (%)
END_VAR

VAR_OUTPUT
    bMachineRunning         : BOOL; // Machine is in run state
    bError                  : BOOL; // Error active
    iErrorCode              : INT;  // Error code
    rFilmServoSpeed         : REAL; // Output speed for film unwind servo
    rJawServoPosition       : REAL; // Target position for jaw servo
    bJawServoEnable         : BOOL; // Enable jaw servo
    bUltrasonicGenEnable    : BOOL; // Enable ultrasonic generator
    rUltrasonicPowerCmd     : REAL; // Command power to ultrasonic generator
    bDumpRequest            : ARRAY[1..4] OF BOOL; // Request weigher to dump product
    bBagComplete            : ARRAY[1..4] OF BOOL; // Signal bag is complete and cut
END_VAR

VAR
    // State Machine
    eState                  : INT := 0; 
    // 0 = Idle, 1 = Homing, 2 = Ready, 3 = Pulling Film, 4 = Filling, 5 = Sealing/Cutting, 99 = Error

    // PID for Web Tension
    rTensionError           : REAL;
    rTensionIntegral        : REAL;
    rKp                     : REAL := 2.5;
    rKi                     : REAL := 0.1;

    // Jaw Kinematics
    rJawTargetSealPos       : REAL := 150.0; // mm
    rJawTargetHomePos       : REAL := 0.0;   // mm
    rSealTime               : TIME := T#200MS;
    tSealTimer              : TON;

    // Web Tracking & Registration
    rPullDistance           : REAL := 200.0; // Bag length (mm)
    rCurrentPull            : REAL;
    tPullTimer              : TON;

    // Multi-head Weigher Handshake
    bAllWeighersReady       : BOOL;
    i                       : INT;
    tFillTimer              : TON;
END_VAR

// Emergency Stop Handling
IF bEStop THEN
    eState := 99;
    iErrorCode := 1000;
    bMachineRunning := FALSE;
    bJawServoEnable := FALSE;
    bUltrasonicGenEnable := FALSE;
    rFilmServoSpeed := 0.0;
    FOR i := 1 TO 4 DO
        bDumpRequest[i] := FALSE;
    END_FOR;
    RETURN;
END_IF;

// Main State Machine
CASE eState OF
    0: // IDLE
        bMachineRunning := FALSE;
        IF bEnable AND bStart THEN
            eState := 1;
        END_IF;

    1: // HOMING
        bJawServoEnable := TRUE;
        rJawServoPosition := rJawTargetHomePos;
        IF bJawHomeSensor THEN
            eState := 2;
        END_IF;

    2: // READY
        bMachineRunning := TRUE;
        IF bStop THEN
            eState := 0;
        ELSIF bAllWeighersReady THEN
            eState := 3;
            rCurrentPull := 0.0;
        END_IF;

    3: // PULLING FILM
        // Tension PID Control
        rTensionError := rFilmTensionSetpoint - rActualFilmTension;
        rTensionIntegral := rTensionIntegral + rTensionError;
        rFilmServoSpeed := (rKp * rTensionError) + (rKi * rTensionIntegral) + 100.0; // Base speed

        // Registration Mark Logic (Simplified)
        IF bRegistrationMark THEN
            rFilmServoSpeed := 0.0; // Stop pulling
            eState := 4; // Move to filling
        END_IF;

    4: // FILLING
        FOR i := 1 TO 4 DO
            bDumpRequest[i] := TRUE;
        END_FOR;

        tFillTimer(IN := TRUE, PT := T#500MS);
        IF tFillTimer.Q THEN
            tFillTimer(IN := FALSE);
            FOR i := 1 TO 4 DO
                bDumpRequest[i] := FALSE;
            END_FOR;
            eState := 5;
        END_IF;

    5: // SEALING & CUTTING
        rJawServoPosition := rJawTargetSealPos;

        // Ultrasonic Sealing
        IF ABS(rJawPositionActual - rJawTargetSealPos) < 2.0 THEN
            bUltrasonicGenEnable := TRUE;
            rUltrasonicPowerCmd := 80.0; // 80% power
            tSealTimer(IN := TRUE, PT := rSealTime);
        END_IF;

        IF tSealTimer.Q THEN
            tSealTimer(IN := FALSE);
            bUltrasonicGenEnable := FALSE;
            rUltrasonicPowerCmd := 0.0;
            FOR i := 1 TO 4 DO
                bBagComplete[i] := TRUE;
            END_FOR;

            // Retract Jaw
            rJawServoPosition := rJawTargetHomePos;
            eState := 2;
        END_IF;

    99: // ERROR STATE
        bError := TRUE;
        IF NOT bEStop AND bStop THEN
            bError := FALSE;
            iErrorCode := 0;
            eState := 0;
        END_IF;
END_CASE;

// Weigher Handshake Aggregation
bAllWeighersReady := TRUE;
FOR i := 1 TO 4 DO
    IF NOT bWeigherReady[i] THEN
        bAllWeighersReady := FALSE;
    END_IF;
    IF eState <> 5 THEN
        bBagComplete[i] := FALSE;
    END_IF;
END_FOR;

END_FUNCTION_BLOCK
