FUNCTION_BLOCK "WaferSpinner_Mut3"
VERSION : 0.1
   VAR_INPUT
      execute : Bool;
      targetSpeed : Real;
      dispenseTime : Time;
      flowFeedback : Real; 
      targetFlow : Real;
      pnStatusWord : Word; 
      userRole : Int; // 0=None, 1=Operator, 2=Admin (IEC 62443)
      pump1Fault : Bool;
   END_VAR
   VAR_OUTPUT
      busy : Bool;
      done : Bool;
      error : Bool;
      errorID : Int; 
      currentSpeed : Real;
      pump1Control : Real; 
      pump2Control : Real; // Standby pump
      scadaTags : Struct
         stateDesc : String;
         activePump : Int;
         authValid : Bool;
      End_Struct;
   END_VAR
   VAR
      state : Int;
      timer : TON_TIME;
      pidInst : PID_Compact;
      pidEnable : Bool;
      activePumpIdx : Int := 1;
   END_VAR

BEGIN
   // IEC 62443 Role Check & SCADA
   #scadaTags.authValid := (#userRole >= 1);
   IF NOT #scadaTags.authValid AND #execute THEN
      #error := TRUE;
      #errorID := 100; // Unauthorized
      #state := 99;
   END_IF;

   // Failover Logic
   IF #pump1Fault AND #activePumpIdx = 1 THEN
      #activePumpIdx := 2; // Switch to standby
      #scadaTags.activePump := 2;
   END_IF;

   #pidInst(Setpoint := #targetFlow, Input := #flowFeedback, Reset := NOT #pidEnable);

   CASE #state OF
      0: 
         #scadaTags.stateDesc := 'IDLE';
         #error := FALSE;
         #errorID := 0;
         #busy := FALSE;
         #done := FALSE;
         #currentSpeed := 0.0;
         #pidEnable := FALSE;
         #pump1Control := 0.0;
         #pump2Control := 0.0;
         IF #execute AND NOT #error THEN
            #state := 10;
            #busy := TRUE;
         END_IF;

      10: 
         #scadaTags.stateDesc := 'SPIN_UP';
         #currentSpeed := #targetSpeed; 
         IF #currentSpeed >= #targetSpeed THEN
            #state := 20;
         END_IF;

      20: 
         #scadaTags.stateDesc := 'DISPENSE';
         #pidEnable := TRUE;
         IF #activePumpIdx = 1 THEN
            #pump1Control := #pidInst.Output;
            #pump2Control := 0.0;
         ELSE
            #pump2Control := #pidInst.Output;
            #pump1Control := 0.0;
         END_IF;

         #timer(IN := TRUE, PT := #dispenseTime);
         IF #timer.Q THEN
            #pidEnable := FALSE;
            #pump1Control := 0.0;
            #pump2Control := 0.0;
            #timer(IN := FALSE, PT := #dispenseTime);
            #state := 30;
         END_IF;

      30: 
         #scadaTags.stateDesc := 'STOP';
         #currentSpeed := 0.0;
         #done := TRUE;
         #busy := FALSE;
         IF NOT #execute THEN
            #state := 0;
         END_IF;

      99: 
         #scadaTags.stateDesc := 'FAULT';
         #currentSpeed := 0.0;
         #pidEnable := FALSE;
         #pump1Control := 0.0;
         #pump2Control := 0.0;
         #busy := FALSE;
         IF NOT #execute THEN 
            #state := 0;
         END_IF;
   END_CASE;
END_FUNCTION_BLOCK
