FUNCTION_BLOCK FB_SausageStufferControl
VAR_INPUT
    bEnable : BOOL; // System enable
    bStartCycle : BOOL; // Start automatic cycle
    bEStop : BOOL; // Emergency stop (Active Low)

    rTargetWeight : REAL; // Target portion weight in grams
    rActualWeight : REAL; // Feedback from load cell in grams

    bCasingPresent : BOOL; // Sensor indicating casing is loaded
    rVacuumLevel : REAL; // Current vacuum pressure in mbar
    rTargetVacuum : REAL; // Required vacuum setpoint in mbar

    rVanePumpSpeed : REAL; // Current vane pump speed RPM
END_VAR

VAR_OUTPUT
    bPumpRun : BOOL; // Enable vane pump
    rPumpSpeedRef : REAL; // Pump speed reference (0-100%)

    bVacuumPumpRun : BOOL; // Enable vacuum system
    bLinkerServoEnable : BOOL; // Enable twisting servo
    rLinkerServoSpeed : REAL; // Twisting servo speed
    bCutterEnable : BOOL; // Actuate cutting knife

    bSystemReady : BOOL; // System ready for production
    bFault : BOOL; // General fault indicator
    iErrorCode : INT; // Error code (0 = No Error, 1 = E-Stop, 2 = No Casing, 3 = Vacuum Fault, 4 = Weight Tolerance)
END_VAR

VAR
    iState : INT := 0; // State machine state
    rWeightError : REAL;
    rIntegral : REAL := 0.0;
    rDerivative : REAL := 0.0;
    rLastError : REAL := 0.0;

    // PID tuning parameters for pump speed
    Kp : REAL := 2.5;
    Ki : REAL := 0.1;
    Kd : REAL := 0.05;

    tTimer : TON; // General purpose timer
    tTwistTimer : TON; // Twisting timer
END_VAR

// Emergency Stop Check
IF NOT bEStop THEN
    iState := 999; // Fault state
    bFault := TRUE;
    iErrorCode := 1;
END_IF;

// Main State Machine
CASE iState OF
    0: // Idle
        bSystemReady := TRUE;
        bPumpRun := FALSE;
        bVacuumPumpRun := FALSE;
        bLinkerServoEnable := FALSE;
        bCutterEnable := FALSE;
        rPumpSpeedRef := 0.0;

        IF bEnable AND bStartCycle AND bCasingPresent THEN
            bSystemReady := FALSE;
            bFault := FALSE;
            iErrorCode := 0;
            iState := 10;
        ELSIF bEnable AND bStartCycle AND NOT bCasingPresent THEN
            bFault := TRUE;
            iErrorCode := 2;
        END_IF;

    10: // Vacuum Generation
        bVacuumPumpRun := TRUE;
        IF rVacuumLevel <= rTargetVacuum THEN
            iState := 20;
        END_IF;

    20: // Stuffing / Pumping (PID control for exact weight)
        bPumpRun := TRUE;
        rWeightError := rTargetWeight - rActualWeight;

        // PID Calculation
        rIntegral := rIntegral + rWeightError;
        rDerivative := rWeightError - rLastError;
        rPumpSpeedRef := (Kp * rWeightError) + (Ki * rIntegral) + (Kd * rDerivative);

        // Clamp output
        IF rPumpSpeedRef > 100.0 THEN
            rPumpSpeedRef := 100.0;
        ELSIF rPumpSpeedRef < 0.0 THEN
            rPumpSpeedRef := 0.0;
        END_IF;

        rLastError := rWeightError;

        IF rActualWeight >= rTargetWeight THEN
            bPumpRun := FALSE;
            rPumpSpeedRef := 0.0;
            iState := 30;
        END_IF;

    30: // Linking / Twisting
        bLinkerServoEnable := TRUE;
        rLinkerServoSpeed := 50.0; // 50% speed for twist

        tTwistTimer(IN:=TRUE, PT:=T#500MS);

        IF tTwistTimer.Q THEN
            tTwistTimer(IN:=FALSE);
            bLinkerServoEnable := FALSE;
            rLinkerServoSpeed := 0.0;
            iState := 40;
        END_IF;

    40: // Cutting (Optional)
        bCutterEnable := TRUE;
        tTimer(IN:=TRUE, PT:=T#200MS);

        IF tTimer.Q THEN
            tTimer(IN:=FALSE);
            bCutterEnable := FALSE;
            iState := 0; // Return to idle for next cycle
        END_IF;

    999: // Fault
        bSystemReady := FALSE;
        bPumpRun := FALSE;
        bVacuumPumpRun := FALSE;
        bLinkerServoEnable := FALSE;
        bCutterEnable := FALSE;
        rPumpSpeedRef := 0.0;

        IF bEStop AND NOT bStartCycle THEN // Reset condition
            iState := 0;
            bFault := FALSE;
            iErrorCode := 0;
        END_IF;

END_CASE;
END_FUNCTION_BLOCK
