FUNCTION_BLOCK FB_EUV_Reticle_MagLev_6DOF
VAR_INPUT
    bEnablePower            : BOOL;     (* System master enable *)
    bEstopOK                : BOOL;     (* Safety circuit loop OK *)
    bVacuumReady            : BOOL;     (* Main chamber vacuum at target mTorr *)
    bInterferometerOK       : BOOL;     (* Metrology frame alignment lasers valid *)
    rSetpointX_nm           : LREAL;    (* X-axis position setpoint in nanometers *)
    rSetpointY_nm           : LREAL;    (* Y-axis position setpoint in nanometers *)
    rSetpointZ_nm           : LREAL;    (* Z-axis position setpoint in nanometers *)
    rActualX_nm             : LREAL;    (* Current X position from laser interferometer *)
    rActualY_nm             : LREAL;    (* Current Y position from laser interferometer *)
    rActualZ_nm             : LREAL;    (* Current Z position from laser interferometer *)
    rScanVelocity_mms       : LREAL;    (* Requested Y-axis scan velocity mm/sec *)
    rFeedForwardForce_N     : LREAL;    (* Pre-calculated feed-forward force *)
END_VAR
VAR_OUTPUT
    bSystemReady            : BOOL;     (* All subsystems initialized and stable *)
    bScanningActive         : BOOL;     (* Reticle is actively scanning at constant velocity *)
    bTrackingErrorAlarm     : BOOL;     (* Dynamic tracking error exceeded nanometer limits *)
    rForceCommandX_N        : LREAL;    (* Output force vector X-axis to linear motor amplifiers *)
    rForceCommandY_N        : LREAL;    (* Output force vector Y-axis to linear motor amplifiers *)
    rForceCommandZ_N        : LREAL;    (* Output force vector Z-axis to linear motor amplifiers *)
    iStateWord              : INT;      (* Internal state machine status for upper level host *)
END_VAR
VAR
    iState                  : INT := 0; (* 0: Init, 10: Levitate, 20: Servo, 30: Scan, 99: Fault *)
    tScanTimeout            : TON;
    tSettleTimer            : TON;
    rErrorX                 : LREAL;
    rErrorY                 : LREAL;
    rErrorZ                 : LREAL;

    (* PID Controller variables for 6-DOF decoupled axes *)
    rKp_XY                  : LREAL := 150000.0; (* Proportional gain N/nm *)
    rKd_XY                  : LREAL := 25000.0;  (* Derivative gain N/(nm/s) *)
    rKi_XY                  : LREAL := 5000.0;   (* Integral gain N/(nm*s) *)

    rIntegralX              : LREAL := 0.0;
    rIntegralY              : LREAL := 0.0;
    rIntegralZ              : LREAL := 0.0;

    rLastErrorX             : LREAL := 0.0;
    rLastErrorY             : LREAL := 0.0;
    rLastErrorZ             : LREAL := 0.0;

    rCycleTime_s            : LREAL := 0.0001; (* 10kHz servo update rate *)

    rTrackingErrorLimit     : LREAL := 5.0; (* 5 nanometers dynamic limit *)
    bFault                  : BOOL := FALSE;
END_VAR

(* === MAIN EUV RETICLE SCANNER LOGIC === *)
(* 1. Safety and Interlock Check *)
IF NOT bEstopOK OR NOT bVacuumReady OR NOT bInterferometerOK THEN
    bSystemReady := FALSE;
    bScanningActive := FALSE;
    rForceCommandX_N := 0.0;
    rForceCommandY_N := 0.0;
    rForceCommandZ_N := 0.0;
    iState := 99; (* Fault state *)
    bFault := TRUE;
    iStateWord := iState;
    RETURN;
END_IF;

(* 2. Dynamic State Machine *)
CASE iState OF
    0: (* INIT - Waiting for Master Enable *)
        bSystemReady := FALSE;
        bScanningActive := FALSE;
        bTrackingErrorAlarm := FALSE;
        rIntegralX := 0.0;
        rIntegralY := 0.0;
        rIntegralZ := 0.0;
        IF bEnablePower AND NOT bFault THEN
            iState := 10;
        END_IF;

    10: (* LEVITATE - Z-axis magnetic levitation engagement *)
        (* Basic Z-axis proportional-derivative control to capture the stage *)
        rErrorZ := rSetpointZ_nm - rActualZ_nm;
        rForceCommandZ_N := (rErrorZ * rKp_XY) + ((rErrorZ - rLastErrorZ)/rCycleTime_s * rKd_XY);
        rLastErrorZ := rErrorZ;

        IF ABS(rErrorZ) < 50.0 THEN (* Stage captured within 50nm of zero plane *)
            tSettleTimer(IN := TRUE, PT := T#200MS);
            IF tSettleTimer.Q THEN
                tSettleTimer(IN := FALSE);
                iState := 20;
            END_IF;
        ELSE
            tSettleTimer(IN := FALSE);
        END_IF;

    20: (* SERVO - Full 3D PID position lock (simplified from 6DOF) *)
        bSystemReady := TRUE;

        rErrorX := rSetpointX_nm - rActualX_nm;
        rErrorY := rSetpointY_nm - rActualY_nm;
        rErrorZ := rSetpointZ_nm - rActualZ_nm;

        (* Integrate *)
        rIntegralX := rIntegralX + (rErrorX * rCycleTime_s);
        rIntegralY := rIntegralY + (rErrorY * rCycleTime_s);
        rIntegralZ := rIntegralZ + (rErrorZ * rCycleTime_s);

        (* Calculate Forces N *)
        rForceCommandX_N := (rErrorX * rKp_XY) + (rIntegralX * rKi_XY) + ((rErrorX - rLastErrorX)/rCycleTime_s * rKd_XY);
        rForceCommandY_N := (rErrorY * rKp_XY) + (rIntegralY * rKi_XY) + ((rErrorY - rLastErrorY)/rCycleTime_s * rKd_XY);
        rForceCommandZ_N := (rErrorZ * rKp_XY) + (rIntegralZ * rKi_XY) + ((rErrorZ - rLastErrorZ)/rCycleTime_s * rKd_XY);

        rLastErrorX := rErrorX;
        rLastErrorY := rErrorY;
        rLastErrorZ := rErrorZ;

        IF rScanVelocity_mms > 0.1 THEN
            iState := 30; (* Transition to synchronous scanning *)
        END_IF;

        IF NOT bEnablePower THEN
            iState := 0;
        END_IF;

    30: (* SCAN - High dynamic trajectory tracking with Feed-Forward *)
        bScanningActive := TRUE;

        rErrorX := rSetpointX_nm - rActualX_nm;
        rErrorY := rSetpointY_nm - rActualY_nm;
        rErrorZ := rSetpointZ_nm - rActualZ_nm;

        (* Tracking error monitor during wafer exposure *)
        IF ABS(rErrorY) > rTrackingErrorLimit OR ABS(rErrorX) > rTrackingErrorLimit THEN
            bTrackingErrorAlarm := TRUE;
            iState := 99; (* Abort scan to protect yield *)
        END_IF;

        (* Control Law = PID + Acceleration FeedForward *)
        rForceCommandY_N := (rErrorY * rKp_XY) + ((rErrorY - rLastErrorY)/rCycleTime_s * rKd_XY) + rFeedForwardForce_N;

        (* X and Z maintain tight regulating lock *)
        rForceCommandX_N := (rErrorX * rKp_XY) + (rIntegralX * rKi_XY) + ((rErrorX - rLastErrorX)/rCycleTime_s * rKd_XY);
        rForceCommandZ_N := (rErrorZ * rKp_XY) + (rIntegralZ * rKi_XY) + ((rErrorZ - rLastErrorZ)/rCycleTime_s * rKd_XY);

        rLastErrorX := rErrorX;
        rLastErrorY := rErrorY;
        rLastErrorZ := rErrorZ;

        IF rScanVelocity_mms < 0.1 THEN
            bScanningActive := FALSE;
            iState := 20; (* Return to static servo *)
        END_IF;

    99: (* FAULT *)
        bSystemReady := FALSE;
        bScanningActive := FALSE;
        rForceCommandX_N := 0.0;
        rForceCommandY_N := 0.0;
        rForceCommandZ_N := 0.0;
        IF NOT bEnablePower THEN
            bFault := FALSE;
            bTrackingErrorAlarm := FALSE;
            iState := 0;
        END_IF;
END_CASE;

iStateWord := iState;

END_FUNCTION_BLOCK
```

