FUNCTION_BLOCK FB_PaintBatchMixer
TITLE = 'Advanced Gravimetric Paint & Tint Mixing Control'
VERSION : 1.0
AUTHOR : 'Lumina Swarm'

VAR_INPUT
    bStartBatch          : BOOL;   (* Start Batch Sequence *)
    bEmergencyStop       : BOOL;   (* E-Stop from HMI or hardwired *)
    bAck                 : BOOL;   (* Acknowledge Alarms *)
    rTargetBaseSolventKg : REAL;   (* Target Base Solvent in Kg *)
    rTargetPigmentAKg    : REAL;   (* Target Pigment A in Kg *)
    rTargetPigmentBKg    : REAL;   (* Target Pigment B in Kg *)
    iTargetDisperserRPM  : INT;    (* Target RPM for High-shear disperser *)
    tMixTime             : TIME;   (* Disperser Mix Duration *)
    rSolventMassFlowRate : REAL;   (* Feedback from Coriolis Mass Flow Meter (kg/s) *)
    rPigmentA_Weight     : REAL;   (* Feedback from Load Cell Hopper A (kg) *)
    rPigmentB_Weight     : REAL;   (* Feedback from Load Cell Hopper B (kg) *)
    rTankWeight          : REAL;   (* Feedback from Main Tank Load Cell (kg) *)
END_VAR

VAR_OUTPUT
    bSolventValve        : BOOL;   (* Output to Base Solvent Valve *)
    bPigmentA_Feeder     : BOOL;   (* Output to Pigment A Screw Feeder *)
    bPigmentB_Feeder     : BOOL;   (* Output to Pigment B Screw Feeder *)
    iDisperserVFD_Cmd    : INT;    (* VFD Speed Command 0-100% mapped to RPM *)
    bBatchComplete       : BOOL;   (* Batch Cycle Complete *)
    bAlarm               : BOOL;   (* System in Alarm State *)
    sStatusMsg           : STRING[50]; (* HMI Status Message *)
END_VAR

VAR
    iState               : INT := 0; (* State Machine Index *)
    rSolventTotalized    : REAL := 0.0;
    rStartWeightA        : REAL := 0.0;
    rStartWeightB        : REAL := 0.0;
    MixTimer             : TON;
    CycleTimer           : TON;
    bFirstPass           : BOOL := TRUE;
    rTolerance           : REAL := 0.05; (* 50g tolerance *)
END_VAR

(* STATE MACHINE DEFINITION
   0: IDLE
   10: DOSE_SOLVENT
   20: DOSE_PIGMENT_A
   30: DOSE_PIGMENT_B
   40: DISPERSION_MIXING
   50: COMPLETE
   99: ALARM / E-STOP
*)

IF bEmergencyStop THEN
    iState := 99;
END_IF;

CASE iState OF
    0: (* IDLE *)
        bSolventValve := FALSE;
        bPigmentA_Feeder := FALSE;
        bPigmentB_Feeder := FALSE;
        iDisperserVFD_Cmd := 0;
        bBatchComplete := FALSE;
        bAlarm := FALSE;
        sStatusMsg := 'IDLE: Ready for Batch';

        IF bStartBatch AND NOT bEmergencyStop THEN
            rSolventTotalized := 0.0;
            iState := 10;
        END_IF;

    10: (* DOSE SOLVENT *)
        sStatusMsg := 'DOSING: Base Solvent';
        bSolventValve := TRUE;
        (* Integrate mass flow (simplified integration logic, ideally done via high speed counter or integration FB) *)
        rSolventTotalized := rSolventTotalized + (rSolventMassFlowRate * 0.1); (* Assuming 100ms task cycle *)

        IF rSolventTotalized >= (rTargetBaseSolventKg - rTolerance) THEN
            bSolventValve := FALSE;
            rStartWeightA := rPigmentA_Weight;
            iState := 20;
        END_IF;

    20: (* DOSE PIGMENT A *)
        sStatusMsg := 'DOSING: Pigment A';
        bPigmentA_Feeder := TRUE;

        IF (rStartWeightA - rPigmentA_Weight) >= (rTargetPigmentAKg - rTolerance) THEN
            bPigmentA_Feeder := FALSE;
            rStartWeightB := rPigmentB_Weight;
            iState := 30;
        END_IF;

    30: (* DOSE PIGMENT B *)
        sStatusMsg := 'DOSING: Pigment B';
        bPigmentB_Feeder := TRUE;

        IF (rStartWeightB - rPigmentB_Weight) >= (rTargetPigmentBKg - rTolerance) THEN
            bPigmentB_Feeder := FALSE;
            iState := 40;
        END_IF;

    40: (* DISPERSION MIXING *)
        sStatusMsg := 'MIXING: High-Shear Dispersion Active';
        iDisperserVFD_Cmd := iTargetDisperserRPM; 

        MixTimer(IN := TRUE, PT := tMixTime);
        IF MixTimer.Q THEN
            MixTimer(IN := FALSE); (* Reset Timer *)
            iDisperserVFD_Cmd := 0;
            iState := 50;
        END_IF;

    50: (* COMPLETE *)
        sStatusMsg := 'COMPLETE: Batch Ready for Transfer';
        bBatchComplete := TRUE;
        IF NOT bStartBatch THEN
            iState := 0;
        END_IF;

    99: (* ALARM / E-STOP *)
        bSolventValve := FALSE;
        bPigmentA_Feeder := FALSE;
        bPigmentB_Feeder := FALSE;
        iDisperserVFD_Cmd := 0;
        bAlarm := TRUE;
        sStatusMsg := 'ALARM: System Stopped';

        IF bAck AND NOT bEmergencyStop THEN
            iState := 0;
        END_IF;

    ELSE
        iState := 99;
END_CASE;

END_FUNCTION_BLOCK
