FUNCTION_BLOCK "Lyophilizer_Mut2"
VAR_INPUT
    Start : Bool;
    Stop : Bool;
    StartDefrost : Bool;
    VacuumSetPoint : Real;
    TempSetPoint : Real;
    ActualVacuum : Real;
    ActualTemp : Real;
    CondenserTemp : Real;
    PN_Comm_OK : Bool;
    RemoteStart : Bool;
END_VAR
VAR_OUTPUT
    VacuumValveControl : Real;
    HeaterControl : Real;
    CoolingControl : Real;
    DefrostHeater : Bool;
    DrainValve : Bool;
    Fault_Active : Bool;
    Fault_Code : Int;
END_VAR
VAR
    PID_Vacuum : "PID_Compact";
    PID_Temp : "PID_Compact";
    State : Int;
    DefrostTimer : TON;
END_VAR

BEGIN
    Fault_Active := FALSE;
    Fault_Code := 0;

    IF NOT PN_Comm_OK THEN
        Fault_Active := TRUE;
        Fault_Code := 101;
    END_IF;
    IF ActualTemp > 100.0 THEN
        Fault_Active := TRUE;
        Fault_Code := 201;
    END_IF;

    IF Fault_Active THEN
        State := 99;
    ELSIF Stop THEN
        State := 0;
    ELSIF (Start OR RemoteStart) AND State = 0 THEN
        State := 1;
    ELSIF StartDefrost AND State = 0 THEN
        State := 2;
    END_IF;

    CASE State OF
        0:
            VacuumValveControl := 0.0;
            HeaterControl := 0.0;
            CoolingControl := 0.0;
            DefrostHeater := FALSE;
            DrainValve := FALSE;
        1:
            PID_Vacuum(Setpoint:=VacuumSetPoint, Input:=ActualVacuum, Output=>VacuumValveControl);
            PID_Temp(Setpoint:=TempSetPoint, Input:=ActualTemp, Output=>HeaterControl);
            CoolingControl := 100.0 - HeaterControl;
            DefrostHeater := FALSE;
            DrainValve := FALSE;
        2:
            DefrostHeater := TRUE;
            DrainValve := TRUE;
