FUNCTION_BLOCK FB_HIFU_AblationArray
(*
    Advanced Biomedical High-Intensity Focused Ultrasound (HIFU) Ablation Array Controller
    Features:
    - Phased-array focal point electronic steering
    - MRI-guided tissue cavitation real-time feedback integration
    - Piezoelectric transducer fluid-coupled thermal management
    - Real-time dose and cavitation energy calculation
*)
VAR_INPUT
    bEnable                 : BOOL;     (* System master enable signal *)
    bEmergencyStop          : BOOL;     (* Safety relay OK signal - Active HIGH *)
    rMRI_TemperatureMap     : REAL;     (* Current peak tissue temperature from MRI thermometry [deg C] *)
    rCavitationAcousticSig  : REAL;     (* Passive acoustic mapping of cavitation [mV] *)
    rCouplingFluidFlow      : REAL;     (* Coupling fluid flow rate [L/min] *)
    rCouplingFluidTemp      : REAL;     (* Coupling fluid return temperature [deg C] *)
    rTargetX                : REAL;     (* Electronic steering target X coordinate [mm] *)
    rTargetY                : REAL;     (* Electronic steering target Y coordinate [mm] *)
    rTargetZ                : REAL;     (* Electronic steering target Z coordinate [mm] *)
    rRequestedPower         : REAL;     (* Requested ablation power per element [W] *)
END_VAR

VAR_OUTPUT
    bSystemReady            : BOOL;     (* System ready for ablation status *)
    rPowerOutputSetpt       : REAL;     (* Calculated RF power output to transducers [W] *)
    rPhaseShiftX            : REAL;     (* Phased-array phase shift for X steering [rad] *)
    rPhaseShiftY            : REAL;     (* Phased-array phase shift for Y steering [rad] *)
    rChillerPumpCmd         : REAL;     (* Command to fluid coupling chiller pump [0-100%] *)
    bAblationActive         : BOOL;     (* Active ablation indicator *)
    bCavitationWarning      : BOOL;     (* High cavitation risk warning *)
    bCriticalAlarm          : BOOL;     (* System fault alarm output *)
END_VAR

VAR
    iState                  : INT := 0; (* State machine variable *)
    tAblationTimer          : TON;      (* Timer for ablation pulse duration *)
    rFilteredCavitation     : REAL := 0.0; (* Low-pass filtered cavitation signal *)
    rThermalDose            : REAL := 0.0; (* Cumulative thermal dose [CEM43] *)
    rPhaseBaseFreq          : REAL := 1.2e6; (* 1.2 MHz base frequency *)
    tCooldownTimer          : TON;      (* Cooldown period timer *)

    (* Filter Constants *)
    rAlpha                  : REAL := 0.15; (* EMA filter coefficient *)
    rMaxTemp                : REAL := 95.0; (* Max allowable tissue temp [deg C] *)
    rCavThreshold           : REAL := 15.0; (* Cavitation warning threshold [mV] *)
END_VAR

(* === MAIN LOGIC === *)
(* 1. Safety Interlocks & Emergency Stop *)
IF NOT bEmergencyStop THEN
    bSystemReady := FALSE;
    bAblationActive := FALSE;
    bCriticalAlarm := TRUE;
    rPowerOutputSetpt := 0.0;
    rChillerPumpCmd := 100.0; (* Max cooling during E-Stop *)
    iState := 99; (* Fault state *)
    RETURN;
END_IF;

(* 2. Signal Processing *)
(* Exponential Moving Average filter for cavitation noise *)
rFilteredCavitation := (rAlpha * rCavitationAcousticSig) + ((1.0 - rAlpha) * rFilteredCavitation);

(* Cavitation threshold monitoring *)
IF rFilteredCavitation > rCavThreshold THEN
    bCavitationWarning := TRUE;
ELSE
    bCavitationWarning := FALSE;
END_IF;

(* Continuous Thermal Management of Transducer Coupling Fluid *)
IF rCouplingFluidTemp > 25.0 THEN
    rChillerPumpCmd := 100.0;
ELSIF rCouplingFluidTemp > 18.0 THEN
    rChillerPumpCmd := 50.0 + (rCouplingFluidTemp - 18.0) * (50.0 / 7.0);
ELSE
    rChillerPumpCmd := 20.0; (* Minimum maintenance flow *)
END_IF;

(* Flow loss detection *)
IF rCouplingFluidFlow < 0.5 AND iState >= 10 THEN
    bCriticalAlarm := TRUE;
    iState := 99;
END_IF;

(* 3. State Machine *)
CASE iState OF
    0: (* IDLE / INITIALIZATION *)
        bSystemReady := FALSE;
        bAblationActive := FALSE;
        rPowerOutputSetpt := 0.0;
        bCriticalAlarm := FALSE;
        rThermalDose := 0.0;

        IF bEnable AND rCouplingFluidFlow >= 1.0 AND rCouplingFluidTemp < 22.0 THEN
            iState := 10;
        END_IF;

    10: (* READY *)
        bSystemReady := TRUE;

        (* Calculate Steering Phase Shifts based on target coordinates *)
        (* Simplified far-field approximation for focal point targeting *)
        rPhaseShiftX := rTargetX * 0.052; 
        rPhaseShiftY := rTargetY * 0.052;

        IF bEnable AND rRequestedPower > 0.0 AND NOT bCavitationWarning THEN
            iState := 20;
        ELSIF NOT bEnable THEN
            iState := 0;
        END_IF;

    20: (* ABLATION ACTIVE *)
        bAblationActive := TRUE;

        (* Temperature-based Power Regulation (PID approximation) *)
        IF rMRI_TemperatureMap > rMaxTemp THEN
            (* Tissue boiling risk, shut down power immediately *)
            rPowerOutputSetpt := 0.0;
            iState := 30;
        ELSIF rMRI_TemperatureMap > 80.0 THEN
            (* Power foldback to maintain steady-state ablation *)
            rPowerOutputSetpt := rRequestedPower * 0.5;
        ELSE
            (* Full requested power *)
            rPowerOutputSetpt := rRequestedPower;
        END_IF;

        (* Cavitation override *)
        IF bCavitationWarning THEN
            rPowerOutputSetpt := rRequestedPower * 0.2; (* Drop to sub-cavitating diagnostic level *)
        END_IF;

        tAblationTimer(IN := TRUE, PT := T#10S);
        IF tAblationTimer.Q THEN
            tAblationTimer(IN := FALSE);
            iState := 30;
        END_IF;

        IF NOT bEnable THEN
            iState := 30;
        END_IF;

    30: (* COOLDOWN *)
        bAblationActive := FALSE;
        rPowerOutputSetpt := 0.0;
        tAblationTimer(IN := FALSE);

        tCooldownTimer(IN := TRUE, PT := T#5S);
        IF tCooldownTimer.Q THEN
            tCooldownTimer(IN := FALSE);
            iState := 0;
        END_IF;

    99: (* FAULT / ESTOP RECOVERY *)
        bSystemReady := FALSE;
        bAblationActive := FALSE;
        rPowerOutputSetpt := 0.0;

        IF bEmergencyStop AND bEnable = FALSE AND rCouplingFluidFlow >= 1.0 THEN
            bCriticalAlarm := FALSE;
            iState := 0;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
