FUNCTION_BLOCK FB_FischerTropschReactor
(* ==============================================================================
   Title:           FB_FischerTropschReactor
   Author:          Lumina Elite Synthetic Data Architect (40-Yr Automation Vet)
   Version:         1.0.0.0
   Description:     Ultra-realistic Industrial Scale Coal-to-Liquid (CTL) 
                    Fischer-Tropsch Synthesis Reactor Control.
                    Handles Cobalt catalyst slurry bubbling bed density mapping, 
                    syngas (H2/CO) partial pressure dynamic ratio control, 
                    and highly exothermic heat removal via steam drum integration.
   ============================================================================== *)
VAR_INPUT
    bEnable                 : BOOL;     (* System master enable signal *)
    bEmergencyStop          : BOOL;     (* Safety relay OK signal (Active HIGH) *)
    rSyngasFlowH2           : REAL;     (* Measured H2 gas mass flow rate [kg/hr] *)
    rSyngasFlowCO           : REAL;     (* Measured CO gas mass flow rate [kg/hr] *)
    rReactorTemp1           : REAL;     (* Reactor internal temperature zone 1 [deg C] *)
    rReactorTemp2           : REAL;     (* Reactor internal temperature zone 2 [deg C] *)
    rReactorPressure        : REAL;     (* Reactor absolute operating pressure [bar] *)
    rCatalystSlurryDensity  : REAL;     (* Density of Co catalyst slurry bed [kg/m^3] *)
    rSteamDrumLevel         : REAL;     (* Cooling water steam drum level [%] *)
END_VAR
VAR_OUTPUT
    bSystemReady            : BOOL;     (* Reactor is stable and ready for full capacity *)
    rSyngasRatioValve       : REAL;     (* Control signal to H2/CO ratio adjustment valve [%] *)
    rCoolingWaterFlow       : REAL;     (* Control signal to BFW (Boiler Feed Water) pump [%] *)
    rSteamVentValve         : REAL;     (* Steam drum vent valve to manage pressure/temp [%] *)
    bAlarmHighTemp          : BOOL;     (* High temperature trip alarm *)
    bAlarmRatioDev          : BOOL;     (* Syngas H2/CO ratio deviation alarm *)
    iReactorState           : INT;      (* Current operating state machine step *)
END_VAR
VAR
    (* Internal state variables *)
    iState                  : INT := 0; (* 0: IDLE, 10: PURGE, 20: HEATING, 30: SYNTHESIS, 40: SHUTDOWN *)
    tStateTimer             : TON;
    tPurgeTimer             : TON;

    (* Internal process variables *)
    rCalculatedRatio        : REAL;
    rTargetRatio            : REAL := 2.05; (* Ideal H2/CO stoichiometric ratio for Co FT *)
    rAvgTemp                : REAL;
    rTempSetpoint           : REAL := 220.0; (* FT optimal temp [deg C] *)

    (* PID Controllers (Simulated for this FB) *)
    rRatioError             : REAL;
    rRatioIntegral          : REAL;
    rTempError              : REAL;
    rTempIntegral           : REAL;

    (* Constraints and Constants *)
    MAX_TEMP                : REAL := 245.0;
    CRITICAL_TEMP           : REAL := 260.0;
END_VAR

(* === MAIN LOGIC === *)
(* Emergency Interlocks and Safety Constraints *)
IF NOT bEmergencyStop THEN
    bSystemReady := FALSE;
    rSyngasRatioValve := 0.0;
    rCoolingWaterFlow := 100.0; (* Max cooling during emergency *)
    rSteamVentValve := 100.0;   (* Depressurize drum *)
    iState := 0;                (* Force to IDLE / SAFE state *)
    iReactorState := -1;        (* -1 indicates FAULT *)
    RETURN;
END_IF;

(* Process Variable Calculations *)
IF rSyngasFlowCO > 0.1 THEN
    rCalculatedRatio := rSyngasFlowH2 / rSyngasFlowCO;
ELSE
    rCalculatedRatio := 0.0;
END_IF;

rAvgTemp := (rReactorTemp1 + rReactorTemp2) / 2.0;

(* Alarm Monitoring *)
IF rAvgTemp > MAX_TEMP THEN
    bAlarmHighTemp := TRUE;
ELSE
    bAlarmHighTemp := FALSE;
END_IF;

IF ABS(rCalculatedRatio - rTargetRatio) > 0.15 AND iState = 30 THEN
    bAlarmRatioDev := TRUE;
ELSE
    bAlarmRatioDev := FALSE;
END_IF;

(* Critical Temperature Trip Override *)
IF rAvgTemp >= CRITICAL_TEMP THEN
    iState := 40; (* Force SHUTDOWN *)
END_IF;

(* State Machine Control *)
CASE iState OF
    0: (* IDLE *)
        bSystemReady := FALSE;
        rSyngasRatioValve := 0.0;
        rCoolingWaterFlow := 0.0;
        rSteamVentValve := 0.0;
        IF bEnable THEN
            iState := 10;
        END_IF;

    10: (* PURGE / PRE-CONDITIONING *)
        bSystemReady := FALSE;
        (* Execute N2 Purge logic (abstracted) *)
        tPurgeTimer(IN := TRUE, PT := T#30S);
        IF tPurgeTimer.Q THEN
            tPurgeTimer(IN := FALSE);
            iState := 20;
        END_IF;

    20: (* HEATING & PRESSURIZING *)
        bSystemReady := FALSE;
        rCoolingWaterFlow := 10.0; (* Minimum flow to prevent dry drum *)
        IF rAvgTemp > (rTempSetpoint - 20.0) AND rReactorPressure > 15.0 THEN
            iState := 30;
        END_IF;
        IF NOT bEnable THEN
            iState := 40;
        END_IF;

    30: (* SYNTHESIS (MAIN OPERATION) *)
        bSystemReady := TRUE;

        (* 1. Syngas Ratio Control (PI Control simulation) *)
        rRatioError := rTargetRatio - rCalculatedRatio;
        rRatioIntegral := rRatioIntegral + (rRatioError * 0.1);
        rSyngasRatioValve := (rRatioError * 20.0) + rRatioIntegral + 50.0; 

        (* Limit valve output *)
        IF rSyngasRatioValve > 100.0 THEN rSyngasRatioValve := 100.0; END_IF;
        IF rSyngasRatioValve < 0.0 THEN rSyngasRatioValve := 0.0; END_IF;

        (* 2. Highly Exothermic Heat Removal Control *)
        rTempError := rAvgTemp - rTempSetpoint;
        rTempIntegral := rTempIntegral + (rTempError * 0.05);
        rCoolingWaterFlow := (rTempError * 5.0) + rTempIntegral + 30.0;

        (* Limit cooling flow *)
        IF rCoolingWaterFlow > 100.0 THEN rCoolingWaterFlow := 100.0; END_IF;
        IF rCoolingWaterFlow < 0.0 THEN rCoolingWaterFlow := 0.0; END_IF;

        (* Steam Drum Level/Pressure override logic *)
        IF rSteamDrumLevel > 80.0 THEN
            rSteamVentValve := 100.0;
        ELSIF rSteamDrumLevel < 20.0 THEN
            rCoolingWaterFlow := rCoolingWaterFlow * 1.5; (* Force more feed water *)
            rSteamVentValve := 0.0;
        ELSE
            rSteamVentValve := rCoolingWaterFlow * 0.8;
        END_IF;

        IF NOT bEnable THEN
            iState := 40;
        END_IF;

    40: (* SHUTDOWN *)
        bSystemReady := FALSE;
        rSyngasRatioValve := 0.0;
        rCoolingWaterFlow := 50.0; (* Maintain cooling during cooldown *)
        rSteamVentValve := 50.0;

        tStateTimer(IN := TRUE, PT := T#60S);
        IF tStateTimer.Q THEN
            tStateTimer(IN := FALSE);
            iState := 0;
        END_IF;

END_CASE;

iReactorState := iState;

END_FUNCTION_BLOCK
