FUNCTION_BLOCK FB_Optomechanics_Superposition
VAR_INPUT
    bEnable                  : BOOL; // Enable the optomechanics controller
    bExecuteSuperposition    : BOOL; // Trigger spatial superposition sequence

    // Laser and Cavity Inputs
    fCavityResonanceFreq     : LREAL; // [Hz] Optical cavity resonance frequency
    fLaserFreqFeedback       : LREAL; // [Hz] Measured laser frequency from PDH error signal
    fNanoparticlePosZ        : LREAL; // [m] Measured Z-position of nanoparticle via balanced detection
    fTrapDepth               : LREAL; // [W] Current optical trap depth power

    // Quantum & Environmental Parameters
    fTargetGroundStateTemp   : LREAL := 1E-6; // [K] Target temp for ground state cooling
    fMassSilica              : LREAL := 3E-18; // [kg] Mass of 100nm silica nanoparticle
    fMechOmegaZ              : LREAL := 314159.0; // [rad/s] Mechanical trapping frequency in Z (~50 kHz)
END_VAR

VAR_OUTPUT
    // Laser Actuation
    fLaserFreqSetpoint       : LREAL; // [Hz] Actuation to laser piezo/AOM for PDH lock
    fLaserPowerSetpoint      : LREAL; // [W] Actuation to trapping laser power (AOM)
    fFeedbackForce           : LREAL; // [N] Coherent scattering feedback force applied

    // Superposition Pulses
    bSecondaryPulseTrigger   : BOOL; // Trigger for non-linear cubic phase measurement laser

    // Status
    ePackMLState             : E_PackML_State; // Current PackML State
    bGroundStateReached      : BOOL; // TRUE if T < 1uK
    bSuperpositionActive     : BOOL; // TRUE during wavefunction expansion
    fCurrentPhononNumber     : LREAL; // Estimated mean phonon number in Z-axis
    bError                   : BOOL;
    sErrorMsg                : STRING;
END_VAR

VAR
    // PDH Lock PI Controller
    fbPDH_PI                 : FB_PI_Controller;

    // Cooling Feedback variables
    fVelocityZ               : LREAL;
    fPrevPosZ                : LREAL;
    fDampingGamma            : LREAL; // Active damping rate

    // Superposition Sequence Timer
    fbSuperpositionTimer     : TON;
    nSuperpositionStep       : INT;

    // Constants
    fPlanck_bar              : LREAL := 1.054571817E-34; // [J*s] Reduced Planck constant
    fBoltzmann               : LREAL := 1.380649E-23; // [J/K] Boltzmann constant

    // Internal States
    bInitialized             : BOOL := FALSE;
    tCycleTime               : LREAL := 0.0001; // [s] 100us cycle time assumed
END_VAR

// Initialization
IF NOT bInitialized THEN
    fbPDH_PI.Kp := 1.5;
    fbPDH_PI.Ki := 500.0;
    fbPDH_PI.UpperLimit := 1E9; // Max freq shift
    fbPDH_PI.LowerLimit := -1E9;
    ePackMLState := E_PackML_State.STOPPED;
    bInitialized := TRUE;
END_IF

// PackML State Machine
CASE ePackMLState OF
    E_PackML_State.STOPPED:
        fLaserFreqSetpoint := 0.0;
        fLaserPowerSetpoint := 0.0;
        fFeedbackForce := 0.0;
        bSecondaryPulseTrigger := FALSE;
        IF bEnable THEN
            ePackMLState := E_PackML_State.STARTING;
        END_IF

    E_PackML_State.STARTING:
        // Initialize trap and PDH lock
        fLaserPowerSetpoint := 0.5; // Nominal 0.5W trap depth
        IF fTrapDepth > 0.45 THEN
            ePackMLState := E_PackML_State.EXECUTE;
        END_IF

    E_PackML_State.EXECUTE:
        IF NOT bEnable THEN
            ePackMLState := E_PackML_State.STOPPING;
        END_IF

        // ------------------------------------------------------------------
        // 1. Cavity Optomechanical Cooling (PDH Lock & Coherent Scattering)
        // ------------------------------------------------------------------
        // PDH Lock: Keep laser resonant with cavity
        fbPDH_PI(
            Setpoint := fCavityResonanceFreq,
            ProcessVariable := fLaserFreqFeedback,
            CycleTime := tCycleTime,
            Output => fLaserFreqSetpoint
        );

        // Differentiate position to get velocity (simple Euler, assuming fast cycle)
        fVelocityZ := (fNanoparticlePosZ - fPrevPosZ) / tCycleTime;
        fPrevPosZ := fNanoparticlePosZ;

        // Cold Damping / Coherent Scattering feedback force
        // F_fb = - m * gamma_active * v
        fDampingGamma := 5000.0; // Optimized active damping rate [Hz]
        fFeedbackForce := -1.0 * fMassSilica * fDampingGamma * fVelocityZ;

        // Modulate Trap Power slightly to apply the feedback force (Optical gradient force)
        // Power fluctuation dP proportional to requested Force
        fLaserPowerSetpoint := 0.5 + (fFeedbackForce * 1E9); // Scaling factor to W

        // Estimate Mean Phonon Number and Temperature (assuming equipartition near ground state)
        // E = 0.5 * m * w^2 * <z^2> + 0.5 * m * <v^2>
        // Phonon number n = E / (hbar * w)
        fCurrentPhononNumber := (0.5 * fMassSilica * (fMechOmegaZ * fMechOmegaZ) * (fNanoparticlePosZ * fNanoparticlePosZ) 
                              + 0.5 * fMassSilica * (fVelocityZ * fVelocityZ)) / (fPlanck_bar * fMechOmegaZ);

        bGroundStateReached := (fCurrentPhononNumber < 1.0); // Ground state reached if <n> < 1

        // ------------------------------------------------------------------
        // 2. Macroscopic Superposition Preparation (Non-linear sequence)
        // ------------------------------------------------------------------
        IF bExecuteSuperposition AND bGroundStateReached AND NOT bSuperpositionActive THEN
            bSuperpositionActive := TRUE;
            nSuperpositionStep := 1;
            fbSuperpositionTimer(IN := FALSE);
        END_IF

        IF bSuperpositionActive THEN
            CASE nSuperpositionStep OF
                1: // Drop trap depth to expand wavefunction freely
                    fLaserPowerSetpoint := 0.01; // Drop to 10mW
                    fbSuperpositionTimer(IN := TRUE, PT := T#50US);
                    IF fbSuperpositionTimer.Q THEN
                        fbSuperpositionTimer(IN := FALSE);
                        nSuperpositionStep := 2;
                    END_IF

                2: // Non-linear cubic phase measurement pulse (Secondary laser)
                    bSecondaryPulseTrigger := TRUE;
                    fbSuperpositionTimer(IN := TRUE, PT := T#10US); // 10us pulse
                    IF fbSuperpositionTimer.Q THEN
                        bSecondaryPulseTrigger := FALSE;
                        fbSuperpositionTimer(IN := FALSE);
                        nSuperpositionStep := 3;
                    END_IF

                3: // Recapture and Interference observation
                    fLaserPowerSetpoint := 0.5; // Restore trap
                    fbSuperpositionTimer(IN := TRUE, PT := T#200US);
                    IF fbSuperpositionTimer.Q THEN
                        fbSuperpositionTimer(IN := FALSE);
                        bSuperpositionActive := FALSE; // Sequence complete
                        nSuperpositionStep := 0;
                    END_IF
            END_CASE
        END_IF

    E_PackML_State.STOPPING:
        fLaserPowerSetpoint := 0.0;
        IF fTrapDepth < 0.01 THEN
            ePackMLState := E_PackML_State.STOPPED;
        END_IF

END_CASE
END_FUNCTION_BLOCK
