FUNCTION_BLOCK FB_LH2_ZBO_Storage
VAR_INPUT
    bSystemEnable           : BOOL;     (* Master enable for the ZBO LH2 storage system *)
    bEmergencyStop          : BOOL;     (* SIL-3 rated emergency stop signal (Active Low) *)
    rTankPressure           : REAL;     (* LH2 primary tank pressure [bar] *)
    rTankTemperature        : REAL;     (* LH2 primary tank temperature [K] *)
    rCryocoolerSpeed        : REAL;     (* Brayton cycle cryocooler turbo-expander speed feedback [RPM] *)
    rOrthoParaRatio         : REAL;     (* In-situ mass spec ortho-to-para hydrogen ratio feedback [%] *)
    bMagneticBearingOK      : BOOL;     (* Turbo-expander active magnetic bearing health status *)
END_VAR
VAR_OUTPUT
    bSystemReady            : BOOL;     (* System is initialized and ready for auto-control *)
    bCryocoolerEnable       : BOOL;     (* Command to start the 20K Brayton cycle cryocooler *)
    rCryocoolerSpeedCmd     : REAL;     (* Commanded turbo-expander speed [RPM] *)
    rCatalystHeaterCmd      : REAL;     (* Ortho-para conversion endothermic compensation heater command [%] *)
    bCriticalAlarm          : BOOL;     (* High-priority fault, triggers automatic isolation *)
    bVentValveOpen          : BOOL;     (* Emergency boil-off venting valve command *)
END_VAR
VAR
    iState                  : INT := 0; (* System state machine state *)
    rFilteredPressure       : REAL;     (* First-order low pass filtered tank pressure *)
    rFilteredTemp           : REAL;     (* First-order low pass filtered tank temperature *)
    rPressureError          : REAL;     (* Tank pressure error vs setpoint *)
    tStartupDelay           : TON;      (* Cryocooler start delay timer *)
    tAlarmDelay             : TON;      (* Transient alarm suppression timer *)

    (* Constants & Parameters *)
    c_rPressureSetpoint     : REAL := 1.2;  (* Target LH2 tank pressure [bar] *)
    c_rTempSetpoint         : REAL := 20.3; (* Target LH2 tank temperature [K] *)
    c_rMaxPressure          : REAL := 2.5;  (* Absolute maximum safe pressure [bar] *)
    c_rAlphaFilter          : REAL := 0.1;  (* Low-pass filter coefficient *)
    c_rKp_Cryo              : REAL := 500.0; (* Proportional gain for cryocooler speed control *)
    c_rKi_Cryo              : REAL := 10.0;  (* Integral gain for cryocooler speed control *)

    (* Integral accumulators *)
    rIntegralAccumulator    : REAL := 0.0;
END_VAR

(* === MAIN LOGIC === *)

(* Safety and Interlocks Check *)
IF NOT bEmergencyStop THEN
    (* Fail-safe state on E-Stop *)
    bSystemReady := FALSE;
    bCryocoolerEnable := FALSE;
    rCryocoolerSpeedCmd := 0.0;
    rCatalystHeaterCmd := 0.0;
    bCriticalAlarm := TRUE;

    (* Open vent valve if pressure exceeds absolute safety limit, even in E-stop, assuming mechanical override not present *)
    IF rTankPressure > c_rMaxPressure THEN
        bVentValveOpen := TRUE;
    ELSE
        bVentValveOpen := FALSE;
    END_IF;

    iState := 0;
    RETURN;
END_IF;

(* Signal Filtering (Noise suppression for cryogenic sensors) *)
rFilteredPressure := (c_rAlphaFilter * rTankPressure) + ((1.0 - c_rAlphaFilter) * rFilteredPressure);
rFilteredTemp := (c_rAlphaFilter * rTankTemperature) + ((1.0 - c_rAlphaFilter) * rFilteredTemp);

(* Overpressure Protection *)
IF rFilteredPressure >= c_rMaxPressure THEN
    tAlarmDelay(IN := TRUE, PT := T#2S);
    IF tAlarmDelay.Q THEN
        bCriticalAlarm := TRUE;
        bVentValveOpen := TRUE;
        iState := 99; (* Fault state *)
    END_IF;
ELSE
    tAlarmDelay(IN := FALSE);
    IF iState <> 99 THEN
        bVentValveOpen := FALSE;
    END_IF;
END_IF;

(* Main State Machine for ZBO Storage Control *)
CASE iState OF
    0: (* IDLE & INITIALIZATION *)
        bSystemReady := FALSE;
        bCryocoolerEnable := FALSE;
        rCryocoolerSpeedCmd := 0.0;
        rCatalystHeaterCmd := 0.0;
        bCriticalAlarm := FALSE;
        rIntegralAccumulator := 0.0;

        IF bSystemEnable AND bMagneticBearingOK THEN
            iState := 10;
        END_IF;

    10: (* STARTUP SEQUENCE *)
        bSystemReady := TRUE;

        (* Evaluate requirement for refrigeration *)
        IF rFilteredPressure > (c_rPressureSetpoint + 0.1) OR rFilteredTemp > (c_rTempSetpoint + 0.2) THEN
            bCryocoolerEnable := TRUE;
            tStartupDelay(IN := TRUE, PT := T#10S);

            IF tStartupDelay.Q THEN
                tStartupDelay(IN := FALSE);
                iState := 20; (* Active Refrigeration Control *)
            END_IF;
        ELSE
            (* Tank is well within margins, no cooling required *)
            iState := 0;
        END_IF;

    20: (* ACTIVE ZBO CONTROL (BRAYTON CYCLE) *)
        (* Check critical systems *)
        IF NOT bMagneticBearingOK THEN
            iState := 99;
        END_IF;

        (* Calculate pressure error for PI control loop *)
        rPressureError := rFilteredPressure - c_rPressureSetpoint;

        (* Anti-windup integration *)
        IF (rCryocoolerSpeedCmd < 120000.0) AND (rCryocoolerSpeedCmd > 0.0) THEN
            rIntegralAccumulator := rIntegralAccumulator + (rPressureError * c_rKi_Cryo);
        END_IF;

        (* Calculate PI output for Turbo-Expander speed (Max 120k RPM) *)
        rCryocoolerSpeedCmd := (rPressureError * c_rKp_Cryo) + rIntegralAccumulator;

        (* Limit speed command *)
        IF rCryocoolerSpeedCmd > 120000.0 THEN
            rCryocoolerSpeedCmd := 120000.0;
        ELSIF rCryocoolerSpeedCmd < 10000.0 THEN
            rCryocoolerSpeedCmd := 10000.0; (* Minimum stable hydrodynamic/magnetic speed *)
        END_IF;

        (* Endothermic Ortho-Para Conversion Compensation Mapping 
           The conversion of ortho-hydrogen to para-hydrogen releases heat.
           If the ratio of ortho is high, more catalyst heating/compensation may be needed
           to stabilize the conversion reactor before re-entering the main tank. *)
        IF rOrthoParaRatio > 5.0 THEN
            rCatalystHeaterCmd := (rOrthoParaRatio - 5.0) * 2.5; (* Proportional compensation *)
            IF rCatalystHeaterCmd > 100.0 THEN
                rCatalystHeaterCmd := 100.0;
            END_IF;
        ELSE
            rCatalystHeaterCmd := 0.0;
        END_IF;

        (* Check if ZBO condition is achieved *)
        IF rFilteredPressure < c_rPressureSetpoint AND rFilteredTemp < c_rTempSetpoint THEN
            (* Cool down complete, return to idle/monitoring *)
            iState := 0;
        END_IF;

        IF NOT bSystemEnable THEN
            iState := 0;
        END_IF;

    99: (* FAULT / CRITICAL SHUTDOWN *)
        bSystemReady := FALSE;
        bCryocoolerEnable := FALSE;
        rCryocoolerSpeedCmd := 0.0;
        rCatalystHeaterCmd := 0.0;
        bCriticalAlarm := TRUE;

        (* Acknowledge fault to clear, provided pressure is safe *)
        IF NOT bSystemEnable AND rFilteredPressure < c_rMaxPressure THEN
            iState := 0;
            bCriticalAlarm := FALSE;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
