FUNCTION_BLOCK FB_HighSpeedCanningLine_CascadeController
TITLE = 'High-Speed Beverage Canning Line - Cascade Control System'
VERSION : '1.2'
AUTHOR : 'Lumina AI Cloud Swarm'

VAR_INPUT
    bEnableSystem         : BOOL;      // Master Enable signal for the high-speed canning cascade
    bResetFaults          : BOOL;      // Reset command for system faults and reject counters
    rSeamOverlapMm        : REAL;      // Analog input: Seamer roll overlap measurement in millimeters
    rLN2DosingMg          : REAL;      // Analog input: Liquid Nitrogen (LN2) dose weight in milligrams
    rXrayFillLevelMm      : REAL;      // Analog input: X-Ray fill level measurement in millimeters
    rLineSpeedCpm         : REAL;      // Analog input: Line speed in Cans Per Minute (CPM)
    rTargetPressurePsi    : REAL;      // Setpoint: Target internal pressure in PSI
    rTargetFillLevelMm    : REAL;      // Setpoint: Target fill level in millimeters
END_VAR

VAR_OUTPUT
    bSeamReject           : BOOL;      // Discrete output: Reject signal due to seamer roll overlap out of bounds
    bLN2DoseReject        : BOOL;      // Discrete output: Reject signal due to improper LN2 dosing/pressure
    bFillLevelReject      : BOOL;      // Discrete output: Reject signal due to X-Ray fill level out of bounds
    bSystemFault          : BOOL;      // Discrete output: Overall system fault (e.g. cascaded critical failures)
    rCalculatedPressure   : REAL;      // Analog output: Estimated internal pressure based on LN2 dose
    iTotalRejects         : DINT;      // Accumulator: Total number of cans rejected during production
    iConsecutiveRejects   : INT;       // Accumulator: Consecutive rejects counter for auto-stop triggering
END_VAR

VAR
    // Internal States and Limits
    rMinSeamOverlap       : REAL := 1.25;  // Minimum acceptable seamer roll overlap in mm
    rMaxSeamOverlap       : REAL := 1.75;  // Maximum acceptable seamer roll overlap in mm
    rFillToleranceMm      : REAL := 2.5;   // Permissible deviation from target fill level
    iMaxConsecutiveRejects: INT  := 5;     // Threshold for system fault based on continuous failures

    // Timers and Trigger Handling
    fbSeamCheckTimer      : TON;
    fbLN2DosingTimer      : TON;
    fbEjectorPulse        : TP;

    // Status Flags
    bSeamOk               : BOOL;
    bLN2Ok                : BOOL;
    bFillOk               : BOOL;
END_VAR

// -----------------------------------------------------------------------------
// Initialization and State Control
// -----------------------------------------------------------------------------
IF NOT bEnableSystem THEN
    bSeamReject         := FALSE;
    bLN2DoseReject      := FALSE;
    bFillLevelReject    := FALSE;
    bSystemFault        := FALSE;
    rCalculatedPressure := 0.0;
    RETURN;
END_IF;

IF bResetFaults THEN
    bSystemFault        := FALSE;
    iConsecutiveRejects := 0;
END_IF;

// -----------------------------------------------------------------------------
// 1. Seamer Roll Overlap Verification
// High-speed verification of the double seam overlap critical for hermetic seal
// -----------------------------------------------------------------------------
IF (rSeamOverlapMm < rMinSeamOverlap) OR (rSeamOverlapMm > rMaxSeamOverlap) THEN
    bSeamReject := TRUE;
    bSeamOk     := FALSE;
ELSE
    bSeamReject := FALSE;
    bSeamOk     := TRUE;
END_IF;

// -----------------------------------------------------------------------------
// 2. Liquid Nitrogen Dosing for Internal Pressure
// Dosing calculations for non-carbonated beverages to provide rigidity
// Assume 355ml standard can volume and empirical constant 0.852
// -----------------------------------------------------------------------------
IF rTargetPressurePsi > 0.0 THEN
    rCalculatedPressure := (rLN2DosingMg * 0.852) / 355.0; 

    IF (rCalculatedPressure < (rTargetPressurePsi * 0.92)) OR (rCalculatedPressure > (rTargetPressurePsi * 1.08)) THEN
        bLN2DoseReject := TRUE;
        bLN2Ok         := FALSE;
    ELSE
        bLN2DoseReject := FALSE;
        bLN2Ok         := TRUE;
    END_IF;
END_IF;

// -----------------------------------------------------------------------------
// 3. X-Ray Fill Level Inspection Cascades
// Highly precise fill level inspection utilizing X-Ray technology
// -----------------------------------------------------------------------------
IF (rXrayFillLevelMm < (rTargetFillLevelMm - rFillToleranceMm)) OR 
   (rXrayFillLevelMm > (rTargetFillLevelMm + rFillToleranceMm)) THEN
    bFillLevelReject := TRUE;
    bFillOk          := FALSE;
ELSE
    bFillLevelReject := FALSE;
    bFillOk          := TRUE;
END_IF;

// -----------------------------------------------------------------------------
// Reject Aggregation and System Fault Handling
// -----------------------------------------------------------------------------
IF bSeamReject OR bLN2DoseReject OR bFillLevelReject THEN
    iTotalRejects       := iTotalRejects + 1;
    iConsecutiveRejects := iConsecutiveRejects + 1;
ELSE
    iConsecutiveRejects := 0;
END_IF;

// Trigger a critical system fault if consecutive rejects exceed threshold
IF iConsecutiveRejects >= iMaxConsecutiveRejects THEN
    bSystemFault := TRUE;
END_IF;

END_FUNCTION_BLOCK
