FUNCTION_BLOCK FB_SOFC_Plant_Controller
(*
    Advanced Control Algorithm for Solid Oxide Fuel Cell (SOFC) Cogeneration Plant.
    Handles high-temperature startup gradients, methane reforming, anode mass flow, 
    and cathode air supply to maintain 800°C operational setpoint while avoiding 
    thermal shock and optimizing electrical efficiency.
*)
VAR_INPUT
    bEnable                 : BOOL;     (* System overall enable/run command *)
    bEmergencyStop          : BOOL;     (* E-Stop relay OK signal (Active High) *)
    rStackTemp1             : REAL;     (* Ceramic electrolyte temperature zone 1 [degC] *)
    rStackTemp2             : REAL;     (* Ceramic electrolyte temperature zone 2 [degC] *)
    rAnodeGasPressure       : REAL;     (* Reformed methane supply pressure [bar] *)
    rGridVoltage            : REAL;     (* Grid voltage for synchronization [V] *)
    rCathodeAirFlowRaw      : REAL;     (* Raw air flow from blower [L/min] *)
    rMethaneMassFlow        : REAL;     (* Fuel mass flow input [kg/h] *)
END_VAR

VAR_OUTPUT
    bSystemReady            : BOOL;     (* Stack at operating temperature and pressure *)
    bLoadConnected          : BOOL;     (* Inverter synchronized and supplying power *)
    rHeaterControlOutput    : REAL;     (* PWM or analog control for startup heaters (0-100%) *)
    rAnodeValvePosition     : REAL;     (* Control valve for fuel flow (0-100%) *)
    rBlowerSpeedSetpoint    : REAL;     (* Cathode blower speed (0-100%) *)
    bAlarm                  : BOOL;     (* General fault alarm *)
    iFaultCode              : INT;      (* Diagnostics code *)
END_VAR

VAR
    iState                  : INT := 0; (* Internal state machine *)
    rAvgStackTemp           : REAL;     (* Filtered average stack temperature *)
    rTempGradient           : REAL;     (* Rate of change of temperature (degC/min) *)
    rLastAvgStackTemp       : REAL;
    tTempSampleTimer        : TON;
    tStabilizationTimer     : TON;
    tPurgeTimer             : TON;

    (* Filter variables *)
    rAlpha                  : REAL := 0.1; (* Low pass filter coefficient *)

    (* PID variables for temperature control *)
    rTempError              : REAL;
    rTempIntegral           : REAL;
    rKp                     : REAL := 2.5;
    rKi                     : REAL := 0.05;
    rTempSetpoint           : REAL := 800.0;

    (* Constants *)
    MAX_TEMP_GRADIENT       : REAL := 5.0; (* Max 5 degC per minute *)
    ALARM_OVERTEMP          : REAL := 850.0;
END_VAR

(* === MAIN LOGIC === *)

(* 1. Safety Interlocks & Signal Filtering *)
IF NOT bEmergencyStop THEN
    bSystemReady := FALSE;
    bLoadConnected := FALSE;
    rHeaterControlOutput := 0.0;
    rAnodeValvePosition := 0.0;
    rBlowerSpeedSetpoint := 100.0; (* Full cooling on e-stop *)
    bAlarm := TRUE;
    iFaultCode := 99; (* E-Stop active *)
    iState := 0;
    RETURN;
END_IF;

(* Filter stack temperatures *)
rAvgStackTemp := (rStackTemp1 + rStackTemp2) / 2.0;
rAvgStackTemp := (rAlpha * rAvgStackTemp) + ((1.0 - rAlpha) * rLastAvgStackTemp);

(* Calculate Thermal Gradient (dT/dt) *)
tTempSampleTimer(IN := TRUE, PT := T#60S);
IF tTempSampleTimer.Q THEN
    rTempGradient := rAvgStackTemp - rLastAvgStackTemp;
    rLastAvgStackTemp := rAvgStackTemp;
    tTempSampleTimer(IN := FALSE);
END_IF;

(* Over-temperature Protection *)
IF rAvgStackTemp > ALARM_OVERTEMP THEN
    bAlarm := TRUE;
    iFaultCode := 10; (* Overtemp *)
    iState := 999; (* Fault state *)
END_IF;

(* 2. Main State Machine *)
CASE iState OF
    0: (* IDLE & PURGE *)
        bSystemReady := FALSE;
        bLoadConnected := FALSE;
        rHeaterControlOutput := 0.0;
        rAnodeValvePosition := 0.0;

        IF bEnable THEN
            rBlowerSpeedSetpoint := 50.0; (* Purge flow *)
            tPurgeTimer(IN := TRUE, PT := T#120S);
            IF tPurgeTimer.Q THEN
                tPurgeTimer(IN := FALSE);
                iState := 10;
            END_IF;
        ELSE
            rBlowerSpeedSetpoint := 0.0;
            tPurgeTimer(IN := FALSE);
        END_IF;

    10: (* HEATUP PHASE *)
        (* Ensure gradient < MAX_TEMP_GRADIENT to avoid ceramic cracking *)
        rTempError := rTempSetpoint - rAvgStackTemp;
        IF rTempGradient > MAX_TEMP_GRADIENT THEN
            rHeaterControlOutput := MAX(0.0, rHeaterControlOutput - 5.0);
        ELSE
            (* Basic PI Control for heater *)
            rTempIntegral := rTempIntegral + (rTempError * 0.1);
            IF rTempIntegral > 100.0 THEN rTempIntegral := 100.0; END_IF;
            IF rTempIntegral < 0.0 THEN rTempIntegral := 0.0; END_IF;
            rHeaterControlOutput := (rKp * rTempError) + (rKi * rTempIntegral);
        END_IF;

        (* Limit output *)
        IF rHeaterControlOutput > 100.0 THEN rHeaterControlOutput := 100.0; END_IF;
        IF rHeaterControlOutput < 0.0 THEN rHeaterControlOutput := 0.0; END_IF;

        rBlowerSpeedSetpoint := 20.0; (* Minimum flow during heatup *)

        IF rAvgStackTemp >= (rTempSetpoint - 10.0) THEN
            iState := 20;
        END_IF;

        IF NOT bEnable THEN iState := 0; END_IF;

    20: (* STABILIZATION & FUEL INTRODUCTION *)
        bSystemReady := TRUE;
        tStabilizationTimer(IN := TRUE, PT := T#300S);

        IF tStabilizationTimer.Q AND (rAnodeGasPressure > 1.5) THEN
            tStabilizationTimer(IN := FALSE);
            iState := 30;
        END_IF;

        IF NOT bEnable THEN iState := 0; END_IF;

    30: (* NORMAL OPERATION *)
        (* Modulate fuel based on desired power / thermal balance *)
        rAnodeValvePosition := 60.0 + (rMethaneMassFlow * 0.1); 
        IF rAnodeValvePosition > 100.0 THEN rAnodeValvePosition := 100.0; END_IF;

        (* Stoichiometric air supply via blower *)
        rBlowerSpeedSetpoint := rAnodeValvePosition * 1.2;
        IF rBlowerSpeedSetpoint > 100.0 THEN rBlowerSpeedSetpoint := 100.0; END_IF;

        IF rGridVoltage > 380.0 THEN
            bLoadConnected := TRUE;
        ELSE
            bLoadConnected := FALSE;
        END_IF;

        IF NOT bEnable THEN
            iState := 40; (* Cooldown phase *)
        END_IF;

    40: (* CONTROLLED COOLDOWN *)
        bLoadConnected := FALSE;
        bSystemReady := FALSE;
        rAnodeValvePosition := 0.0;
        rHeaterControlOutput := 0.0;

        (* Run blower to slowly cool stack *)
        rBlowerSpeedSetpoint := 30.0;

        IF rAvgStackTemp < 100.0 THEN
            iState := 0;
        END_IF;

    999: (* FAULT SHUTDOWN *)
        bSystemReady := FALSE;
        bLoadConnected := FALSE;
        rHeaterControlOutput := 0.0;
        rAnodeValvePosition := 0.0;
        rBlowerSpeedSetpoint := 100.0; (* Cool down fast *)

        IF bEnable = FALSE AND rAvgStackTemp < 100.0 THEN
            bAlarm := FALSE;
            iFaultCode := 0;
            iState := 0;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
