    rArgonFlowCmd           : REAL;     (* Setpoint for Argon MFC (Mass Flow Controller) (L/min) *)
    iEMS_StirringPattern    : INT;      (* 0=Off, 1=Gentle, 2=Aggressive for Electromagnetic Stirrer *)
    bAlarm                  : BOOL;     (* Fault alarm output (True = Fault active) *)
END_VAR

VAR
    iState                  : INT := 0; (* Internal state machine tracker *)
    tTimer                  : TON;      (* Process stabilization timer *)
    tArgonDelay             : TON;      (* Argon pre-fill delay timer *)
    rLevelError             : REAL;     (* Meniscus tracking error *)
    rLevelIntegral          : REAL;     (* Integral accumulator for PID *)
    rKp                     : REAL := 1.25;
    rKi                     : REAL := 0.05;
    rMaxIntegral            : REAL := 25.0;
    rBaseArgonFlow          : REAL := 12.0; (* L/min base flow *)
END_VAR

(* === MAIN LOGIC === *)
(* Critical Safety Interlock Check *)
IF NOT bEmergencyStop THEN
    bSystemReady := FALSE;
    bAlarm := TRUE;
    rStopperRodCmd := 0.0; (* Slam stopper rod closed on E-STOP *)
    rArgonFlowCmd := 0.0;
    iEMS_StirringPattern := 0;
    iState := 999; (* Transition to fault state *)
    RETURN;
END_IF;

CASE iState OF
    0: (* IDLE & INITIALIZATION *)
        bSystemReady := FALSE;
        bAlarm := FALSE;
        rStopperRodCmd := 0.0; 
        rArgonFlowCmd := 0.0;
        iEMS_StirringPattern := 0;

        IF bEnable THEN
            iState := 10;
        END_IF;

    10: (* ARGON PURGING *)
        (* Initiate Argon flow into the slide-gate nozzle before opening *)
        rArgonFlowCmd := rBaseArgonFlow * 1.5;
        tArgonDelay(IN := TRUE, PT := T#10S);
        IF tArgonDelay.Q THEN
            tArgonDelay(IN := FALSE);
            iState := 20;
        END_IF;

    20: (* RUNNING & MENISCUS TRACKING *)
        bSystemReady := TRUE;

        (* Calculate Meniscus Level Error *)
        rLevelError := rMeniscusSetpoint - rMeniscusLevelRadar;

        (* Integrate with anti-windup clamping *)
        rLevelIntegral := rLevelIntegral + (rLevelError * rKi);
        IF rLevelIntegral > rMaxIntegral THEN
            rLevelIntegral := rMaxIntegral;
        ELSIF rLevelIntegral < -rMaxIntegral THEN
            rLevelIntegral := -rMaxIntegral;
        END_IF;

        (* PI Control for Stopper Rod Position *)
        rStopperRodCmd := (rLevelError * rKp) + rLevelIntegral;

        (* Stopper rod position limits (0% to 100%) *)
        IF rStopperRodCmd > 100.0 THEN
            rStopperRodCmd := 100.0;
        ELSIF rStopperRodCmd < 0.0 THEN
            rStopperRodCmd := 0.0;
        END_IF;

        (* Argon Flow proportional to stopper rod position & mold casting speed *)
        rArgonFlowCmd := rBaseArgonFlow + (rStopperRodCmd * 0.1) + (rMoldCastingSpeed * 2.5);

        (* Electromagnetic Mold Stirring (EMS) Pattern Selection *)
        IF rMoldCastingSpeed > 1.2 THEN
            iEMS_StirringPattern := 2; (* High speed casting = Aggressive Stirring *)
        ELSIF rMoldCastingSpeed > 0.5 THEN
            iEMS_StirringPattern := 1; (* Normal speed = Gentle Stirring *)
        ELSE
            iEMS_StirringPattern := 0; (* Slow/Stop = No Stirring *)
        END_IF;

        (* Shutdown Condition *)
        IF NOT bEnable THEN
            iState := 30;
        END_IF;

    30: (* RAMP DOWN & CLOSING *)
        bSystemReady := FALSE;
        rStopperRodCmd := 0.0; (* Command close *)

        tTimer(IN := TRUE, PT := T#5S);
        IF tTimer.Q AND (rStopperRodPosFb < 1.0) THEN
            tTimer(IN := FALSE);
            rArgonFlowCmd := 0.0;
            iState := 0;
        END_IF;

    999: (* FAULT HANDLING *)
        IF bEmergencyStop AND NOT bEnable THEN
            bAlarm := FALSE;
            iState := 0;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
