FUNCTION_BLOCK FB_DeepwaterBOP_AcousticTelemetry
VAR_INPUT
    (* Physical inputs and acoustic signals *)
    bSystemEnable           : BOOL;     (* Main safety system enable signal *)
    bAcousticRxValid        : BOOL;     (* Subsea acoustic receiver signal validation flag *)
    rAcousticSNR            : REAL;     (* Acoustic signal-to-noise ratio in dB *)
    dwTelemetryCommand      : DWORD;    (* Decoded acoustic telemetry command word *)
    rHydraulicPressure      : REAL;     (* Subsea hydraulic accumulator pressure in PSI *)
    rAmbientTemp            : REAL;     (* Ambient seawater temperature in deg C *)
    bManualOverrideCmd      : BOOL;     (* Surface manual override command via acoustics *)
    rBatteryVoltage         : REAL;     (* Subsea battery pack voltage *)
END_VAR
VAR_OUTPUT
    (* Actuation and status outputs *)
    bBlindShearRamActuate   : BOOL;     (* Trigger for Blind Shear Rams (BSR) *)
    bAnnularPreventerActuate: BOOL;     (* Trigger for Annular Preventer *)
    rTelemetryTxPower       : REAL;     (* Acoustic transmit power level request (Watts) *)
    bCriticalAlarm          : BOOL;     (* System critical fault / low pressure alarm *)
    wStatusWord             : WORD;     (* Diagnostic status word for telemetry tx *)
    bSystemReady            : BOOL;     (* System ready for telemetry comms and actuation *)
END_VAR
VAR
    (* Internal State and Timer Variables *)
    iState                  : INT := 0; 
    tAcousticTimeout        : TON;
    tActuationDelay         : TON;
    rFilteredPressure       : REAL;
    wCommandBuffer          : WORD;
    bCommandValid           : BOOL;
    nFailSafeCounter        : INT := 0;

    (* Constants *)
    c_rMinOpPressure        : REAL := 3500.0; (* Minimum operational pressure in PSI *)
    c_rMinBatteryVolts      : REAL := 22.0;   (* Minimum battery voltage limit *)
    c_dwCmd_BSR_Close       : DWORD := 16#DEADBEEF; (* Highly secured command signature for BSR *)
    c_dwCmd_Annular_Close   : DWORD := 16#CAFEBABE;
END_VAR

(* === MAIN LOGIC === *)
(* 1. Safety Interlocks & Diagnostics *)
IF NOT bSystemEnable OR (rBatteryVoltage < c_rMinBatteryVolts) THEN
    bSystemReady := FALSE;
    bCriticalAlarm := TRUE;
    bBlindShearRamActuate := FALSE;
    bAnnularPreventerActuate := FALSE;
    rTelemetryTxPower := 0.0;
    wStatusWord := 16#FFFF; (* Fault code *)
    RETURN;
ELSE
    bSystemReady := TRUE;
END_IF;

(* 2. Acoustic Telemetry Validation *)
bCommandValid := FALSE;
IF bAcousticRxValid AND (rAcousticSNR > 10.0) THEN
    (* Valid acoustic burst received, evaluate the command *)
    IF dwTelemetryCommand = c_dwCmd_BSR_Close THEN
        bCommandValid := TRUE;
        wCommandBuffer := 16#0001; (* BSR Cmd *)
    ELSIF dwTelemetryCommand = c_dwCmd_Annular_Close THEN
        bCommandValid := TRUE;
        wCommandBuffer := 16#0002; (* Annular Cmd *)
    ELSE
        wCommandBuffer := 16#0000;
    END_IF;
END_IF;

(* 3. Accumulator Pressure Monitoring with Simple Filter *)
rFilteredPressure := (rFilteredPressure * 0.8) + (rHydraulicPressure * 0.2);
IF rFilteredPressure < c_rMinOpPressure THEN
    bCriticalAlarm := TRUE;
    wStatusWord := wStatusWord OR 16#0001; (* Set low pressure bit *)
ELSE
    bCriticalAlarm := FALSE;
    wStatusWord := wStatusWord AND 16#FFFE; (* Clear low pressure bit *)
END_IF;

(* 4. State Machine for BOP Actuation and Fail-Safe Logic *)
CASE iState OF
    0: (* IDLE & MONITORING *)
        bBlindShearRamActuate := FALSE;
        bAnnularPreventerActuate := FALSE;
        rTelemetryTxPower := 10.0; (* Low power ping mode *)

        IF bCommandValid AND NOT bCriticalAlarm THEN
            iState := 10;
        END_IF;

    10: (* COMMAND VERIFICATION *)
        (* Increase TX power to ACK receipt of command *)
        rTelemetryTxPower := 150.0; 
        tAcousticTimeout(IN := TRUE, PT := T#2S);

        IF tAcousticTimeout.Q THEN
            tAcousticTimeout(IN := FALSE);
            IF wCommandBuffer = 16#0001 THEN
                iState := 20; (* Execute BSR *)
            ELSIF wCommandBuffer = 16#0002 THEN
                iState := 30; (* Execute Annular *)
            ELSE
                iState := 0; (* Abort *)
            END_IF;
        END_IF;

    20: (* ACTUATE BLIND SHEAR RAM (BSR) *)
        (* Ultimate fail-safe response *)
        bBlindShearRamActuate := TRUE;
        wStatusWord := wStatusWord OR 16#0100; (* BSR Actuated bit *)

        tActuationDelay(IN := TRUE, PT := T#15S);
        IF tActuationDelay.Q THEN
            tActuationDelay(IN := FALSE);
            iState := 100; (* Secure and wait *)
        END_IF;

    30: (* ACTUATE ANNULAR PREVENTER *)
        bAnnularPreventerActuate := TRUE;
        wStatusWord := wStatusWord OR 16#0200; (* Annular Actuated bit *)

        tActuationDelay(IN := TRUE, PT := T#10S);
        IF tActuationDelay.Q THEN
            tActuationDelay(IN := FALSE);
            iState := 100; (* Secure and wait *)
        END_IF;

    100: (* SECURED & POST-ACTUATION TELEMETRY *)
        (* Maintain actuation signals, broadcast maximum power SOS/Status *)
        rTelemetryTxPower := 250.0;

        (* Stay in this state until manual reset via override *)
        IF bManualOverrideCmd THEN
            bBlindShearRamActuate := FALSE;
            bAnnularPreventerActuate := FALSE;
            wStatusWord := 16#0000;
            iState := 0;
        END_IF;

    ELSE
        iState := 0;
END_CASE;

END_FUNCTION_BLOCK
```

