FUNCTION_BLOCK FB_IndustrialControl
VAR_INPUT
    bStartSeq : BOOL; // Start sequence
    bStopSeq  : BOOL; // Stop sequence
    bEmergencyStop : BOOL;
    rCavernPressure : REAL; // bar
    rCavernTemp : REAL; // deg C
    rCompressorStage1OutTemp : REAL;
    rCompressorStage2OutTemp : REAL;
    rCompressorStage3OutTemp : REAL;
    rRecuperatorTemp : REAL;
    rGridDemandMw : REAL;
END_VAR
VAR_OUTPUT
    bComp1Enable : BOOL;
    bComp2Enable : BOOL;
    bComp3Enable : BOOL;
    bIntercooler1Pump : BOOL;
    bIntercooler2Pump : BOOL;
    bExpanderValveCmd : REAL; // 0-100%
    bGeneratorBreaker : BOOL;
    iSysState : INT; // 0:Idle, 1:Starting, 2:Compressing, 3:Expanding, 4:Trip
    sStatusMsg : STRING;
END_VAR
VAR
    tStateTimer : TON;
    rMaxCavernPressure : REAL := 75.0; // bar
    rMinCavernPressure : REAL := 45.0; // bar
    rMaxCompTemp : REAL := 150.0; // C
    bTripCondition : BOOL;
END_VAR

// Evaluate trip conditions
bTripCondition := bEmergencyStop OR 
                 (rCavernPressure > (rMaxCavernPressure + 5.0)) OR
                 (rCompressorStage1OutTemp > rMaxCompTemp) OR
                 (rCompressorStage2OutTemp > rMaxCompTemp) OR
                 (rCompressorStage3OutTemp > rMaxCompTemp);

IF bTripCondition THEN
    iSysState := 4; // Trip
    bComp1Enable := FALSE;
    bComp2Enable := FALSE;
    bComp3Enable := FALSE;
    bIntercooler1Pump := FALSE;
    bIntercooler2Pump := FALSE;
    bExpanderValveCmd := 0.0;
    bGeneratorBreaker := FALSE;
    sStatusMsg := 'TRIP ACTIVE';
    RETURN;
END_IF;

CASE iSysState OF
    0: // Idle
        sStatusMsg := 'IDLE';
        IF bStartSeq THEN
            // Determine operation mode based on grid demand
            IF rGridDemandMw < 0.0 AND rCavernPressure < rMaxCavernPressure THEN
                // Negative demand means we compress to store energy
                iSysState := 1; 
                tStateTimer(IN := FALSE);
            ELSIF rGridDemandMw > 0.0 AND rCavernPressure > rMinCavernPressure THEN
                // Positive demand means we expand to generate
                iSysState := 3;
            END_IF;
        END_IF;

    1: // Starting Compression
        sStatusMsg := 'STARTING COMPRESSION';
        tStateTimer(IN := TRUE, PT := T#10S);
        bIntercooler1Pump := TRUE;
        bIntercooler2Pump := TRUE;

        IF tStateTimer.Q THEN
            iSysState := 2;
        END_IF;

    2: // Compressing
        sStatusMsg := 'COMPRESSING';
        bComp1Enable := TRUE;
        bComp2Enable := TRUE;
        bComp3Enable := TRUE;

        // Stop condition: max pressure reached or stop command
        IF rCavernPressure >= rMaxCavernPressure OR bStopSeq OR rGridDemandMw >= 0.0 THEN
            bComp1Enable := FALSE;
            bComp2Enable := FALSE;
            bComp3Enable := FALSE;
            bIntercooler1Pump := FALSE;
            bIntercooler2Pump := FALSE;
            iSysState := 0;
        END_IF;

    3: // Expanding
        sStatusMsg := 'EXPANDING / GENERATING';
        // Simple P control for expander valve based on grid demand
        bExpanderValveCmd := rGridDemandMw * 2.0; // scale factor
        IF bExpanderValveCmd > 100.0 THEN
            bExpanderValveCmd := 100.0;
        END_IF;

        IF rCavernPressure > rMinCavernPressure THEN
            bGeneratorBreaker := TRUE;
        ELSE
            // Cavern depleted
            bGeneratorBreaker := FALSE;
            bExpanderValveCmd := 0.0;
            iSysState := 0;
        END_IF;

        IF bStopSeq OR rGridDemandMw <= 0.0 THEN
            bGeneratorBreaker := FALSE;
            bExpanderValveCmd := 0.0;
            iSysState := 0;
        END_IF;

    4: // Trip state recovery
        IF NOT bTripCondition AND bStopSeq THEN
            iSysState := 0;
        END_IF;

    ELSE
        iSysState := 0;
END_CASE;

END_FUNCTION_BLOCK
