FUNCTION_BLOCK "BakeryOvenControl_M3"
VERSION : 0.1
   VAR_INPUT 
      Start : Bool;
      Stop : Bool;
      TargetSpeed : Real;
      Zone1_TempTarget : Real;
      Zone1_TempActual_A : Real; // Primary RTD Sensor
      Zone1_TempActual_B : Real; // Redundant RTD Sensor
      HumidityTarget : Real;
      HumidityActual : Real;
      PN_NodeStatus : Word;
      UserRole : Int; // IEC 62443 Role (0=Guest, 1=Operator, 2=Admin)
   END_VAR

   VAR_OUTPUT 
      ConveyorRun : Bool;
      ConveyorSpeedOut : Real;
      Zone1_Heater : Bool;
      SteamValve : Bool;
      Running : Bool;
      AlarmCode : Int;
      SCADA_Data : "Oven_SCADA_Data";
   END_VAR

   VAR 
      StateRunning : Bool;
      CommsFault : Bool;
      Zone1_TempUsed : Real;
   END_VAR

BEGIN
    // 1. Sensor Redundancy & Failover Logic
    IF ABS(#Zone1_TempActual_A - #Zone1_TempActual_B) > 10.0 THEN
        #AlarmCode := 201; // Sensor Deviation Alarm
        #Zone1_TempUsed := MAX(IN1:=#Zone1_TempActual_A, IN2:=#Zone1_TempActual_B); // Conservative fail-safe
    ELSE
        #Zone1_TempUsed := (#Zone1_TempActual_A + #Zone1_TempActual_B) / 2.0; // Average mode
    END_IF;

    // 2. Profinet and Hardware Diag
    #CommsFault := (#PN_NodeStatus <> 16#0000);

    // 3. IEC 62443 Cybersecurity Access Control
    IF #UserRole < 1 THEN
        #StateRunning := FALSE;
        #AlarmCode := 403; // Unauthorized access attempt
    ELSIF #CommsFault THEN
        #AlarmCode := 101; 
        #StateRunning := FALSE;
    ELSIF #Stop THEN
        #StateRunning := FALSE;
        #AlarmCode := 0;
    ELSIF #Start AND #UserRole >= 1 THEN
        #StateRunning := TRUE;
    END_IF;

    #Running := #StateRunning;

    // 4. Control Execution
    IF #StateRunning THEN
        #ConveyorRun := TRUE;
        #ConveyorSpeedOut := #TargetSpeed;
        #Zone1_Heater := #Zone1_TempUsed < (#Zone1_TempTarget - 2.0);
        #SteamValve := #HumidityActual < (#HumidityTarget - 5.0);
    ELSE
        #ConveyorRun := FALSE;
        #ConveyorSpeedOut := 0.0;
        #Zone1_Heater := FALSE;
        #SteamValve := FALSE;
    END_IF;

    // 5. SCADA Integration mapping
    #SCADA_Data.SystemStatus := BOOL_TO_INT(#StateRunning);
    #SCADA_Data.CurrentSpeed := #ConveyorSpeedOut;
    #SCADA_Data.Zone1_Temp := #Zone1_TempUsed;
    #SCADA_Data.ActiveAlarm := #AlarmCode;
END_FUNCTION_BLOCK
