    rMotorTempRight           : REAL; // Right traction motor temperature (deg C)

    // Suspension / Payload Sensors
    rStrutPressureFL          : REAL; // Front-Left suspension strut pressure (kPa)
    rStrutPressureFR          : REAL; // Front-Right suspension strut pressure (kPa)
    rStrutPressureRL          : REAL; // Rear-Left suspension strut pressure (kPa)
    rStrutPressureRR          : REAL; // Rear-Right suspension strut pressure (kPa)
    rInclinometerPitch        : REAL; // Vehicle pitch angle (degrees)
    rInclinometerRoll         : REAL; // Vehicle roll angle (degrees)

    // Retarder Grid System
    rGridTemp1                : REAL; // Retarder grid bank 1 temperature (deg C)
    rGridTemp2                : REAL; // Retarder grid bank 2 temperature (deg C)

    // Operator Controls
    bPayloadDumpSwitch        : BOOL; // Bed dump command
    bTractionControlBypass    : BOOL; // Override traction control limits
END_VAR

VAR_OUTPUT
    // Motor Control Commands
    rTractionTorqueCmdLeft    : REAL; // Torque command to left inverter (N-m)
    rTractionTorqueCmdRight   : REAL; // Torque command to right inverter (N-m)
    rRetarderEffortCmd        : REAL; // Blended retarder effort to grid choppers 0.0 to 100.0 %

    // Cooling Systems
    rBlowerFanSpeedCmd        : REAL; // Grid cooling blower fan command 0.0 to 100.0 %
    rMotorCoolingFanCmd       : REAL; // Traction motor cooling fan command 0.0 to 100.0 %

    // Powertrain & VIMS (Vital Information Management System)
    rEngineFuelDemand         : REAL; // Fuel injection demand to Engine ECU 0.0 to 100.0 %
    rEstimatedPayload         : REAL; // Filtered payload estimation (Tonnes)

    // Alarms and Warnings
    bGridOverTempAlarm        : BOOL; // Retarder grid temperature critical
    bTractionSlipAlarm        : BOOL; // Wheel slip condition active
    bMotorOverTempAlarm       : BOOL; // Traction motor temperature critical
END_VAR

VAR
    // Internal calculations
    rAverageSpeed             : REAL;
    rSlipRatioLeft            : REAL;
    rSlipRatioRight           : REAL;
    rMaxSlipAllowed           : REAL := 0.12; // 12% slip limit for optimal traction
    rTorqueLimitSlip          : REAL;

    // Payload estimation variables
    rFilterWeightFront        : REAL;
    rFilterWeightRear         : REAL;
    rRawPayloadTotal          : REAL;
    iPayloadFilterIndex       : INT := 0;
    arPayloadHistory          : ARRAY[0..99] OF REAL; // Moving average window (100 samples)
    rPayloadSum               : REAL := 0.0;
    bFilterInitialized        : BOOL := FALSE;
    i                         : INT;

    // Grid Cooling & Thermal Derating
    rMaxGridTemp              : REAL;
    rGridTempThreshold        : REAL := 680.0; // Max allowed temp before reducing retarder effort
    rGridTempCritical         : REAL := 800.0;
    rBlowerKp                 : REAL := 0.65;
    rRetarderDerateFactor     : REAL := 1.0;

    // Constants
    cEmptyVehicleWeight       : REAL := 160000.0; // 160 Tonnes tare weight
    cMaxTorqueLimit           : REAL := 25000.0;  // 25kNm per wheel motor
END_VAR

// ==============================================================================
// 1. PAYLOAD ESTIMATION & WEIGH-SCALE AVERAGING
// ==============================================================================
// Dynamic weight estimation compensating for vehicle pitch and roll.
// Uses a 100-sample moving average filter to smooth pressure spikes during haulage.

// Calculate dynamic weight distribution based on strut pressures and inclinometer
rFilterWeightFront := (rStrutPressureFL + rStrutPressureFR) * 0.42 * COS(rInclinometerPitch * 3.14159 / 180.0) * COS(rInclinometerRoll * 3.14159 / 180.0);
rFilterWeightRear  := (rStrutPressureRL + rStrutPressureRR) * 0.58 * COS(rInclinometerPitch * 3.14159 / 180.0) * COS(rInclinometerRoll * 3.14159 / 180.0);
rRawPayloadTotal   := rFilterWeightFront + rFilterWeightRear - cEmptyVehicleWeight; 

// Initialize filter array on first scan
IF NOT bFilterInitialized THEN
    FOR i := 0 TO 99 DO
        arPayloadHistory[i] := rRawPayloadTotal;
        rPayloadSum := rPayloadSum + rRawPayloadTotal;
    END_FOR;
    bFilterInitialized := TRUE;
ELSE
    // Moving Average Filter execution
    rPayloadSum := rPayloadSum - arPayloadHistory[iPayloadFilterIndex] + rRawPayloadTotal;
    arPayloadHistory[iPayloadFilterIndex] := rRawPayloadTotal;
    iPayloadFilterIndex := (iPayloadFilterIndex + 1) MOD 100;
END_IF;

rEstimatedPayload := rPayloadSum / 100.0;
// Zero clamp to prevent negative payload readings on bounce
IF rEstimatedPayload < 0.0 THEN
    rEstimatedPayload := 0.0;
END_IF;

// ==============================================================================
// 2. DIESEL-ELECTRIC TRACTION CONTROL & WHEEL SLIP REGULATION
// ==============================================================================
rAverageSpeed := (rWheelSpeedLeft + rWheelSpeedRight) / 2.0;

// Base fuel demand tied to throttle and engine governing (simplified)
rEngineFuelDemand := rThrottleCommand; 

// Calculate independent wheel slip ratios if vehicle is moving
IF rAverageSpeed > 5.0 THEN
    rSlipRatioLeft := (rWheelSpeedLeft - rAverageSpeed) / rAverageSpeed;
    rSlipRatioRight := (rWheelSpeedRight - rAverageSpeed) / rAverageSpeed;
ELSE
    rSlipRatioLeft := 0.0;
    rSlipRatioRight := 0.0;
END_IF;

// Evaluate Slip Conditions
bTractionSlipAlarm := (rSlipRatioLeft > rMaxSlipAllowed) OR (rSlipRatioRight > rMaxSlipAllowed);

// Dynamic Torque Derating for Traction Control
IF bTractionSlipAlarm AND NOT bTractionControlBypass THEN
    // Proportional torque reduction based on worst-case slip
    rTorqueLimitSlip := 1.0 - ((MAX(rSlipRatioLeft, rSlipRatioRight) - rMaxSlipAllowed) * 2.5);
    IF rTorqueLimitSlip < 0.2 THEN
        rTorqueLimitSlip := 0.2; // Minimum 20% torque retention to prevent stalling
    END_IF;
ELSE
    rTorqueLimitSlip := 1.0;
END_IF;

// Apply Torque Commands with Slip Limits
rTractionTorqueCmdLeft := (rThrottleCommand / 100.0) * cMaxTorqueLimit * rTorqueLimitSlip;
rTractionTorqueCmdRight := (rThrottleCommand / 100.0) * cMaxTorqueLimit * rTorqueLimitSlip;

// ==============================================================================
// 3. DYNAMIC RETARDER GRID COOLING & BRAKE BLENDING
// ==============================================================================
// Find highest grid temperature
IF rGridTemp1 > rGridTemp2 THEN
    rMaxGridTemp := rGridTemp1;
ELSE
    rMaxGridTemp := rGridTemp2;
END_IF;

// Grid Cooling Blower PI Control (Simplified to P-only for synthetic model)
IF rMaxGridTemp > 200.0 THEN
    rBlowerFanSpeedCmd := (rMaxGridTemp - 200.0) * rBlowerKp;
ELSE
    rBlowerFanSpeedCmd := 0.0;
END_IF;

IF rBlowerFanSpeedCmd > 100.0 THEN
    rBlowerFanSpeedCmd := 100.0;
END_IF;

// Thermal Derating of Retarder Grid
bGridOverTempAlarm := rMaxGridTemp > rGridTempThreshold;
IF rMaxGridTemp > rGridTempCritical THEN
    rRetarderDerateFactor := 0.0; // Shut down dynamic braking, force mechanical brakes
ELSIF bGridOverTempAlarm THEN
    // Linear derate from threshold to critical
    rRetarderDerateFactor := 1.0 - ((rMaxGridTemp - rGridTempThreshold) / (rGridTempCritical - rGridTempThreshold));
ELSE
    rRetarderDerateFactor := 1.0;
END_IF;

// Final Retarder Effort blending operator commands with thermal protection
rRetarderEffortCmd := (rRetarderLever + (rBrakePedal * 0.5)) * rRetarderDerateFactor;
IF rRetarderEffortCmd > 100.0 THEN
    rRetarderEffortCmd := 100.0;
END_IF;

// Motor Cooling Management
bMotorOverTempAlarm := (rMotorTempLeft > 180.0) OR (rMotorTempRight > 180.0);
IF bMotorOverTempAlarm OR (rTractionTorqueCmdLeft > cMaxTorqueLimit * 0.8) THEN
    rMotorCoolingFanCmd := 100.0;
ELSIF rAverageSpeed > 10.0 THEN
    rMotorCoolingFanCmd := 50.0;
ELSE
    rMotorCoolingFanCmd := 20.0; // Idle cooling
END_IF;

END_FUNCTION_BLOCK
```

```iec-st
Here is the production-ready IEC 61131-3 implementation for the Amine Scrubber CO2 Stripping Controller.

### Design Overview
This Function Block (`FB_AmineScrubberController`) is engineered for industrial carbon capture operations. It encapsulates the core dynamics of MEA-based post-combustion capture into an IEC 61131-3 Structured Text module:

1. **Thermal Balancing**: Calculates enthalpy transfer (Q = m * Cp * ΔT) across the Lean/Rich Cross-Heat Exchanger, driving a fault-detection signal if the thermal imbalance exceeds typical fouling/bypass thresholds (15%).
2. **Reboiler Duty Control**: Continuously evaluates current reboiler steam duty and incorporates a bumpless PI controller with anti-windup to modulate the steam valve and achieve the `rTarget_Reboiler_Duty`.
3. **Foaming Detection**: Employs a low-pass filtered differential pressure (dP) monitor across the absorber column. Prolonged spikes trigger a foaming alarm, which auto-activates a Time-Off-Delay (TOF) anti-foam dosing sequence.

### IEC 61131-3 Structured Text

(*
==========================================================================================
BLOCK: FB_AmineScrubberController
AUTHOR: Lumina Elite Synthetic Data Architect
VERSION: 1.0.0
DESCRIPTION: 
Advanced control block for an Amine Scrubber CO2 Stripping unit. 
Implements:
1. Lean/Rich MEA cross-heat exchanger thermal balancing (enthalpy tracking).
2. Stripper column steam reboiler duty control via cascade PI.
3. Flue gas absorber column foaming detection (dP anomaly) & anti-foam dosing.
==========================================================================================
*)
FUNCTION_BLOCK FB_AmineScrubberController
VAR_INPUT
    // --- Temperatures (Degrees C) ---
    rTemp_RichMEA_In          : REAL; (* Rich MEA temp into Cross-Exchanger *)
    rTemp_RichMEA_Out         : REAL; (* Rich MEA temp out of Cross-Exchanger (to Stripper) *)
    rTemp_LeanMEA_In          : REAL; (* Lean MEA temp from Stripper into Cross-Exchanger *)
    rTemp_LeanMEA_Out         : REAL; (* Lean MEA temp out of Cross-Exchanger *)
    rTemp_Reboiler            : REAL; (* Steam reboiler temperature *)
    rTemp_FlueGas_In          : REAL; (* Inlet Flue gas temperature *)

    // --- Flows (kg/h) ---
    rFlow_RichMEA             : REAL; (* Rich MEA mass flow rate *)
    rFlow_LeanMEA             : REAL; (* Lean MEA mass flow rate *)
    rFlow_Steam               : REAL; (* Steam flow to reboiler *)

    // --- Pressures (bar) ---
    rPress_Absorber_Btm       : REAL; (* Absorber bottom pressure *)
    rPress_Absorber_Top       : REAL; (* Absorber top pressure *)

    // --- Quality / Tuning ---
    rTarget_Reboiler_Duty     : REAL; (* Target duty in kW *)
    rMEA_Cp                   : REAL := 3.4; (* Specific heat of MEA sol. kJ/kg.K *)
    rSteam_Enthalpy           : REAL := 2100.0; (* Latent heat of steam kJ/kg *)

    bReset                    : BOOL; (* Reset alarms and integrals *)
END_VAR

VAR_OUTPUT
    // --- Control Signals ---
    rCmd_SteamValve           : REAL; (* 0-100% steam flow valve command *)
    bCmd_AntiFoamPump         : BOOL; (* Anti-foam dosing pump command *)

    // --- Diagnostics ---
    rCalc_ExchangerDuty_Rich  : REAL; (* kW transferred to Rich MEA *)
    rCalc_ExchangerDuty_Lean  : REAL; (* kW lost from Lean MEA *)
    rThermal_Imbalance        : REAL; (* % difference in expected vs actual heat transfer *)
    rCalc_ReboilerDuty        : REAL; (* Current Reboiler Duty in kW *)
    rdP_Absorber              : REAL; (* Differential pressure across absorber *)

    // --- Alarms ---
    bAlarm_Fouling_Exchanger  : BOOL; (* High thermal imbalance indicating fouling *)
    bAlarm_Foaming            : BOOL; (* Foaming detected in absorber *)
    bAlarm_LowReboilerTemp    : BOOL; (* Reboiler temperature critically low *)
END_VAR

VAR
    // --- Internal States ---
    rAbsorber_dP_Filtered     : REAL;
    rFilter_Tau               : REAL := 2.0; (* Low pass filter time constant *)

    // Foaming detection thresholds
    rdP_Foam_Threshold        : REAL := 0.15; (* dP spike indicating foaming *)
    ton_FoamTimer             : TON;
    tof_DosingTimer           : TOF;

    // Reboiler PID variables
    rError_Duty               : REAL;
    rIntegral_Duty            : REAL;
    rKp_Steam                 : REAL := 0.5;
    rKi_Steam                 : REAL := 0.05;

    // Timing
    rCycleTime_Sec            : REAL := 1.0; (* Execute cycle assumption for math *)
END_VAR

(* -----------------------------------------------------------------------------
   1. Lean/Rich MEA Cross-Heat Exchanger Thermal Balancing
   ----------------------------------------------------------------------------- *)
// Q = m * Cp * dT (kW) Note: Flow is kg/h, so divide by 3600 for kg/s
rCalc_ExchangerDuty_Rich := (rFlow_RichMEA / 3600.0) * rMEA_Cp * (rTemp_RichMEA_Out - rTemp_RichMEA_In);
rCalc_ExchangerDuty_Lean := (rFlow_LeanMEA / 3600.0) * rMEA_Cp * (rTemp_LeanMEA_In - rTemp_LeanMEA_Out);

// Calculate Thermal Imbalance (%)
IF rCalc_ExchangerDuty_Rich > 10.0 THEN
    rThermal_Imbalance := ABS(rCalc_ExchangerDuty_Rich - rCalc_ExchangerDuty_Lean) / rCalc_ExchangerDuty_Rich * 100.0;
ELSE
    rThermal_Imbalance := 0.0;
END_IF;

// Fouling Alarm (Imbalance > 15% indicates significant bypass, fouling or instrumentation error)
IF rThermal_Imbalance > 15.0 THEN
    bAlarm_Fouling_Exchanger := TRUE;
END_IF;

IF bReset THEN
    bAlarm_Fouling_Exchanger := FALSE;
END_IF;

(* -----------------------------------------------------------------------------
   2. Stripper Column Steam Reboiler Duty Calculation & Control
   ----------------------------------------------------------------------------- *)
// Current Duty (kW) = Flow (kg/s) * Latent Heat (kJ/kg)
rCalc_ReboilerDuty := (rFlow_Steam / 3600.0) * rSteam_Enthalpy;

// PI Controller for Steam Valve
rError_Duty := rTarget_Reboiler_Duty - rCalc_ReboilerDuty;

IF NOT bReset THEN
    rIntegral_Duty := rIntegral_Duty + (rError_Duty * rKi_Steam * rCycleTime_Sec);
    // Anti-windup
    IF rIntegral_Duty > 100.0 THEN rIntegral_Duty := 100.0; END_IF;
    IF rIntegral_Duty < 0.0 THEN rIntegral_Duty := 0.0; END_IF;
ELSE
    rIntegral_Duty := 0.0;
END_IF;

rCmd_SteamValve := (rError_Duty * rKp_Steam) + rIntegral_Duty;

// Clamp Output
IF rCmd_SteamValve > 100.0 THEN rCmd_SteamValve := 100.0; END_IF;
IF rCmd_SteamValve < 0.0 THEN rCmd_SteamValve := 0.0; END_IF;

// Reboiler Temp Monitoring
bAlarm_LowReboilerTemp := (rTemp_Reboiler < 105.0) AND (rTarget_Reboiler_Duty > 0.0);

(* -----------------------------------------------------------------------------
   3. Flue Gas Absorber Column Foaming Detection and Anti-Foam Dosing
   ----------------------------------------------------------------------------- *)
// Calculate raw differential pressure
rdP_Absorber := rPress_Absorber_Btm - rPress_Absorber_Top;

// First-order low pass filter for dP to eliminate gas surge noise
rAbsorber_dP_Filtered := rAbsorber_dP_Filtered + (rCycleTime_Sec / (rFilter_Tau + rCycleTime_Sec)) * (rdP_Absorber - rAbsorber_dP_Filtered);

// Detect foaming (dP sudden continuous rise)
ton_FoamTimer(IN := (rAbsorber_dP_Filtered > rdP_Foam_Threshold), PT := T#5S);

IF ton_FoamTimer.Q THEN
    bAlarm_Foaming := TRUE;
END_IF;

IF bReset THEN
    bAlarm_Foaming := FALSE;
END_IF;

// Anti-Foam Dosing Logic (Dose for 30 seconds when foaming detected)
tof_DosingTimer(IN := bAlarm_Foaming, PT := T#30S);
bCmd_AntiFoamPump := tof_DosingTimer.Q;

END_FUNCTION_BLOCK
### Safety and Optimization Notes:
- **Tuning Assumptions**: `rKp_Steam` and `rKi_Steam` default to 0.5 and 0.05 respectively, but would require open-loop step tuning in actual production.
- **Fail-Safe Operation**: Anti-windup clamping prevents integral saturation. Valve command is clamped `[0, 100]` to avoid undefined analog scaling.
- **Cycle Time**: Assumes the host PLC executes this block on a 1.0s periodic task (`rCycleTime_Sec`), meaning filter constants and integrals are pre-scaled for a 1 Hz resolution.
