FUNCTION_BLOCK FB_ClarifierControl
VAR_INPUT
    rRawWaterFlow : REAL; (* Influent flow rate m3/h *)
    rRawWaterTurbidity : REAL; (* NTU *)
    rpH_Inlet : REAL;
    rFlocBlanketLevel : REAL; (* meters from bottom *)
    bScraperDriveFault : BOOL;
    bSludgePumpsReady : BOOL;
END_VAR
VAR_OUTPUT
    rCoagulantDoseRate : REAL; (* L/h *)
    rPolymerDoseRate : REAL; (* L/h *)
    rScraperRPM_Cmd : REAL; (* RPM *)
    bSludgePumpStart : BOOL;
    rSludgePumpSpeed : REAL; (* % *)
    wState : WORD;
    bAlarm : BOOL;
END_VAR
VAR
    rTargetDoseCoag : REAL;
    rTargetDosePoly : REAL;
    rFlocError : REAL;
    rFlocBlanketSP : REAL := 2.5; (* Target blanket level 2.5m *)
    rKp_Floc : REAL := 10.0;
    rKi_Floc : REAL := 0.5;
    rFlocIntegral : REAL := 0.0;
    rScraperBaseRPM : REAL := 0.1;
    tmrBlanketHigh : TON;
    tmrSludgePumpRun : TON;
    bSludgePumpingActive : BOOL;
    step : INT := 0;
END_VAR

(* Calculate Coagulant Dose based on flow, turbidity and pH compensation *)
(* Base dose is proportional to flow and turbidity, with a pH multiplier *)
rTargetDoseCoag := rRawWaterFlow * (rRawWaterTurbidity * 0.05);
IF rpH_Inlet > 7.5 THEN
    rTargetDoseCoag := rTargetDoseCoag * 1.2; (* Requires more coagulant at higher pH *)
ELSIF rpH_Inlet < 6.5 THEN
    rTargetDoseCoag := rTargetDoseCoag * 0.8;
END_IF;
rCoagulantDoseRate := rTargetDoseCoag;

(* Polymer Dose is proportional to coagulant dose *)
rTargetDosePoly := rTargetDoseCoag * 0.15;
rPolymerDoseRate := rTargetDosePoly;

(* Floc Blanket Level Control *)
rFlocError := rFlocBlanketLevel - rFlocBlanketSP;
IF rFlocError > 0.0 THEN
    rFlocIntegral := rFlocIntegral + (rFlocError * rKi_Floc);
    (* Limit integral windup *)
    IF rFlocIntegral > 50.0 THEN
        rFlocIntegral := 50.0;
    END_IF;
ELSE
    rFlocIntegral := 0.0; (* Reset if below target *)
END_IF;

(* Scraper RPM Control *)
IF bScraperDriveFault THEN
    rScraperRPM_Cmd := 0.0;
    bAlarm := TRUE;
    wState := 16#F001; (* Fault state *)
ELSE
    rScraperRPM_Cmd := rScraperBaseRPM + (rFlocError * rKp_Floc) + rFlocIntegral;
    (* Clamp RPM *)
    IF rScraperRPM_Cmd > 0.5 THEN
        rScraperRPM_Cmd := 0.5;
    ELSIF rScraperRPM_Cmd < 0.05 THEN
        rScraperRPM_Cmd := 0.05;
    END_IF;
    bAlarm := FALSE;
    wState := 16#0001; (* Running state *)
END_IF;

(* Sludge Pumping Logic *)
tmrBlanketHigh(IN := (rFlocBlanketLevel > (rFlocBlanketSP + 0.5)), PT := T#5M);

IF tmrBlanketHigh.Q AND bSludgePumpsReady AND NOT bSludgePumpingActive THEN
    bSludgePumpingActive := TRUE;
END_IF;

tmrSludgePumpRun(IN := bSludgePumpingActive, PT := T#15M);

IF tmrSludgePumpRun.Q THEN
    bSludgePumpingActive := FALSE;
END_IF;

IF bSludgePumpingActive THEN
    bSludgePumpStart := TRUE;
    rSludgePumpSpeed := 80.0; (* Run at 80% speed during extraction *)
    wState := 16#0002; (* Desludging state *)
ELSE
    bSludgePumpStart := FALSE;
    rSludgePumpSpeed := 0.0;
END_IF;

END_FUNCTION_BLOCK
