```iec-st
FUNCTION_BLOCK FB_OTEC_AmmoniaEvaporator
(* 
   ====================================================================================
   Author: Elite automation architect (40+ years experience)
   Domain: Next-Gen Ocean Thermal Energy Conversion (OTEC) Closed-Cycle Ammonia Evaporator
   Description: Advanced control algorithm for a thin-film falling liquid cascade 
                ammonia evaporator. Includes dynamic vapor quality supersaturation 
                monitoring, non-condensable gas vacuum purging, and PID/state-machine 
                resilience with multi-layered safety interlocks.
   ==================================================================================== 
*)
VAR_INPUT
    bEnable                 : BOOL;     (* System global enable command *)
    bEmergencyStop          : BOOL;     (* Safety instrumented system (SIS) OK signal *)
    rWarmSeawaterFlow       : REAL;     (* Flow rate of warm surface seawater (kg/s) *)
    rWarmSeawaterTemp       : REAL;     (* Inlet temperature of warm seawater (deg C) *)
    rAmmoniaInletPressure   : REAL;     (* Evaporator ammonia inlet pressure (bar) *)
    rAmmoniaLiquidLevel     : REAL;     (* Liquid ammonia inventory level (mm) *)
    rVaporQuality           : REAL;     (* Vapor quality measurement (0.0 to 1.0) *)
    rNonCondensableGasLvl   : REAL;     (* Detected non-condensable gases (ppm) *)
END_VAR
VAR_OUTPUT
    bSystemReady            : BOOL;     (* System ready for power generation loop *)
    rSeawaterPumpSpeed      : REAL;     (* Control signal to warm seawater pump (0-100%) *)
    rAmmoniaFeedValve       : REAL;     (* Control signal to ammonia feed valve (0-100%) *)
    bVacuumPurgeValve       : BOOL;     (* Command to open NCG vacuum purge valve *)
    rSuperheatTemp          : REAL;     (* Calculated supersaturation / superheat (deg C) *)
    bCriticalAlarm          : BOOL;     (* Critical fault alarm, triggers immediate shutdown *)
END_VAR
VAR
    iState                  : INT := 0; (* Internal state machine step *)
    tStartupDelay           : TON;      (* Delay timer for system stabilization *)
    tPurgeTimer             : TON;      (* Timer for non-condensable gas purging duration *)
    rFilteredLevel          : REAL;     (* Low-pass filtered liquid level *)
    rFilteredLevelPrev      : REAL;     (* Previous cycle filtered level for derivative *)
    rErrorLevel             : REAL;     (* Ammonia level control error *)
    rIntegralTerm           : REAL := 0.0; (* PID Integral term accumulator *)
    rDerivativeTerm         : REAL;     (* PID Derivative term *)
    rKp                     : REAL := 1.25; (* Proportional gain *)
    rKi                     : REAL := 0.15; (* Integral gain *)
    rKd                     : REAL := 0.45; (* Derivative gain *)
    rSaturationTemp         : REAL;     (* Calculated saturation temp based on pressure *)
    bLevelFault             : BOOL;     (* Internal flag for level deviations *)
END_VAR

(* === MAIN SAFETY INTERLOCKS === *)
IF NOT bEmergencyStop THEN
    (* Immediate safe state on SIS intervention *)
    bSystemReady := FALSE;
    rSeawaterPumpSpeed := 0.0;
    rAmmoniaFeedValve := 0.0;
    bVacuumPurgeValve := FALSE;
    bCriticalAlarm := TRUE;
    iState := 0;
    RETURN;
END_IF;

(* === SENSOR NOISE FILTERING === *)
(* First order low-pass filter for noisy liquid level sensor (Time constant ~1s at 10ms cycle) *)
rFilteredLevel := (rAmmoniaLiquidLevel * 0.1) + (rFilteredLevelPrev * 0.9);

(* === THERMODYNAMIC CALCULATIONS === *)
(* Antoine equation approximation for Ammonia Saturation Temperature (deg C) given Pressure (bar) *)
rSaturationTemp := (2000.0 / (15.0 - LN(rAmmoniaInletPressure * 100000.0))) - 273.15;
rSuperheatTemp := rWarmSeawaterTemp - rSaturationTemp;

(* === STATE MACHINE === *)
CASE iState OF
    0: (* IDLE & INITIALIZATION *)
        bSystemReady := FALSE;
        rSeawaterPumpSpeed := 0.0;
        rAmmoniaFeedValve := 0.0;
        bVacuumPurgeValve := FALSE;
        bCriticalAlarm := FALSE;
        rIntegralTerm := 0.0;

        IF bEnable THEN
            iState := 10;
        END_IF;

    10: (* WARM-UP & SEAWATER PRIMING *)
        (* Ramp up seawater pump to prime the heat exchanger *)
        IF rSeawaterPumpSpeed < 50.0 THEN
            rSeawaterPumpSpeed := rSeawaterPumpSpeed + 0.5;
        ELSE
            tStartupDelay(IN := TRUE, PT := T#10S);
            IF tStartupDelay.Q THEN
                tStartupDelay(IN := FALSE);
                iState := 20;
            END_IF;
        END_IF;

    20: (* CASCADE INJECTION & PID CONTROL *)
        bSystemReady := TRUE;

        (* Maintain optimum liquid level via PID Control *)
        rErrorLevel := 500.0 - rFilteredLevel; (* Setpoint is 500 mm *)

        (* Integral with anti-windup *)
        rIntegralTerm := rIntegralTerm + (rErrorLevel * rKi);
        IF rIntegralTerm > 100.0 THEN rIntegralTerm := 100.0; END_IF;
        IF rIntegralTerm < 0.0 THEN rIntegralTerm := 0.0; END_IF;

        rDerivativeTerm := (rFilteredLevel - rFilteredLevelPrev) * rKd;

        rAmmoniaFeedValve := (rErrorLevel * rKp) + rIntegralTerm - rDerivativeTerm;

        (* Clamp valve output *)
        IF rAmmoniaFeedValve > 100.0 THEN rAmmoniaFeedValve := 100.0; END_IF;
        IF rAmmoniaFeedValve < 0.0 THEN rAmmoniaFeedValve := 0.0; END_IF;

        (* Non-Condensable Gas Purging Logic *)
        IF rNonCondensableGasLvl > 150.0 THEN (* 150 ppm threshold *)
            bVacuumPurgeValve := TRUE;
            tPurgeTimer(IN := TRUE, PT := T#5S);
            IF tPurgeTimer.Q THEN
                (* Wait for purge completion or reset if still high later *)
            END_IF;
        ELSE
            bVacuumPurgeValve := FALSE;
            tPurgeTimer(IN := FALSE);
        END_IF;

        (* Fault Detection *)
        IF rFilteredLevel > 800.0 OR rFilteredLevel < 100.0 THEN
            bLevelFault := TRUE;
        ELSE
            bLevelFault := FALSE;
        END_IF;

        IF bLevelFault OR (rSuperheatTemp < 2.0) THEN
            bCriticalAlarm := TRUE;
            iState := 99; (* TRIPPED *)
        END_IF;

        IF NOT bEnable THEN
            iState := 0;
        END_IF;

    99: (* TRIPPED / FAULT STATE *)
        bSystemReady := FALSE;
        rAmmoniaFeedValve := 0.0;
        rSeawaterPumpSpeed := 10.0; (* Keep minimum flow for thermal shock prevention *)
        IF NOT bEnable AND NOT bLevelFault THEN
            bCriticalAlarm := FALSE;
            iState := 0;
        END_IF;

END_CASE;

(* === END OF CYCLE UPDATES === *)
rFilteredLevelPrev := rFilteredLevel;

END_FUNCTION_BLOCK
