FUNCTION_BLOCK FB_HTS_CoolingControl
(*
    High-Temperature Superconducting (HTS) Cable Cooling Control
    Manages Liquid Nitrogen (LN2) sub-cooling loops, cryostat vacuum pressure,
    and cryogenic quench detection.
*)
VAR_INPUT
    bEnable                 : BOOL;   (* Enable Cooling Control *)
    rLN2_SupplyTemp         : REAL;   (* K: LN2 Supply Temperature *)
    rLN2_ReturnTemp         : REAL;   (* K: LN2 Return Temperature *)
    rCryostatVacuum         : REAL;   (* mbar: Cryostat Vacuum Pressure *)
    rCableCurrent           : REAL;   (* A: HTS Cable Current *)
    rCableVoltageDrop       : REAL;   (* V: HTS Cable Voltage Drop *)
    bEmergencyStop          : BOOL;   (* Emergency Stop Signal *)
    bReset                  : BOOL;   (* Reset Faults *)
END_VAR

VAR_OUTPUT
    bPumpRun                : BOOL;   (* Run Sub-cooler Pump *)
    rPumpSpeedCmd           : REAL;   (* %: Pump Speed Command 0-100% *)
    bValveOpen              : BOOL;   (* Open LN2 Supply Valve *)
    rValvePosCmd            : REAL;   (* %: Valve Position Command 0-100% *)
    bQuenchDetected         : BOOL;   (* HTS Quench Detected *)
    bVacuumFault            : BOOL;   (* Cryostat Vacuum Fault *)
    bTempFault              : BOOL;   (* Temperature Limits Exceeded *)
    iState                  : INT;    (* Current State Machine State *)
    bSystemReady            : BOOL;   (* System Ready for Cable Operation *)
END_VAR

VAR
    (* Internal State *)
    rDeltaT                 : REAL;
    rApparentResistance     : REAL;
    tQuenchFilter           : TON;
    tVacuumFilter           : TON;
    tPumpStartDelay         : TON;

    (* PI Controller for Temperature *)
    rKp_Temp                : REAL := 2.5;
    rKi_Temp                : REAL := 0.5;
    rIntegralSum            : REAL;
    rErrorTemp              : REAL;

    (* Constants *)
    c_rMaxTemp              : REAL := 77.0; (* K *)
    c_rTargetTemp           : REAL := 68.0; (* K *)
    c_rMaxDeltaT            : REAL := 5.0;  (* K *)
    c_rMaxVacuum            : REAL := 1.0E-5; (* mbar *)
    c_rQuenchResThreshold   : REAL := 1.0E-4; (* Ohms *)
    c_tQuenchTime           : TIME := T#50MS;
    c_tVacuumTime           : TIME := T#2S;

    bInit                   : BOOL := TRUE;
END_VAR

(* Initialization *)
IF bInit THEN
    iState := 0;
    rIntegralSum := 0.0;
    bInit := FALSE;
END_IF

(* Emergency Stop Handling *)
IF bEmergencyStop THEN
    bPumpRun := FALSE;
    rPumpSpeedCmd := 0.0;
    bValveOpen := FALSE;
    rValvePosCmd := 0.0;
    iState := 99; (* Fault State *)
END_IF

(* Diagnostics & Fault Detection *)
(* 1. Quench Detection: Calculate apparent resistance if current is high enough *)
IF rCableCurrent > 100.0 THEN
    rApparentResistance := rCableVoltageDrop / rCableCurrent;
ELSE
    rApparentResistance := 0.0;
END_IF

tQuenchFilter(IN := (rApparentResistance > c_rQuenchResThreshold), PT := c_tQuenchTime);
IF tQuenchFilter.Q THEN
    bQuenchDetected := TRUE;
    iState := 99;
END_IF

(* 2. Vacuum Monitoring *)
tVacuumFilter(IN := (rCryostatVacuum > c_rMaxVacuum), PT := c_tVacuumTime);
IF tVacuumFilter.Q THEN
    bVacuumFault := TRUE;
    iState := 99;
END_IF

(* 3. Temperature Monitoring *)
rDeltaT := rLN2_ReturnTemp - rLN2_SupplyTemp;
IF rLN2_SupplyTemp > c_rMaxTemp OR rLN2_ReturnTemp > c_rMaxTemp OR rDeltaT > c_rMaxDeltaT THEN
    bTempFault := TRUE;
    iState := 99;
END_IF

(* Fault Reset *)
IF bReset AND NOT bEmergencyStop THEN
    bQuenchDetected := FALSE;
    bVacuumFault := FALSE;
    bTempFault := FALSE;
    IF iState = 99 THEN
        iState := 0;
    END_IF
END_IF

(* State Machine *)
CASE iState OF
    0: (* Standby *)
        bSystemReady := FALSE;
        bPumpRun := FALSE;
        rPumpSpeedCmd := 0.0;
        bValveOpen := FALSE;
        rValvePosCmd := 0.0;
        IF bEnable AND NOT bEmergencyStop AND NOT bQuenchDetected AND NOT bVacuumFault AND NOT bTempFault THEN
            iState := 10;
        END_IF

    10: (* Pre-cooling *)
        bValveOpen := TRUE;
        rValvePosCmd := 25.0; (* Open valve slightly to slowly cool down *)
        (* Wait for supply temp to drop below 75K before starting pump *)
        IF rLN2_SupplyTemp < 75.0 THEN
            iState := 20;
        END_IF

    20: (* Pump Start & Stabilization *)
        bPumpRun := TRUE;
        rPumpSpeedCmd := 50.0;
        rValvePosCmd := 50.0;
        IF rLN2_ReturnTemp < 70.0 AND rLN2_SupplyTemp < 70.0 THEN
            iState := 30;
        END_IF

    30: (* Active Sub-cooling (PID Control) *)
        bSystemReady := TRUE;

        (* Calculate Temperature Error *)
        rErrorTemp := rLN2_ReturnTemp - c_rTargetTemp;

        (* PI Control Algorithm *)
        rIntegralSum := rIntegralSum + (rErrorTemp * rKi_Temp * 0.1); (* Assuming 100ms task cycle *)

        (* Anti-windup *)
        IF rIntegralSum > 100.0 THEN rIntegralSum := 100.0; END_IF;
        IF rIntegralSum < 0.0 THEN rIntegralSum := 0.0; END_IF;

        rPumpSpeedCmd := (rErrorTemp * rKp_Temp) + rIntegralSum;

        (* Clamp Output *)
        IF rPumpSpeedCmd > 100.0 THEN rPumpSpeedCmd := 100.0; END_IF;
        IF rPumpSpeedCmd < 20.0 THEN rPumpSpeedCmd := 20.0; END_IF; (* Minimum flow *)

        rValvePosCmd := rPumpSpeedCmd; (* Simplistic slave operation for valve *)

        IF NOT bEnable THEN
            iState := 0;
        END_IF

    99: (* Fault State *)
        bSystemReady := FALSE;
        bPumpRun := FALSE;
        rPumpSpeedCmd := 0.0;
        bValveOpen := FALSE;
        rValvePosCmd := 0.0; 
END_CASE
END_FUNCTION_BLOCK
