FUNCTION_BLOCK FB_QuantumGradiometer
VAR_INPUT
    bEnable : BOOL; // Enable Gradiometer
    bStartSequence : BOOL; // Start measurement sequence
    fTargetTemperature_nK : LREAL := 50.0; // BEC target temp
    fInterrogationTime_s : LREAL := 1.5; // Free-fall time T
    bRamanLaserReady : BOOL;
    bMagneticCoilsReady : BOOL;
    bCameraReady : BOOL;
END_VAR

VAR_OUTPUT
    eState : E_PackML_State := E_PackML_State.IDLE;
    fMeasuredGravity_mps2 : LREAL;
    fGravityGradient_Eotvos : LREAL;
    fAtomNumber : LREAL;
    bBEC_Achieved : BOOL;
    bMeasurementComplete : BOOL;
    bError : BOOL;
    sErrorMsg : STRING;
END_VAR

VAR
    // Internal States
    eInternalStep : (INIT, MOT_2D_LOADING, MOT_3D_COOLING, OPTICAL_MOLASSES, MAGNETIC_TRAPPING, RF_EVAPORATION, DIPOLE_TRAP_LOADING, RAMAN_PULSE_PI_HALF_1, FREE_EVOLUTION_1, RAMAN_PULSE_PI, FREE_EVOLUTION_2, RAMAN_PULSE_PI_HALF_2, FLUORESCENCE_IMAGING, CALCULATION);

    // Physics constants
    c_k_eff : LREAL := 16105806.0; // Effective wavevector (m^-1)

    // Timers
    fbTimer : TON;

    // Measurement variables
    fPhaseShift : LREAL;
    fUpperCloudPopulation : LREAL;
    fLowerCloudPopulation : LREAL;

    // Simulations / Internal
    fCurrentTemp_uK : LREAL := 300000.0; // Room temp initially
END_VAR

// PackML State Machine
CASE eState OF
    E_PackML_State.IDLE:
        bMeasurementComplete := FALSE;
        IF bEnable AND bRamanLaserReady AND bMagneticCoilsReady THEN
            eState := E_PackML_State.STARTING;
        END_IF

    E_PackML_State.STARTING:
        eInternalStep := INIT;
        bBEC_Achieved := FALSE;
        eState := E_PackML_State.EXECUTE;

    E_PackML_State.EXECUTE:
        // Execute the Atom Interferometry Sequence
        CASE eInternalStep OF
            INIT:
                fCurrentTemp_uK := 300000.0; // 300K
                IF bStartSequence THEN
                    eInternalStep := MOT_2D_LOADING;
                    fbTimer(IN := FALSE);
                END_IF

            MOT_2D_LOADING:
                fbTimer(IN := TRUE, PT := T#500MS);
                IF fbTimer.Q THEN
                    fCurrentTemp_uK := 1000.0; // 1 mK
                    eInternalStep := MOT_3D_COOLING;
                    fbTimer(IN := FALSE);
                END_IF

            MOT_3D_COOLING:
                fbTimer(IN := TRUE, PT := T#2S);
                IF fbTimer.Q THEN
                    fCurrentTemp_uK := 100.0; // 100 uK
                    eInternalStep := OPTICAL_MOLASSES;
                    fbTimer(IN := FALSE);
                END_IF

            OPTICAL_MOLASSES:
                fbTimer(IN := TRUE, PT := T#10MS);
                IF fbTimer.Q THEN
                    fCurrentTemp_uK := 10.0; // 10 uK
                    eInternalStep := MAGNETIC_TRAPPING;
                    fbTimer(IN := FALSE);
                END_IF

            MAGNETIC_TRAPPING:
                fbTimer(IN := TRUE, PT := T#100MS);
                IF fbTimer.Q THEN
                    eInternalStep := RF_EVAPORATION;
                    fbTimer(IN := FALSE);
                END_IF

            RF_EVAPORATION:
                fbTimer(IN := TRUE, PT := T#3S);
                IF fbTimer.Q THEN
                    fCurrentTemp_uK := 1.0; // 1 uK
                    eInternalStep := DIPOLE_TRAP_LOADING;
                    fbTimer(IN := FALSE);
                END_IF

            DIPOLE_TRAP_LOADING:
                fbTimer(IN := TRUE, PT := T#2S);
                IF fbTimer.Q THEN
                    fCurrentTemp_uK := fTargetTemperature_nK / 1000.0; // Target BEC temp
                    bBEC_Achieved := TRUE;
                    fAtomNumber := 1000000.0; // 10^6 atoms in BEC
                    eInternalStep := RAMAN_PULSE_PI_HALF_1;
                    fbTimer(IN := FALSE);
                END_IF

            RAMAN_PULSE_PI_HALF_1:
                // First beam splitter pulse (pi/2)
                // Duration typical ~ 10 us
                fbTimer(IN := TRUE, PT := T#10US);
                IF fbTimer.Q THEN
                    eInternalStep := FREE_EVOLUTION_1;
                    fbTimer(IN := FALSE);
                END_IF

            FREE_EVOLUTION_1:
                // Interrogation time T
                fbTimer(IN := TRUE, PT := LREAL_TO_TIME(fInterrogationTime_s * 1000.0));
                IF fbTimer.Q THEN
                    eInternalStep := RAMAN_PULSE_PI;
                    fbTimer(IN := FALSE);
                END_IF

            RAMAN_PULSE_PI:
                // Mirror pulse (pi)
                // Duration typical ~ 20 us
                fbTimer(IN := TRUE, PT := T#20US);
                IF fbTimer.Q THEN
                    eInternalStep := FREE_EVOLUTION_2;
                    fbTimer(IN := FALSE);
                END_IF

            FREE_EVOLUTION_2:
                // Interrogation time T
                fbTimer(IN := TRUE, PT := LREAL_TO_TIME(fInterrogationTime_s * 1000.0));
                IF fbTimer.Q THEN
                    eInternalStep := RAMAN_PULSE_PI_HALF_2;
                    fbTimer(IN := FALSE);
                END_IF

            RAMAN_PULSE_PI_HALF_2:
                // Recombination pulse (pi/2)
                fbTimer(IN := TRUE, PT := T#10US);
                IF fbTimer.Q THEN
                    eInternalStep := FLUORESCENCE_IMAGING;
                    fbTimer(IN := FALSE);
                END_IF

            FLUORESCENCE_IMAGING:
                // Readout phase
                fbTimer(IN := TRUE, PT := T#50MS);
                IF fbTimer.Q THEN
                    // Simulate fringe extraction
                    fUpperCloudPopulation := 0.45;
                    fLowerCloudPopulation := 0.55;
                    fPhaseShift := ACOS( (fUpperCloudPopulation - fLowerCloudPopulation) / (fUpperCloudPopulation + fLowerCloudPopulation) );
                    eInternalStep := CALCULATION;
                    fbTimer(IN := FALSE);
                END_IF

            CALCULATION:
                // Delta Phi = k_eff * g * T^2
                // g = Delta Phi / (k_eff * T^2)
                fMeasuredGravity_mps2 := fPhaseShift / (c_k_eff * EXPT(fInterrogationTime_s, 2.0));

                // Typical Earth gravity baseline offset for simulation
                fMeasuredGravity_mps2 := 9.80665 + fMeasuredGravity_mps2 * 1e-9;

                // Gravity gradient (simulated using two displaced clouds, normally needs dual interferometer)
                fGravityGradient_Eotvos := 3000.0; // 3000 E

                bMeasurementComplete := TRUE;
                eState := E_PackML_State.COMPLETE;

        END_CASE

    E_PackML_State.COMPLETE:
        IF NOT bStartSequence THEN
            eState := E_PackML_State.IDLE;
        END_IF

    E_PackML_State.ABORTING:
        eState := E_PackML_State.ABORTED;

    E_PackML_State.ABORTED:
        IF bStartSequence THEN // Clear command
            eState := E_PackML_State.IDLE;
        END_IF

END_CASE

IF NOT bEnable THEN
    eState := E_PackML_State.ABORTING;
    bError := TRUE;
    sErrorMsg := 'System Disabled';
END_IF
END_FUNCTION_BLOCK

TYPE E_PackML_State :
(
    IDLE := 0,
    STARTING := 1,
    EXECUTE := 2,
    COMPLETING := 3,
    COMPLETE := 4,
    HOLDING := 5,
    HELD := 6,
    UNHOLDING := 7,
    SUSPENDING := 8,
    SUSPENDED := 9,
    UNSUSPENDING := 10,
    ABORTING := 11,
    ABORTED := 12,
    CLEARING := 13,
    STOPPING := 14,
    STOPPED := 15
);
END_TYPE
