FUNCTION_BLOCK FB_Methanation_Reactor_Control
VAR_INPUT
    rH2_Feed_Flow       : REAL;  // H2 feed flow rate [Nm3/h]
    rCO2_Feed_Flow      : REAL;  // CO2 feed flow rate [Nm3/h]
    rReactor_Temp_1     : REAL;  // Bed 1 temperature [deg C]
    rReactor_Temp_2     : REAL;  // Bed 2 temperature [deg C]
    rReactor_Temp_3     : REAL;  // Bed 3 temperature [deg C]
    rReactor_Pressure   : REAL;  // Reactor pressure [bar]
    rCooling_Water_Temp : REAL;  // Cooling water inlet temperature [deg C]
    rRecycle_Gas_Flow   : REAL;  // Current recycle gas flow rate [Nm3/h]
    bStart_Sequence     : BOOL;
    bEmergency_Stop     : BOOL;
END_VAR

VAR_OUTPUT
    rCooling_Valve_Cmd  : REAL;  // Cooling circuit valve position 0-100%
    rRecycle_Comp_Speed : REAL;  // Recycle compressor speed 0-100%
    rH2_Valve_Cmd       : REAL;  // H2 inlet valve 0-100%
    rCO2_Valve_Cmd      : REAL;  // CO2 inlet valve 0-100%
    bSystem_Ready       : BOOL;
    bAlarm_HighTemp     : BOOL;
    bAlarm_LowRatio     : BOOL;
END_VAR

VAR
    rStoichiometric_Ratio : REAL := 4.0; // Ideal H2/CO2 ratio
    rCurrent_Ratio        : REAL;
    rTarget_Temp_1        : REAL := 300.0;
    rTarget_Temp_2        : REAL := 350.0;
    rTarget_Temp_3        : REAL := 250.0;
    rMax_Temp             : REAL := 450.0;
    rTemp_Error_1         : REAL;
    rTemp_Error_2         : REAL;
    rTemp_Error_3         : REAL;
    rIntegral_Error       : REAL := 0.0;
    rDerivative_Error     : REAL := 0.0;
    rPrev_Error           : REAL := 0.0;
    rKp                   : REAL := 2.5;
    rKi                   : REAL := 0.1;
    rKd                   : REAL := 0.5;
    rPid_Output           : REAL;
    tCycleTime            : TIME := T#100ms;
    iState                : INT := 0; 
END_VAR

// State Machine for Methanation Reactor Startup and Operation
CASE iState OF
    0: // Idle state
        bSystem_Ready := FALSE;
        rCooling_Valve_Cmd := 100.0; // Full cooling on standby
        rRecycle_Comp_Speed := 0.0;
        rH2_Valve_Cmd := 0.0;
        rCO2_Valve_Cmd := 0.0;
        IF bStart_Sequence AND NOT bEmergency_Stop THEN
            iState := 10;
        END_IF;

    10: // Pressurization & Purge with Recycle Gas
        rRecycle_Comp_Speed := 30.0; // Start compressor
        IF rReactor_Pressure > 5.0 THEN
            iState := 20;
        END_IF;
        IF bEmergency_Stop THEN iState := 99; END_IF;

    20: // Feed Introduction and Ratio Control
        IF rCO2_Feed_Flow > 0.0 THEN
            rCurrent_Ratio := rH2_Feed_Flow / rCO2_Feed_Flow;
        ELSE
            rCurrent_Ratio := 0.0;
        END_IF;

        // Ratio Control Loop
        IF rCurrent_Ratio < rStoichiometric_Ratio THEN
            rH2_Valve_Cmd := rH2_Valve_Cmd + 0.5;
            rCO2_Valve_Cmd := rCO2_Valve_Cmd - 0.1;
        ELSIF rCurrent_Ratio > (rStoichiometric_Ratio + 0.2) THEN
            rH2_Valve_Cmd := rH2_Valve_Cmd - 0.5;
            rCO2_Valve_Cmd := rCO2_Valve_Cmd + 0.1;
        END_IF;

        // Safety interlocks
        bAlarm_LowRatio := (rCurrent_Ratio < 3.5);

        // Transition to Thermal Control
        IF rReactor_Temp_1 > 200.0 THEN
            iState := 30;
            bSystem_Ready := TRUE;
        END_IF;
        IF bEmergency_Stop THEN iState := 99; END_IF;

    30: // Sabatier Thermal Regulation (Active Cooling)
        // Multi-stage average error calculation for robust control
        rTemp_Error_1 := rReactor_Temp_1 - rTarget_Temp_1;
        rTemp_Error_2 := rReactor_Temp_2 - rTarget_Temp_2;
        rTemp_Error_3 := rReactor_Temp_3 - rTarget_Temp_3;

        // Weighted average for primary control variable (Bed 2 is hottest)
        rPid_Output := (rTemp_Error_1 * 0.2) + (rTemp_Error_2 * 0.6) + (rTemp_Error_3 * 0.2);

        // PID Calculation
        rIntegral_Error := rIntegral_Error + rPid_Output;
        rDerivative_Error := rPid_Output - rPrev_Error;
        rCooling_Valve_Cmd := (rKp * rPid_Output) + (rKi * rIntegral_Error) + (rKd * rDerivative_Error);
        rPrev_Error := rPid_Output;

        // Valve Saturation limits
        IF rCooling_Valve_Cmd > 100.0 THEN rCooling_Valve_Cmd := 100.0; END_IF;
        IF rCooling_Valve_Cmd < 0.0 THEN rCooling_Valve_Cmd := 0.0; END_IF;

        // Dynamic Recycle Gas Ratio Adjustment for secondary temperature control
        IF rTemp_Error_2 > 20.0 THEN
            rRecycle_Comp_Speed := rRecycle_Comp_Speed + 1.0; // Increase recycle to dilute reactants and cool bed
        ELSIF rTemp_Error_2 < -20.0 THEN
            rRecycle_Comp_Speed := rRecycle_Comp_Speed - 1.0;
        END_IF;
        IF rRecycle_Comp_Speed > 100.0 THEN rRecycle_Comp_Speed := 100.0; END_IF;
        IF rRecycle_Comp_Speed < 20.0 THEN rRecycle_Comp_Speed := 20.0; END_IF;

        // Thermal Runaway Alarm
        bAlarm_HighTemp := (rReactor_Temp_2 > rMax_Temp);
        IF bAlarm_HighTemp OR bEmergency_Stop THEN
            iState := 99;
        END_IF;

    99: // Emergency Shutdown Sequence
        bSystem_Ready := FALSE;
        rH2_Valve_Cmd := 0.0;
        rCO2_Valve_Cmd := 0.0;
        rCooling_Valve_Cmd := 100.0; // Max cooling
        rRecycle_Comp_Speed := 50.0; // Maintain some circulation to distribute heat
        IF rReactor_Temp_2 < 150.0 AND NOT bEmergency_Stop THEN
            iState := 0;
        END_IF;
END_CASE;
END_FUNCTION_BLOCK
