FUNCTION_BLOCK FB_PIDController
VAR_INPUT
    setpoint : REAL;
    processValue : REAL;
    kP : REAL := 1.0;
    kI : REAL := 0.1;
    kD : REAL := 0.01;
END_VAR
VAR_OUTPUT
    output : REAL;
    error : REAL;
END_VAR
VAR
    integral : REAL;
    lastError : REAL;
    derivative : REAL;
END_VAR

// PID calculation
error := setpoint - processValue;
integral := integral + error;
derivative := error - lastError;
output := kP * error + kI * integral + kD * derivative;
lastError := error;

