FUNCTION_BLOCK FB_IndustrialControl
TITLE = 'Direct Lithium Extraction - Resin Desorption and Nanofiltration Control'
VERSION : '1.0'

VAR_INPUT
    bStart_Process : BOOL; // Start the DLE process sequence
    bEmergency_Stop : BOOL; // Emergency stop interlock
    rBrine_Flow_Rate : REAL; // Current inlet brine flow rate (m3/h)
    rResin_Bed_Level : REAL; // Level of resin bed in the column (%)
    rEluent_pH : REAL; // pH of the desorption eluent
    rEluent_Temp : REAL; // Temperature of the eluent (deg C)
    rNF_Feed_Pressure : REAL; // Nanofiltration feed pressure (bar)
    rNF_Permeate_Flow : REAL; // Nanofiltration permeate flow (m3/h)
    bDesorption_Cycle_Req : BOOL; // Request to start desorption
END_VAR

VAR_OUTPUT
    bPump_Brine_Cmd : BOOL; // Command to start brine feed pump
    bValve_Eluent_Cmd : BOOL; // Command to open eluent feed valve
    bPump_NF_Feed_Cmd : BOOL; // Command to start nanofiltration feed pump
    rEluent_Heating_Cmd : REAL; // Control signal for eluent heater (0-100%)
    rNF_Pressure_Ctrl : REAL; // Control signal for NF pressure control valve (0-100%)
    bSystem_Ready : BOOL; // System ready to start
    bAlarm_High_Pressure : BOOL; // Alarm: NF feed pressure too high
    bAlarm_Low_pH : BOOL; // Alarm: Eluent pH out of range
    iProcess_State : INT; // Current state of the DLE process
END_VAR

VAR
    Tmr_Desorption : TON;
    Tmr_NF_Flush : TON;
    rTarget_Eluent_Temp : REAL := 65.0; // Target temperature for optimal desorption
    rTarget_NF_Pressure : REAL := 35.0; // Target pressure for nanofiltration
    rMax_NF_Pressure : REAL := 45.0;
    rMin_Eluent_pH : REAL := 2.5;

    PID_Heater : FB_PID_Controller;
    PID_NF_Pressure : FB_PID_Controller;

    bInit_Done : BOOL := FALSE;
    iState : INT := 0; // Internal state machine variable
END_VAR

// Initialization
IF NOT bInit_Done THEN
    iState := 0;
    bSystem_Ready := TRUE;
    bInit_Done := TRUE;
END_IF;

// Safety and Interlocks
IF bEmergency_Stop THEN
    bPump_Brine_Cmd := FALSE;
    bValve_Eluent_Cmd := FALSE;
    bPump_NF_Feed_Cmd := FALSE;
    rEluent_Heating_Cmd := 0.0;
    rNF_Pressure_Ctrl := 0.0;
    iState := 99; // Error state
    RETURN;
END_IF;

// Alarms Evaluation
IF rNF_Feed_Pressure > rMax_NF_Pressure THEN
    bAlarm_High_Pressure := TRUE;
ELSE
    bAlarm_High_Pressure := FALSE;
END_IF;

IF rEluent_pH < rMin_Eluent_pH THEN
    bAlarm_Low_pH := TRUE;
ELSE
    bAlarm_Low_pH := FALSE;
END_IF;

// Main State Machine
CASE iState OF
    0: // Standby
        bSystem_Ready := TRUE;
        IF bStart_Process AND NOT bAlarm_High_Pressure AND NOT bAlarm_Low_pH THEN
            iState := 10;
            bSystem_Ready := FALSE;
        END_IF;

    10: // Adsorption Phase - Loading Resin
        bPump_Brine_Cmd := TRUE;
        bValve_Eluent_Cmd := FALSE;
        bPump_NF_Feed_Cmd := FALSE;

        // Monitor resin bed loading
        IF bDesorption_Cycle_Req OR (rResin_Bed_Level > 95.0) THEN
            bPump_Brine_Cmd := FALSE;
            iState := 20; // Move to Desorption preparation
        END_IF;

    20: // Desorption Phase - Eluent Heating and Pumping
        // Control Eluent Temperature
        PID_Heater(
            rSetpoint := rTarget_Eluent_Temp,
            rProcessValue := rEluent_Temp,
            bEnable := TRUE,
            rControlSignal => rEluent_Heating_Cmd
        );

        IF rEluent_Temp >= (rTarget_Eluent_Temp - 2.0) THEN
            bValve_Eluent_Cmd := TRUE;
            Tmr_Desorption(IN := TRUE, PT := T#45M); // 45 minute desorption cycle

            IF Tmr_Desorption.Q THEN
                bValve_Eluent_Cmd := FALSE;
                Tmr_Desorption(IN := FALSE); // Reset timer
                rEluent_Heating_Cmd := 0.0;
                iState := 30; // Move to Nanofiltration
            END_IF;
        END_IF;

    30: // Nanofiltration Phase - Cross-flow Flux Control
        bPump_NF_Feed_Cmd := TRUE;

        // Control NF pressure for optimal cross-flow flux
        PID_NF_Pressure(
            rSetpoint := rTarget_NF_Pressure,
            rProcessValue := rNF_Feed_Pressure,
            bEnable := TRUE,
            rControlSignal => rNF_Pressure_Ctrl
        );

        // Simulate end of batch based on permeate flow or time
        Tmr_NF_Flush(IN := TRUE, PT := T#2H);
        IF Tmr_NF_Flush.Q OR bAlarm_High_Pressure THEN
            bPump_NF_Feed_Cmd := FALSE;
            rNF_Pressure_Ctrl := 0.0;
            Tmr_NF_Flush(IN := FALSE);
            iState := 0; // Return to standby
        END_IF;

    99: // Error/Emergency State
        bPump_Brine_Cmd := FALSE;
        bValve_Eluent_Cmd := FALSE;
        bPump_NF_Feed_Cmd := FALSE;
        rEluent_Heating_Cmd := 0.0;
        rNF_Pressure_Ctrl := 0.0;

        IF NOT bEmergency_Stop AND NOT bAlarm_High_Pressure AND NOT bAlarm_Low_pH THEN
            iState := 0; // Reset if clear
        END_IF;

END_CASE;

iProcess_State := iState;

END_FUNCTION_BLOCK
