    rHyperbaricPressure     : REAL;     (* Internal vessel pressure [Bar], range 350-450 *)
    rAmbientThermalSinkTemp : REAL;     (* Deep-sea external cooling water temperature [deg C] *)
    rDissolvedH2            : REAL;     (* Dissolved Hydrogen concentration [ppm] *)
    rDissolvedH2S           : REAL;     (* Dissolved Hydrogen Sulfide concentration [ppm] *)
