    bSafetyVentingActive    : BOOL;     (* Hyperbaric relief venting status *)
    rHeaterControlOutput    : REAL;     (* 0.0 - 100.0% signal to extreme high-temp localized heater *)
    rCoolantFlowValve       : REAL;     (* 0.0 - 100.0% signal for ambient deep-sea cooling jacket *)
    rGasMixRatioSetPoint    : REAL;     (* Commanded H2/H2S mass flow mix ratio controller SP *)
    bCriticalAlarm          : BOOL;     (* Life safety / Reactor integrity compromise alarm *)
END_VAR

VAR
    (* Internal State and Timers *)
    iOperationState         : INT := 0; 
    tStabilizationTimer     : TON;
    tSafetyDelay            : TON;

    (* Cascade Control Variables *)
    rTargetH2Ratio          : REAL := 1.25; 
    rErrorRatio             : REAL := 0.0;
    rRatioIntegral          : REAL := 0.0;
    rRatioDerivative        : REAL := 0.0;
    rLastRatioError         : REAL := 0.0;

    (* Thermal Control Variables *)
    rTargetTemp             : REAL := 120.5; (* Typical hyper-thermophile target *)
    rTempError              : REAL := 0.0;

    (* Constants *)
    Kp_Ratio : REAL := 0.55;
    Ki_Ratio : REAL := 0.12;
    Kd_Ratio : REAL := 0.05;
END_VAR

(* === MAIN LOGIC === *)
(* 1. Safety and Interlock Processing *)
IF NOT bEmergencyStop OR NOT bSystemEnable THEN
    bSystemReady := FALSE;
    bSafetyVentingActive := TRUE;
    rHeaterControlOutput := 0.0;
    rCoolantFlowValve := 100.0; (* Fail open to max cooling *)
    rGasMixRatioSetPoint := 0.0;
    bCriticalAlarm := TRUE;
    iOperationState := 0;
    RETURN;
END_IF;

(* 2. Hyperbaric Over-Pressure Protection *)
IF rHyperbaricPressure > 425.0 THEN
    bSafetyVentingActive := TRUE;
    bCriticalAlarm := TRUE;
ELSE
    bSafetyVentingActive := FALSE;
    bCriticalAlarm := FALSE;
END_IF;

(* 3. State Machine for Continuous Culture Operations *)
CASE iOperationState OF
    0: (* IDLE & SYSTEM CHECKS *)
        IF bSystemEnable AND (rHyperbaricPressure > 380.0) THEN
            iOperationState := 10;
        END_IF;

    10: (* THERMAL EQUILIBRATION *)
        (* Basic Proportional Thermal Control utilizing Ambient Sink *)
        rTempError := rTargetTemp - rReactorInternalTemp;

        IF rTempError > 0.0 THEN
            rHeaterControlOutput := LIMIT(0.0, rTempError * 5.0, 100.0);
            rCoolantFlowValve := 0.0;
        ELSE
            rHeaterControlOutput := 0.0;
            (* Exploit the ambient thermal sink proportional to error *)
            rCoolantFlowValve := LIMIT(0.0, ABS(rTempError) * 2.5, 100.0);
        END_IF;

        tStabilizationTimer(IN := (ABS(rTempError) < 1.0), PT := T#30S);
        IF tStabilizationTimer.Q THEN
            tStabilizationTimer(IN := FALSE);
            iOperationState := 20;
        END_IF;

    20: (* METABOLIC GAS CASCADING CONTROL *)
        bSystemReady := TRUE;

        (* Maintain Thermal Stability *)
        rTempError := rTargetTemp - rReactorInternalTemp;
        IF rTempError > 0.0 THEN
            rHeaterControlOutput := LIMIT(0.0, rTempError * 5.0, 100.0);
            rCoolantFlowValve := 0.0;
        ELSE
            rHeaterControlOutput := 0.0;
            rCoolantFlowValve := LIMIT(0.0, ABS(rTempError) * 2.5, 100.0);
        END_IF;

        (* PID calculation for Dissolved H2 / H2S ratio *)
        IF rDissolvedH2S > 0.0 THEN
            rErrorRatio := rTargetH2Ratio - (rDissolvedH2 / rDissolvedH2S);

            rRatioIntegral := rRatioIntegral + (rErrorRatio * 0.1); (* Assuming 100ms cycle time eq. *)
            rRatioIntegral := LIMIT(-50.0, rRatioIntegral, 50.0); (* Anti-windup *)

            rRatioDerivative := (rErrorRatio - rLastRatioError) / 0.1;
            rLastRatioError := rErrorRatio;

            rGasMixRatioSetPoint := (Kp_Ratio * rErrorRatio) + (Ki_Ratio * rRatioIntegral) + (Kd_Ratio * rRatioDerivative);
            rGasMixRatioSetPoint := LIMIT(0.0, rGasMixRatioSetPoint, 100.0);
        ELSE
            rGasMixRatioSetPoint := 50.0; (* Safe fallback injection ratio *)
        END_IF;

        IF NOT bSystemEnable THEN
            iOperationState := 0;
            bSystemReady := FALSE;
        END_IF;

    ELSE
        iOperationState := 0;
END_CASE;

END_FUNCTION_BLOCK
