    bHVAC_Fault : Bool;
    bRobot_PN_Fault : Bool;
END_VAR

BEGIN
    // Diagnostics & Fault Handling
    #bRobot_PN_Fault := (#wPN_Status_Word AND 16#0001) = 0; // Check heartbeat bit 0
    #bHVAC_Fault := (#rTemp_Actual > 30.0) OR (#rHumidity_Actual > 80.0);

    #tConveyorTimeout(IN:=#bConveyor_Motor AND NOT #bCar_In_Position, PT:=T#10s);
    #bConveyor_Fault := NOT #tConveyorTimeout.Q AND #bConveyor_Motor;

    #bFault_Active := #bRobot_PN_Fault OR #bHVAC_Fault OR #bConveyor_Fault;

    IF #bConveyor_Fault THEN #iFault_Code := 101; 
    ELSIF #bHVAC_Fault THEN #iFault_Code := 201;
    ELSIF #bRobot_PN_Fault THEN #iFault_Code := 301;
    ELSE #iFault_Code := 0; 
    END_IF;

    // Start/Stop
    IF #bStop_PB OR #bFault_Active THEN
        #bSystem_Running := FALSE;
    ELSIF #bStart_PB AND NOT #bFault_Active THEN
        #bSystem_Running := TRUE;
    END_IF;

    IF NOT #bSystem_Running THEN
        #iState := 0;
    ELSIF #bSystem_Running AND #iState = 0 THEN
        #iState := 1;
    END_IF;

    // State Machine
    CASE #iState OF
        0: // Stop
            #bConveyor_Motor := FALSE;
            #bRobot_Enable := FALSE;
            #wPN_Control_Word := 16#0000;
        1: // Index
            #bRobot_Enable := FALSE;
            #wPN_Control_Word := 16#0000;
            IF NOT #bCar_In_Position THEN
                #bConveyor_Motor := TRUE;
            ELSE
                #bConveyor_Motor := FALSE;
                #iState := 2;
            END_IF;
        2: // Painting
            #bConveyor_Motor := FALSE;
            IF NOT #bHVAC_Fault THEN
                #bRobot_Enable := TRUE;
                #wPN_Control_Word := 16#0001; // Send Enable command over Profinet
            END_IF;
    END_CASE;

    // HVAC PID
    #instPID_Temp(Setpoint := 22.0, Input := #rTemp_Actual, Reset := NOT #bSystem_Running, Output => #rHeater_Valve);
    #instPID_Humidity(Setpoint := 55.0, Input := #rHumidity_Actual, Reset := NOT #bSystem_Running, Output => #rHumidifier_Valve);

    // Overspray
    #bExhaust_Fan := #bSystem_Running AND (#rOverspray_Concentration > 20.0);
    #bCapture_Pump := #bSystem_Running AND (#rOverspray_Concentration > 60.0);
END_FUNCTION_BLOCK
