FUNCTION_BLOCK FB_SubOrbitalAvionics
VAR_INPUT
    bLaunchEnable : BOOL; // Main launch command
    fAltitude_m : REAL; // Current altitude from radar/baro
    fVelocity_ms : REAL; // Current velocity
    fPitchAngle_deg : REAL; // Current pitch angle from IMU
    fYawAngle_deg : REAL; // Current yaw angle from IMU
    fRollAngle_deg : REAL; // Current roll angle from IMU
    fTargetPitch_deg : REAL; // Desired pitch profile
    fTargetYaw_deg : REAL; // Desired yaw profile
    bStageSeparationCmd : BOOL; // Command to separate stage
END_VAR
VAR_OUTPUT
    fTVCPitchCmd : REAL; // Thrust Vector Control pitch actuator command
    fTVCYawCmd : REAL; // Thrust Vector Control yaw actuator command
    bIgniteMotor : BOOL; // Solid rocket motor ignition
    bFireExplosiveBolts : BOOL; // Stage separation bolts
    bRCS_PitchUp : BOOL; // Cold gas RCS pitch up
    bRCS_PitchDown : BOOL; // Cold gas RCS pitch down
    bRCS_YawLeft : BOOL; // Cold gas RCS yaw left
    bRCS_YawRight : BOOL; // Cold gas RCS yaw right
    bRCS_RollCW : BOOL; // Cold gas RCS roll clockwise
    bRCS_RollCCW : BOOL; // Cold gas RCS roll counter-clockwise
    eFlightPhase : INT; // Current flight phase state machine
END_VAR
VAR
    // PID State Variables for TVC
    fPitchError : REAL;
    fPitchIntegral : REAL;
    fPitchDerivative : REAL;
    fPitchLastError : REAL;

    fYawError : REAL;
    fYawIntegral : REAL;
    fYawDerivative : REAL;
    fYawLastError : REAL;

    // RCS Deadband
    fRCSDeadband : REAL := 2.5; // Degrees

    // Constants
    Kp_TVC : REAL := 1.25;
    Ki_TVC : REAL := 0.05;
    Kd_TVC : REAL := 0.35;

    // State machine constants
    PHASE_IDLE : INT := 0;
    PHASE_IGNITION : INT := 1;
    PHASE_ASCENT : INT := 2;
    PHASE_SEPARATION : INT := 3;
    PHASE_COAST : INT := 4;

    tStateTimer : TIME;
    fDt : REAL := 0.01; // 10ms cycle time
END_VAR

// State Machine and Control Logic
CASE eFlightPhase OF
    PHASE_IDLE:
        bIgniteMotor := FALSE;
        bFireExplosiveBolts := FALSE;
        fTVCPitchCmd := 0.0;
        fTVCYawCmd := 0.0;
        IF bLaunchEnable THEN
            eFlightPhase := PHASE_IGNITION;
        END_IF;

    PHASE_IGNITION:
        bIgniteMotor := TRUE;
        // Wait for motor to build thrust, simplified as altitude check
        IF fAltitude_m > 10.0 THEN
            eFlightPhase := PHASE_ASCENT;
        END_IF;

    PHASE_ASCENT:
        // Active Thrust Vector Control (TVC) using PID
        fPitchError := fTargetPitch_deg - fPitchAngle_deg;
        fPitchIntegral := fPitchIntegral + (fPitchError * fDt);
        fPitchDerivative := (fPitchError - fPitchLastError) / fDt;
        fTVCPitchCmd := (Kp_TVC * fPitchError) + (Ki_TVC * fPitchIntegral) + (Kd_TVC * fPitchDerivative);
        fPitchLastError := fPitchError;

        fYawError := fTargetYaw_deg - fYawAngle_deg;
        fYawIntegral := fYawIntegral + (fYawError * fDt);
        fYawDerivative := (fYawError - fYawLastError) / fDt;
        fTVCYawCmd := (Kp_TVC * fYawError) + (Ki_TVC * fYawIntegral) + (Kd_TVC * fYawDerivative);
        fYawLastError := fYawError;

        // Limits for TVC Actuators
        IF fTVCPitchCmd > 15.0 THEN fTVCPitchCmd := 15.0; END_IF;
        IF fTVCPitchCmd < -15.0 THEN fTVCPitchCmd := -15.0; END_IF;
        IF fTVCYawCmd > 15.0 THEN fTVCYawCmd := 15.0; END_IF;
        IF fTVCYawCmd < -15.0 THEN fTVCYawCmd := -15.0; END_IF;

        IF bStageSeparationCmd OR fAltitude_m > 50000.0 THEN
            eFlightPhase := PHASE_SEPARATION;
        END_IF;

    PHASE_SEPARATION:
        bFireExplosiveBolts := TRUE;
        // Turn off TVC commands as main motor is separated
        fTVCPitchCmd := 0.0;
        fTVCYawCmd := 0.0;
        eFlightPhase := PHASE_COAST;

    PHASE_COAST:
        // Exatmospheric coast phase using cold-gas RCS for attitude stabilization
        bFireExplosiveBolts := FALSE; // Pulse complete

        // Pitch RCS
        bRCS_PitchUp := (fPitchAngle_deg < (fTargetPitch_deg - fRCSDeadband));
        bRCS_PitchDown := (fPitchAngle_deg > (fTargetPitch_deg + fRCSDeadband));

        // Yaw RCS
        bRCS_YawLeft := (fYawAngle_deg < (fTargetYaw_deg - fRCSDeadband));
        bRCS_YawRight := (fYawAngle_deg > (fTargetYaw_deg + fRCSDeadband));

        // Roll RCS (target roll is 0)
        bRCS_RollCW := (fRollAngle_deg < -fRCSDeadband);
        bRCS_RollCCW := (fRollAngle_deg > fRCSDeadband);

    ELSE
        // Safe state
        eFlightPhase := PHASE_IDLE;
END_CASE;
END_FUNCTION_BLOCK
