(*
* ==============================================================================
* FUNCTION BLOCK: BATHYSCAPHE_VBS_CTRL
* DESCRIPTION: Deep-Sea Bathyscaphe Variable Ballast System
* FEATURES:
*   - High-pressure seawater pump sequencing (10,000m / 1,000 bar head)
*   - Iron shot magnetic hopper drop for emergency surfacing (Failsafe)
*   - Pitch and trim compensation via closed-loop mercury transfer
* ==============================================================================
*)

FUNCTION_BLOCK BATHYSCAPHE_VBS_CTRL
VAR_INPUT
    xEnable                  : BOOL;   (* System Enable *)
    xEmergencySurface        : BOOL;   (* Dead-man switch or emergency abort trigger *)

    rCurrentDepth            : REAL;   (* Current depth in meters (0 to 11000.0) *)
    rTargetDepth             : REAL;   (* Commanded depth in meters *)

    rCurrentPitch            : REAL;   (* Current pitch angle in degrees (-45.0 to 45.0) *)
    rTargetPitch             : REAL;   (* Commanded pitch angle *)

    rExternalPressureBar     : REAL;   (* Ambient hydrostatic pressure in Bar *)
    rInternalVBSLevel        : REAL;   (* 0.0 to 100.0 % of variable ballast tank *)

    xVBSPumpFault            : BOOL;
    xHgPumpFault             : BOOL;
END_VAR

VAR_OUTPUT
    xSeawaterPumpRun         : BOOL;   (* Command HP seawater pump *)
    xSeawaterFloodValve      : BOOL;   (* Command flood valve (ingress) *)
    xSeawaterDischargeValve  : BOOL;   (* Command discharge valve (egress) *)

    xMagHopper1Power         : BOOL;   (* Power to FWD iron shot hopper electromagnet (Failsafe low) *)
    xMagHopper2Power         : BOOL;   (* Power to AFT iron shot hopper electromagnet (Failsafe low) *)

    xHgPumpFwd               : BOOL;   (* Mercury transfer pump to forward bladder *)
    xHgPumpAft               : BOOL;   (* Mercury transfer pump to aft bladder *)

    dwAlarmWord              : DWORD;
    iState                   : INT;
END_VAR

VAR
    (* Timers *)
    tonValveDelay            : TON;
    tonPumpCooldown          : TON;
    tonHopperDelay           : TON;
    tonTrimDelay             : TON;

    (* Internal State *)
    rDepthDeadband           : REAL := 2.5; (* meters *)
    rPitchDeadband           : REAL := 0.5; (* degrees *)

    bDepthDiff               : REAL;
    bPitchDiff               : REAL;

    xPumpCooling             : BOOL;
    xEmergencyActive         : BOOL;

    eSubState                : INT := 0;
END_VAR

(* 1. Emergency Overrides and Failsafes *)
IF xEmergencySurface OR NOT xEnable THEN
    xEmergencyActive := TRUE;

    (* Cut power to electromagnets -> Iron shot drops *)
    xMagHopper1Power := FALSE;

    (* Drop hopper 2 with a slight delay to maintain pitch stability if possible, or immediately if disabled *)
    tonHopperDelay(IN := xEmergencyActive, PT := T#2S);
    IF tonHopperDelay.Q OR NOT xEnable THEN
        xMagHopper2Power := FALSE;
    END_IF;

    (* Secure all fluid transfer *)
    xSeawaterPumpRun := FALSE;
    xSeawaterFloodValve := FALSE;
    xSeawaterDischargeValve := FALSE;
    xHgPumpFwd := FALSE;
    xHgPumpAft := FALSE;

    iState := 999; (* EMERGENCY STATE *)
    dwAlarmWord := dwAlarmWord OR 16#00000001;
    RETURN; (* Halt further logic processing *)
ELSE
    xEmergencyActive := FALSE;
    xMagHopper1Power := TRUE;
    xMagHopper2Power := TRUE;
    tonHopperDelay(IN := FALSE);
    dwAlarmWord := dwAlarmWord AND 16#FFFFFFFE;
END_IF;

(* 2. Pitch & Trim Compensation (Mercury Transfer) *)
bPitchDiff := rTargetPitch - rCurrentPitch;

IF ABS(bPitchDiff) > rPitchDeadband AND NOT xHgPumpFault THEN
    tonTrimDelay(IN := TRUE, PT := T#1S);
    IF tonTrimDelay.Q THEN
        IF bPitchDiff > 0.0 THEN
            (* Need to pitch UP (Bow up) -> Move Mercury AFT *)
            xHgPumpAft := TRUE;
            xHgPumpFwd := FALSE;
        ELSE
            (* Need to pitch DOWN (Bow down) -> Move Mercury FWD *)
            xHgPumpFwd := TRUE;
            xHgPumpAft := FALSE;
        END_IF;
    END_IF;
ELSE
    tonTrimDelay(IN := FALSE);
    xHgPumpFwd := FALSE;
    xHgPumpAft := FALSE;
END_IF;

(* 3. Variable Ballast System (Depth Control) *)
bDepthDiff := rTargetDepth - rCurrentDepth;
tonPumpCooldown(IN := xPumpCooling, PT := T#5M);
IF tonPumpCooldown.Q THEN
    xPumpCooling := FALSE;
END_IF;

(* Protect pump against high head pressures over 1000 bar limits if needed, though rated for 10000m *)
IF rExternalPressureBar > 1050.0 THEN
    dwAlarmWord := dwAlarmWord OR 16#00000002; (* CRITICAL OVERPRESSURE *)
ELSE
    dwAlarmWord := dwAlarmWord AND 16#FFFFFFFD;
END_IF;

CASE eSubState OF
    0: (* IDLE *)
        xSeawaterFloodValve := FALSE;
        xSeawaterDischargeValve := FALSE;
        xSeawaterPumpRun := FALSE;

        IF ABS(bDepthDiff) > rDepthDeadband THEN
            IF bDepthDiff > 0.0 AND rInternalVBSLevel < 98.0 THEN
                (* We need to go deeper -> Flood VBS (Ingress) *)
                eSubState := 10;
            ELSIF bDepthDiff < 0.0 AND rInternalVBSLevel > 2.0 AND NOT xVBSPumpFault AND NOT xPumpCooling THEN
                (* We need to go shallower -> Pump out VBS against hydrostatic head (Egress) *)
                eSubState := 20;
            END_IF;
        END_IF;

    10: (* FLOODING (Descending) *)
        (* Hydrostatic pressure pushes water IN, no pump needed *)
        xSeawaterFloodValve := TRUE;
        IF (rTargetDepth - rCurrentDepth) <= (rDepthDeadband * 0.5) OR rInternalVBSLevel >= 99.0 THEN
            xSeawaterFloodValve := FALSE;
            eSubState := 0;
        END_IF;

    20: (* PUMPING (Ascending) against 10,000m head *)
        (* Sequence: Open discharge valve -> wait -> Start Pump *)
        xSeawaterDischargeValve := TRUE;
        tonValveDelay(IN := TRUE, PT := T#3S);

        IF tonValveDelay.Q THEN
            xSeawaterPumpRun := TRUE;

            IF (rTargetDepth - rCurrentDepth) >= -(rDepthDeadband * 0.5) OR rInternalVBSLevel <= 1.0 OR xVBSPumpFault THEN
                xSeawaterPumpRun := FALSE;
                eSubState := 21; (* Proceed to secure *)
            END_IF;
        END_IF;

    21: (* SECURE PUMPING *)
        xSeawaterDischargeValve := FALSE;
        tonValveDelay(IN := FALSE);
        xPumpCooling := TRUE; (* Force cooldown period after high-load pump cycle *)
        eSubState := 0;

    ELSE
        eSubState := 0;
END_CASE;

iState := eSubState;

END_FUNCTION_BLOCK
