(*
=====================================================================================
Function Block: FB_ArtificialPhotosynthesis
Description:  Advanced Photoelectrochemical (PEC) Solar Fuel Generator & 
              CO2 Reduction Controller.
              Manages TiO2/Silicon tandem photoanodes, dynamically adjusts
              bias voltage based on solar irradiance, and controls MFCs for
              perfect 2:1 H2:CO syngas ratio for Fischer-Tropsch synthesis.
Author:       Principal Biochemical Engineer, Lumina Elite
=====================================================================================
*)
FUNCTION_BLOCK FB_ArtificialPhotosynthesis
VAR_INPUT
    bEnable                 : BOOL;   (* Enable the Artificial Photosynthesis sequence *)
    bReset                  : BOOL;   (* Acknowledge and reset alarms *)

    (* Environmental & Sensor Inputs *)
    fSolarIrradiance        : LREAL;  (* Incident solar irradiance (W/m^2) *)
    fCellTemperature        : LREAL;  (* PEC Cell Temperature (deg C) *)

    (* Gas & Flow Sensors *)
    fH2ProductionRate       : LREAL;  (* Measured H2 production (mol/s) *)
    fCOProductionRate       : LREAL;  (* Measured CO production (mol/s) *)
    fElectrolytepH          : LREAL;  (* pH of the electrolyte solution *)

    (* Redundant Sensor Checks *)
    fSolarIrradiance_Red    : LREAL;  (* Redundant Irradiance sensor *)
    fCellTemperature_Red    : LREAL;  (* Redundant Temp sensor *)
END_VAR

VAR_OUTPUT
    (* Actuator & Control Outputs *)
    fAppliedBiasVoltage     : LREAL;  (* Potentiostat applied bias voltage (V) *)
    fCO2BubblingRate        : LREAL;  (* Mass Flow Controller CO2 flow (sccm) *)
    fPEMHydrationFlow       : LREAL;  (* Proton exchange membrane hydration rate (mL/min) *)

    (* PackML State Outputs *)
    eState                  : E_PackML_State; (* Current PackML State *)
    bActive                 : BOOL;   (* System is actively processing *)
    bError                  : BOOL;   (* Critical Error flag *)

    (* Process Metrics *)
    fCurrentSyngasRatio     : LREAL;  (* Calculated H2:CO ratio *)
    fFaradaicEfficiency     : LREAL;  (* Overall Faradaic Efficiency (%) *)
END_VAR

VAR
    (* Internal PID Controllers *)
    fbVoltagePID            : FB_PID; (* PID for Bias Voltage vs Irradiance *)
    fbSyngasRatioPID        : FB_PID; (* PID for Syngas Ratio control *)
    fbTempControlPID        : FB_PID; (* PID for Cell Cooling/Heating *)

    (* Sensor Validation *)
    fValidatedIrradiance    : LREAL;
    fValidatedTemp          : LREAL;
    bSensorMismatch         : BOOL;

    (* Constants & Limits *)
    MAX_BIAS_VOLTAGE        : LREAL := 3.5;    (* Maximum allowed applied bias (V) *)
    MIN_BIAS_VOLTAGE        : LREAL := 1.23;   (* Thermodynamic minimum for water splitting (V) *)
    TARGET_SYNGAS_RATIO     : LREAL := 2.0;    (* Target H2:CO ratio for FT Synthesis *)
    MAX_TEMP_LIMIT          : LREAL := 85.0;   (* Max safe operating temp (deg C) *)

    (* State Machine Timers *)
    tonStartDelay           : TON;
    tonPurgeTimer           : TON;

    (* Internal State Variables *)
    fTargetVoltage          : LREAL;
    fRatioError             : LREAL;
END_VAR

(* ---------------------------------------------------------------------------------- *)
(* 1. Sensor Validation & Diagnostics                                                 *)
(* ---------------------------------------------------------------------------------- *)
IF ABS(fSolarIrradiance - fSolarIrradiance_Red) > 50.0 THEN
    bSensorMismatch := TRUE;
    fValidatedIrradiance := MAX(fSolarIrradiance, fSolarIrradiance_Red); (* Conservative fail-safe *)
ELSE
    bSensorMismatch := FALSE;
    fValidatedIrradiance := (fSolarIrradiance + fSolarIrradiance_Red) / 2.0;
END_IF;

IF ABS(fCellTemperature - fCellTemperature_Red) > 5.0 THEN
    bSensorMismatch := TRUE;
    fValidatedTemp := MAX(fCellTemperature, fCellTemperature_Red);
ELSE
    fValidatedTemp := (fCellTemperature + fCellTemperature_Red) / 2.0;
END_IF;

(* Calculate Current Syngas Ratio (Protect against division by zero) *)
IF fCOProductionRate > 0.0001 THEN
    fCurrentSyngasRatio := fH2ProductionRate / fCOProductionRate;
ELSE
    fCurrentSyngasRatio := 999.9; (* Indication of zero CO *)
END_IF;

(* ---------------------------------------------------------------------------------- *)
(* 2. PackML State Machine Implementation                                             *)
(* ---------------------------------------------------------------------------------- *)
IF bReset THEN
    eState := E_PackML_State.CLEARED;
    bError := FALSE;
    bSensorMismatch := FALSE;
END_IF;

(* Hard Safety Interlocks *)
IF fValidatedTemp > MAX_TEMP_LIMIT OR bSensorMismatch THEN
    eState := E_PackML_State.ABORTED;
END_IF;

CASE eState OF
    E_PackML_State.STOPPED:
        bActive := FALSE;
        fAppliedBiasVoltage := 0.0;
        fCO2BubblingRate := 0.0;
        fPEMHydrationFlow := 0.0;

        IF bEnable THEN
            eState := E_PackML_State.STARTING;
        END_IF;

    E_PackML_State.STARTING:
        bActive := TRUE;
        (* Initiate system purge with inert gas before bias application *)
        tonPurgeTimer(IN:=TRUE, PT:=T#30S);

        IF tonPurgeTimer.Q THEN
            tonPurgeTimer(IN:=FALSE);
            eState := E_PackML_State.EXECUTE;
        END_IF;

    E_PackML_State.EXECUTE:
        bActive := TRUE;

        (* 2a. Dynamic Bias Voltage Control based on Solar Irradiance *)
        (* As irradiance increases, photovoltage increases, so we can reduce applied bias *)
        fTargetVoltage := MAX_BIAS_VOLTAGE - (fValidatedIrradiance * 0.0015);

        (* Clamp Target Voltage *)
        IF fTargetVoltage < MIN_BIAS_VOLTAGE THEN
            fTargetVoltage := MIN_BIAS_VOLTAGE;
        ELSIF fTargetVoltage > MAX_BIAS_VOLTAGE THEN
            fTargetVoltage := MAX_BIAS_VOLTAGE;
        END_IF;

        fbVoltagePID(
            rSetpoint := fTargetVoltage,
            rProcessValue := fAppliedBiasVoltage, (* Simulating closed loop on the potentiostat *)
            Kp := 0.85,
            Ki := 0.12,
            Kd := 0.01,
            rOutput => fAppliedBiasVoltage
        );

        (* 2b. Syngas Ratio Optimization *)
        (* Adjust CO2 bubbling and PEM hydration to balance CO and H2 generation *)
        fRatioError := TARGET_SYNGAS_RATIO - fCurrentSyngasRatio;

        fbSyngasRatioPID(
            rSetpoint := TARGET_SYNGAS_RATIO,
            rProcessValue := fCurrentSyngasRatio,
            Kp := 2.5,
            Ki := 0.4,
            Kd := 0.05
        );

        (* If Ratio > 2.0 (Too much H2), increase CO2 Bubbling *)
        IF fRatioError < 0.0 THEN
            fCO2BubblingRate := LIMIT(0.0, fCO2BubblingRate + fbSyngasRatioPID.rOutput, 500.0);
            fPEMHydrationFlow := LIMIT(10.0, fPEMHydrationFlow - 0.5, 100.0);
        (* If Ratio < 2.0 (Too much CO), increase PEM Hydration (water for protons) *)
        ELSE
            fCO2BubblingRate := LIMIT(0.0, fCO2BubblingRate - fbSyngasRatioPID.rOutput, 500.0);
            fPEMHydrationFlow := LIMIT(10.0, fPEMHydrationFlow + 1.0, 100.0);
        END_IF;

        IF NOT bEnable THEN
            eState := E_PackML_State.STOPPING;
        END_IF;

    E_PackML_State.STOPPING:
        bActive := FALSE;
        fAppliedBiasVoltage := fAppliedBiasVoltage * 0.9; (* Ramp down *)
        fCO2BubblingRate := 0.0;

        IF fAppliedBiasVoltage < 0.1 THEN
            fAppliedBiasVoltage := 0.0;
            eState := E_PackML_State.STOPPED;
        END_IF;

    E_PackML_State.ABORTED:
        bActive := FALSE;
        bError := TRUE;
        fAppliedBiasVoltage := 0.0;
        fCO2BubblingRate := 0.0;
        fPEMHydrationFlow := 100.0; (* Flood with water to quench *)

    E_PackML_State.CLEARED:
        eState := E_PackML_State.STOPPED;

END_CASE;

(* Calculate Fake Faradaic Efficiency for Telemetry *)
fFaradaicEfficiency := 85.0 + (fValidatedIrradiance * 0.01) - (ABS(TARGET_SYNGAS_RATIO - fCurrentSyngasRatio) * 5.0);
fFaradaicEfficiency := LIMIT(0.0, fFaradaicEfficiency, 99.9);

END_FUNCTION_BLOCK
