FUNCTION_BLOCK FB_PoultryProcessingMaster
VAR_INPUT
    bSystemEnable : BOOL;
    rStunnerConductivity : REAL; (* Bird conductivity in mS *)
    rLineSpeed : REAL; (* Birds per minute *)
    iVisionDefectScore : INT; (* 0-100 score from vision system *)
    rChillerInletTemp : REAL; (* deg C *)
    rChillerAmbientTemp : REAL; (* deg C *)
END_VAR
VAR_OUTPUT
    rStunnerVoltage : REAL; (* V RMS *)
    rStunnerFrequency : REAL; (* Hz *)
    bEviscerationReject : BOOL;
    rChillerCounterflowRate : REAL; (* L/min *)
    bSystemAlarm : BOOL;
    iErrorCode : INT;
END_VAR
VAR
    (* Internal State *)
    rTargetVoltage : REAL := 60.0;
    rTargetFrequency : REAL := 400.0;
    iTrackingIndex : INT := 0;
    VisionScores : ARRAY[0..99] OF INT;

    (* Chiller PID control *)
    rChillerError : REAL;
    rChillerIntegral : REAL := 0.0;
    rChillerDerivative : REAL;
    rChillerLastError : REAL := 0.0;
    Kp : REAL := 2.5;
    Ki : REAL := 0.1;
    Kd : REAL := 0.05;

    (* Timers *)
    TMR_ProcessTick : TON;
END_VAR

(* 1. Waterbath Stunner Profiling *)
IF bSystemEnable THEN
    (* Base stunner parameters on conductivity and line speed *)
    IF rStunnerConductivity > 0.0 AND rLineSpeed > 0.0 THEN
        rTargetVoltage := 120.0 - (rStunnerConductivity * 1.5) + (rLineSpeed * 0.2);
        rTargetFrequency := 400.0 + (rStunnerConductivity * 5.0) - (rLineSpeed * 1.0);

        (* Clamp values for safety *)
        IF rTargetVoltage > 150.0 THEN rTargetVoltage := 150.0; END_IF;
        IF rTargetVoltage < 40.0 THEN rTargetVoltage := 40.0; END_IF;
        IF rTargetFrequency > 1000.0 THEN rTargetFrequency := 1000.0; END_IF;
        IF rTargetFrequency < 100.0 THEN rTargetFrequency := 100.0; END_IF;

        rStunnerVoltage := rTargetVoltage;
        rStunnerFrequency := rTargetFrequency;
    ELSE
        iErrorCode := 101; (* Invalid Stunner Inputs *)
        bSystemAlarm := TRUE;
    END_IF;

    (* 2. Vision-Based Evisceration Tracking *)
    (* Shift array and insert new score *)
    FOR iTrackingIndex := 99 TO 1 BY -1 DO
        VisionScores[iTrackingIndex] := VisionScores[iTrackingIndex - 1];
    END_FOR;
    VisionScores[0] := iVisionDefectScore;

    (* Eviscerate reject logic: If defect score is high *)
    IF VisionScores[50] > 75 THEN
        bEviscerationReject := TRUE;
    ELSE
        bEviscerationReject := FALSE;
    END_IF;

    (* 3. Chilling Tank Thermal Counterflow (PID) *)
    rChillerError := 4.0 - rChillerInletTemp; (* Target temp is 4.0C *)
    rChillerIntegral := rChillerIntegral + rChillerError;
    rChillerDerivative := rChillerError - rChillerLastError;

    rChillerCounterflowRate := (Kp * rChillerError) + (Ki * rChillerIntegral) + (Kd * rChillerDerivative);

    (* Feedforward from ambient *)
    rChillerCounterflowRate := rChillerCounterflowRate + (rChillerAmbientTemp * 0.5);

    (* Clamp rate *)
    IF rChillerCounterflowRate > 500.0 THEN rChillerCounterflowRate := 500.0; END_IF;
    IF rChillerCounterflowRate < 50.0 THEN rChillerCounterflowRate := 50.0; END_IF;

    rChillerLastError := rChillerError;

ELSE
    (* Safe State when disabled *)
    rStunnerVoltage := 0.0;
    rStunnerFrequency := 0.0;
    bEviscerationReject := FALSE;
    rChillerCounterflowRate := 0.0;
    bSystemAlarm := FALSE;
    iErrorCode := 0;
END_IF;
END_FUNCTION_BLOCK
