FUNCTION_BLOCK FB_CentrifugalCompressorControl
TITLE = 'Centrifugal Gas Compressor - Surge Control, IGV, AMB'
VERSION : '1.0'
AUTHOR : 'Lumina AI'

VAR_INPUT
    // Process Variables
    rSuctionPressure : REAL; (* Suction Pressure (bar) *)
    rDischargePressure : REAL; (* Discharge Pressure (bar) *)
    rSuctionTemperature : REAL; (* Suction Temp (C) *)
    rMassFlow : REAL; (* Compressor Mass Flow (kg/s) *)
    rSpeed : REAL; (* Rotor Speed (RPM) *)

    // Limits
    rMaxDischargePressure : REAL := 150.0;
    rMinSuctionPressure : REAL := 2.0;
    rSurgeMarginSetPoint : REAL := 10.0; (* 10% Surge Margin *)

    // AMB Settings
    rRotorPositionX : REAL; (* X-axis displacement (um) *)
    rRotorPositionY : REAL; (* Y-axis displacement (um) *)
    rRotorPositionZ : REAL; (* Axial displacement (um) *)

    // Commands
    bStartCommand : BOOL;
    bStopCommand : BOOL;
    bEmergencyStop : BOOL;
END_VAR

VAR_OUTPUT
    // Actuation
    rAntiSurgeValveCmd : REAL; (* Anti-surge valve position 0-100% *)
    rInletGuideVaneCmd : REAL; (* IGV position 0-100% *)

    // AMB Control
    rMagneticBearingCurrentX : REAL; (* X-axis current (A) *)
    rMagneticBearingCurrentY : REAL; (* Y-axis current (A) *)
    rMagneticBearingCurrentZ : REAL; (* Z-axis current (A) *)

    // Status
    bCompressorRunning : BOOL;
    bSurgeWarning : BOOL;
    bSurgeTrip : BOOL;
    bAMBFault : BOOL;
    bReadyToStart : BOOL;
END_VAR

VAR
    // Internal States
    rPressureRatio : REAL;
    rReducedFlow : REAL;
    rSurgeControlLine : REAL;
    rOperatingPointDistance : REAL;

    // PID Controllers for AMB
    rKp_AMB : REAL := 2.5;
    rKi_AMB : REAL := 0.1;
    rKd_AMB : REAL := 0.05;

    rIntegralX, rIntegralY, rIntegralZ : REAL;
    rPrevErrorX, rPrevErrorY, rPrevErrorZ : REAL;

    // PID for Anti-Surge
    rASV_Kp : REAL := 1.5;
    rASV_Ki : REAL := 0.2;
    rASV_Integral : REAL;
    rASV_PrevError : REAL;

    eState : INT; // (INIT=0, LEVITATION=1, STARTING=2, RUNNING=3, STOPPING=4, FAULT=5);

    // Timers
    tLevitationTimer : TON;
    tSurgeDelay : TON;
END_VAR

(* 
    Implementation Details:
    1. Active Magnetic Bearing (AMB) Levitation
    2. Inlet Guide Vane (IGV) capacity control
    3. Anti-surge Control (ASC) with distance to surge line mapping
*)

// Calculate Pressure Ratio
IF rSuctionPressure > 0.0 THEN
    rPressureRatio := rDischargePressure / rSuctionPressure;
ELSE
    rPressureRatio := 1.0;
END_IF;

// Simplified Surge Map Calculation
// P_ratio = f(ReducedFlow)
// We calculate distance to surge line
rReducedFlow := rMassFlow * SQRT(rSuctionTemperature + 273.15) / rSuctionPressure;
rSurgeControlLine := 1.2 + 0.05 * rReducedFlow + 0.001 * (rReducedFlow * rReducedFlow);

rOperatingPointDistance := ((rReducedFlow - rSurgeControlLine) / rSurgeControlLine) * 100.0;

// AMB PID Control (Simplified Levitation Logic)
IF eState >= 1 THEN
    // X-Axis
    rIntegralX := rIntegralX + (0.0 - rRotorPositionX);
    rMagneticBearingCurrentX := (0.0 - rRotorPositionX) * rKp_AMB + (rIntegralX * rKi_AMB) + ((0.0 - rRotorPositionX - rPrevErrorX) * rKd_AMB);
    rPrevErrorX := 0.0 - rRotorPositionX;

    // Y-Axis
    rIntegralY := rIntegralY + (0.0 - rRotorPositionY);
    rMagneticBearingCurrentY := (0.0 - rRotorPositionY) * rKp_AMB + (rIntegralY * rKi_AMB) + ((0.0 - rRotorPositionY - rPrevErrorY) * rKd_AMB);
    rPrevErrorY := 0.0 - rRotorPositionY;

    // Z-Axis
    rIntegralZ := rIntegralZ + (0.0 - rRotorPositionZ);
    rMagneticBearingCurrentZ := (0.0 - rRotorPositionZ) * rKp_AMB + (rIntegralZ * rKi_AMB) + ((0.0 - rRotorPositionZ - rPrevErrorZ) * rKd_AMB);
    rPrevErrorZ := 0.0 - rRotorPositionZ;

    // Detect AMB Fault
    IF ABS(rRotorPositionX) > 200.0 OR ABS(rRotorPositionY) > 200.0 OR ABS(rRotorPositionZ) > 300.0 THEN
        bAMBFault := TRUE;
    ELSE
        bAMBFault := FALSE;
    END_IF;
ELSE
    rMagneticBearingCurrentX := 0.0;
    rMagneticBearingCurrentY := 0.0;
    rMagneticBearingCurrentZ := 0.0;
END_IF;

// State Machine
CASE eState OF
    0:
        bReadyToStart := TRUE;
        bCompressorRunning := FALSE;
        rAntiSurgeValveCmd := 100.0; // Fully open ASV for start
        rInletGuideVaneCmd := 0.0;   // Fully closed IGV

        IF bStartCommand AND NOT bEmergencyStop THEN
            eState := 1;
            bReadyToStart := FALSE;
        END_IF;

    1:
        tLevitationTimer(IN:=TRUE, PT:=T#5S);
        IF tLevitationTimer.Q AND NOT bAMBFault THEN
            eState := 2;
        ELSIF bAMBFault THEN
            eState := 5;
        END_IF;

    2:
        // Ramp up sequence (mock)
        IF rSpeed > 3000.0 THEN
            eState := 3;
            bCompressorRunning := TRUE;
        END_IF;
        IF bStopCommand THEN
            eState := 4;
        END_IF;

    3:
        // Surge Control Logic
        IF rOperatingPointDistance < rSurgeMarginSetPoint THEN
            bSurgeWarning := TRUE;
            // PI Control for Anti-Surge Valve
            rASV_Integral := rASV_Integral + (rSurgeMarginSetPoint - rOperatingPointDistance);
            rAntiSurgeValveCmd := rAntiSurgeValveCmd + ((rSurgeMarginSetPoint - rOperatingPointDistance) * rASV_Kp) + (rASV_Integral * rASV_Ki);
        ELSE
            bSurgeWarning := FALSE;
            // Slowly close valve if margin is healthy
            rAntiSurgeValveCmd := MAX(0.0, rAntiSurgeValveCmd - 0.1); 
        END_IF;

        // Anti-windup and limits
        IF rAntiSurgeValveCmd > 100.0 THEN rAntiSurgeValveCmd := 100.0; END_IF;
        IF rAntiSurgeValveCmd < 0.0 THEN rAntiSurgeValveCmd := 0.0; END_IF;

        // IGV Control based on discharge pressure
        rInletGuideVaneCmd := (rMaxDischargePressure - rDischargePressure) * 0.5;
        IF rInletGuideVaneCmd > 100.0 THEN rInletGuideVaneCmd := 100.0; END_IF;
        IF rInletGuideVaneCmd < 0.0 THEN rInletGuideVaneCmd := 0.0; END_IF;

        // Trips
        IF rOperatingPointDistance < 0.0 THEN
            tSurgeDelay(IN:=TRUE, PT:=T#2S);
            IF tSurgeDelay.Q THEN
                bSurgeTrip := TRUE;
                eState := 5;
            END_IF;
        ELSE
            tSurgeDelay(IN:=FALSE);
        END_IF;

        IF bStopCommand OR bEmergencyStop OR bAMBFault THEN
            eState := 4;
        END_IF;

    4:
        bCompressorRunning := FALSE;
        rAntiSurgeValveCmd := 100.0; // Open ASV
        rInletGuideVaneCmd := 0.0;   // Close IGV
        IF rSpeed < 10.0 THEN
            eState := 0;
        END_IF;
        IF bEmergencyStop THEN
            eState := 5;
        END_IF;

    5:
        bCompressorRunning := FALSE;
        rAntiSurgeValveCmd := 100.0;
        rInletGuideVaneCmd := 0.0;
        IF NOT bEmergencyStop AND NOT bAMBFault AND NOT bSurgeTrip THEN
            eState := 0;
        END_IF;

END_CASE;
END_FUNCTION_BLOCK
```

