FUNCTION_BLOCK FB_OTEC_PlantSupervisor
(*======================================================================================
  Utility-Scale Oceanic Thermal Energy Conversion (OTEC) Plant Supervisor
  --------------------------------------------------------------------------------------
  Description:
    Supervises the primary Rankine cycle, specifically handling the 1000m Cold Water Pipe (CWP)
    upwelling pump cavitation limits, closed-cycle ammonia turbine cascading, and tracking 
    bio-fouling degradation of the titanium plate heat exchangers.
  ======================================================================================*)

VAR_INPUT
    (* Mandatory System Inputs *)
    bSystemEnable           : BOOL;     (* Main operator enable signal for the OTEC process *)
    bEmergencyStop          : BOOL;     (* Safety loop OK; FALSE = emergency shutdown initiated *)
    bGridSyncOK             : BOOL;     (* Electrical grid synchronization healthy and verified *)
    rAmmoniaVaporPress      : REAL;     (* Ammonia vapor pressure entering main turbine (Bar) *)

    (* Environmental & Flow Measurements *)
    rSurfaceTemp_C          : REAL;     (* Surface warm seawater temperature (Deg C) *)
    rDeepWaterTemp_C        : REAL;     (* 1000m deep cold seawater temperature (Deg C) *)
    rCWPFlowRate_M3         : REAL;     (* Cold Water Pipe upwelling flow rate (m^3/s) *)
    rEvaporatorFoulingIdx   : REAL;     (* Real-time bio-fouling optical/pressure metric (0.0 to 1.0) *)
END_VAR

VAR_OUTPUT
    (* Required System Outputs *)
    bSystemReady            : BOOL;     (* Plant is in a state ready to begin power generation *)
    rCWP_PumpCommand        : REAL;     (* Cold water pump VFD command (0.0 to 100.0 %) *)
    bTurbineTripAlarm       : BOOL;     (* High-priority alarm indicating Rankine turbine trip condition *)
    rTurbineValveCmd        : REAL;     (* Throttle valve setpoint for ammonia cascading turbines (0-100%) *)
    bBioFoulingWarning      : BOOL;     (* Alarm indicating heat exchangers need chlorination or cleaning *)
END_VAR

VAR
    (* Internal State and Timers *)
    iOTEC_State             : INT := 0; (* Main state machine variable *)
    tStartupDelay           : TON;      (* Delay timer for pump stabilization *)
    tCavitationCheck        : TON;      (* Timer for filtering cavitation noise *)

    (* Mathematical and Physics Models *)
    rDeltaT                 : REAL;     (* Thermal gradient available (Deg C) *)
    rNPSH_Available         : REAL;     (* Net Positive Suction Head available (m) *)
    rCavitationThreshold    : REAL := 12.5; (* Pre-calculated cavitation threshold for CWP pump *)
    rEfficiencyTarget       : REAL;     (* Target Rankine efficiency based on Carnot limit *)
    rFoulingLimit           : REAL := 0.85; (* Critical limit for titanium plate heat exchanger fouling *)

    (* Filtered Variables *)
    rFilteredVaporPress     : REAL;
END_VAR

(* === MAIN OTEC CONTROL LOGIC === *)

(* 1. Safety Interlocks and Hard Shutdowns *)
IF NOT bEmergencyStop THEN
    (* Immediate failsafe sequence *)
    bSystemReady      := FALSE;
    rCWP_PumpCommand  := 0.0;
    rTurbineValveCmd  := 0.0;
    bTurbineTripAlarm := TRUE;
    iOTEC_State       := 99; (* Fault State *)
    RETURN;
END_IF;

(* 2. Bio-Fouling Tracking of Titanium Plate Heat Exchangers *)
IF rEvaporatorFoulingIdx > rFoulingLimit THEN
    bBioFoulingWarning := TRUE;
ELSE
    bBioFoulingWarning := FALSE;
END_IF;

(* 3. Thermodynamic Feasibility Calculation *)
rDeltaT := rSurfaceTemp_C - rDeepWaterTemp_C;
IF rDeltaT < 15.0 THEN
    (* Insufficient thermal gradient for sustainable OTEC generation *)
    bSystemReady := FALSE;
    rCWP_PumpCommand := 0.0;
    rTurbineValveCmd := 0.0;
    RETURN;
ELSE
    bSystemReady := TRUE;
END_IF;

(* 4. Cascading State Machine for OTEC Operations *)
CASE iOTEC_State OF
    0: (* IDLE & STANDBY *)
        rCWP_PumpCommand := 0.0;
        rTurbineValveCmd := 0.0;
        bTurbineTripAlarm := FALSE;

        IF bSystemEnable AND bGridSyncOK AND (rDeltaT >= 20.0) THEN
            iOTEC_State := 10;
        END_IF;

    10: (* PRIMING COLD WATER PIPE (CWP) *)
        (* Ramp up CWP upwelling pump cautiously to prevent column separation and cavitation *)
        IF rCWP_PumpCommand < 30.0 THEN
            rCWP_PumpCommand := rCWP_PumpCommand + 0.1;
        END_IF;

        tStartupDelay(IN := TRUE, PT := T#30S);
        IF tStartupDelay.Q THEN
            tStartupDelay(IN := FALSE);
            iOTEC_State := 20;
        END_IF;

    20: (* AMMONIA VAPORIZATION & CAVITATION AVOIDANCE *)
        (* Continuously monitor Net Positive Suction Head (NPSH) *)
        rNPSH_Available := (rDeepWaterTemp_C * 0.5) + (rCWPFlowRate_M3 * 0.1); 

        IF rNPSH_Available < rCavitationThreshold THEN
            (* Incipient cavitation detected: throttle back pump *)
            rCWP_PumpCommand := rCWP_PumpCommand - 1.0;
            tCavitationCheck(IN := TRUE, PT := T#5S);
            IF tCavitationCheck.Q THEN
                (* Persistent cavitation: Fault *)
                bTurbineTripAlarm := TRUE;
                iOTEC_State := 99;
            END_IF;
        ELSE
            tCavitationCheck(IN := FALSE);
            (* Cavitation safe: advance CWP pump to operational nominal flow *)
            IF rCWP_PumpCommand < 85.0 THEN
                rCWP_PumpCommand := rCWP_PumpCommand + 0.5;
            END_IF;
        END_IF;

        IF rAmmoniaVaporPress > 6.0 THEN
            iOTEC_State := 30;
        END_IF;

    30: (* RANKINE TURBINE CASCADING & LOAD SYNC *)
        (* Control ammonia flow via cascading throttle valves *)
        IF bGridSyncOK THEN
            rTurbineValveCmd := LIMIT(0.0, (rAmmoniaVaporPress - 5.5) * 20.0, 100.0);
        ELSE
            iOTEC_State := 99; (* Lost grid sync *)
        END_IF;

        (* Monitor disabling condition *)
        IF NOT bSystemEnable THEN
            iOTEC_State := 40;
        END_IF;

    40: (* CONTROLLED SHUTDOWN *)
        rTurbineValveCmd := 0.0;
        IF rCWP_PumpCommand > 0.0 THEN
            rCWP_PumpCommand := rCWP_PumpCommand - 0.5;
        ELSE
            iOTEC_State := 0;
        END_IF;

    99: (* FAULT / TRIP *)
        rCWP_PumpCommand := 0.0;
        rTurbineValveCmd := 0.0;
        bTurbineTripAlarm := TRUE;

        IF NOT bSystemEnable AND NOT bEmergencyStop THEN
            (* Reset condition *)
            iOTEC_State := 0;
            bTurbineTripAlarm := FALSE;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
