    (* Status/Alarms *)
    bAlarmThermoforming : BOOL;
    bAlarmInspection : BOOL;
    bAlarmSealing : BOOL;
    sStatusMessage : STRING(50);
END_VAR

VAR
    (* State Machine *)
    iState : INT := 0; (* 0=Stop, 10=Heating, 20=Ready, 30=Running, 99=Error *)

    (* PID Controllers for Heaters *)
    pidHeater1 : FB_PID;
    pidHeater2 : FB_PID;
    pidSeal : FB_PID;

    (* Timers *)
    tonFormingDwell : TON;
    tonRejectDelay : TON;

    (* Internal Tracking *)
    rTargetHeaterTemp : REAL := 135.0; (* deg C *)
    rTargetSealTemp : REAL := 180.0; (* deg C *)
    bTempInBand : BOOL;
    iConsecutiveRejects : INT := 0;

    (* Shift Registers for reject tracking *)
    arShiftRegister : ARRAY[0..20] OF BOOL;
    iIndex : INT;
END_VAR

(* Implementation *)

(* Emergency Stop Handling *)
IF NOT bEStop THEN
    iState := 99;
    sStatusMessage := 'EMERGENCY STOP ACTIVE';
    rWebSpeedCmd := 0.0;
    rPVC_HeaterTemp1_Cmd := 0.0;
    rPVC_HeaterTemp2_Cmd := 0.0;
    rSealTemp_Cmd := 0.0;
    bFormingValveCmd := FALSE;
    bCameraTrigger := FALSE;
    bRejectMechanismCmd := FALSE;
    bLineRunning := FALSE;
    RETURN;
END_IF

(* Temperature Band Check *)
bTempInBand := (ABS(rPVC_HeaterTemp1_Fbk - rTargetHeaterTemp) < 5.0) AND 
               (ABS(rPVC_HeaterTemp2_Fbk - rTargetHeaterTemp) < 5.0) AND 
               (ABS(rSealTemp_Fbk - rTargetSealTemp) < 5.0);

CASE iState OF
    0: (* Stopped *)
        bLineRunning := FALSE;
        rWebSpeedCmd := 0.0;
        bFormingValveCmd := FALSE;
        IF bEnableLine THEN
            iState := 10;
            sStatusMessage := 'HEATING UP...';
        END_IF

    10: (* Heating Phase *)
        rPVC_HeaterTemp1_Cmd := rTargetHeaterTemp;
        rPVC_HeaterTemp2_Cmd := rTargetHeaterTemp;
        rSealTemp_Cmd := rTargetSealTemp;

        IF bTempInBand THEN
            iState := 20;
            sStatusMessage := 'READY FOR PRODUCTION';
        END_IF

        IF NOT bEnableLine THEN
            iState := 0;
        END_IF

    20: (* Ready *)
        IF bEnableLine THEN
            iState := 30;
            sStatusMessage := 'PRODUCTION RUNNING';
        ELSIF NOT bEnableLine THEN
            iState := 0;
        END_IF

    30: (* Running *)
        bLineRunning := TRUE;
        rWebSpeedCmd := rWebSpeedSetpt;

        (* Thermoforming Logic: Simulate index cycle forming *)
        (* Using a cyclic timer for the forming valve based on web speed *)
        tonFormingDwell(IN:= NOT tonFormingDwell.Q, PT:= T#500MS);
        bFormingValveCmd := tonFormingDwell.ET < T#200MS; 

        (* Inspection Logic *)
        (* Trigger camera periodically or based on encoder (simplified here) *)
        IF tonFormingDwell.Q THEN
            bCameraTrigger := TRUE;

            (* Evaluate previous index results *)
            IF iFilledCavities < iTotalCavities THEN
                arShiftRegister[0] := TRUE; (* Mark for reject *)
                iConsecutiveRejects := iConsecutiveRejects + 1;
            ELSE
                arShiftRegister[0] := FALSE;
                iConsecutiveRejects := 0;
            END_IF

            (* Shift register advancement for reject station *)
            FOR iIndex := 20 TO 1 BY -1 DO
                arShiftRegister[iIndex] := arShiftRegister[iIndex-1];
            END_FOR
        ELSE
            bCameraTrigger := FALSE;
        END_IF

        (* Reject Mechanism actuation at station offset (e.g., index 5) *)
        bRejectMechanismCmd := arShiftRegister[5];

        (* Alarm Conditions *)
        IF iConsecutiveRejects >= 3 THEN
            bAlarmInspection := TRUE;
            iState := 99;
            sStatusMessage := 'ALARM: CONSECUTIVE REJECTS';
        END_IF

        IF NOT bTempInBand THEN
            bAlarmThermoforming := TRUE;
            iState := 99;
            sStatusMessage := 'ALARM: TEMP OUT OF BAND';
        END_IF

        IF rThermoFormPressure_Fbk < 5.5 THEN
            bAlarmThermoforming := TRUE;
            iState := 99;
            sStatusMessage := 'ALARM: LOW FORMING PRESSURE';
        END_IF

        IF NOT bEnableLine THEN
            iState := 0;
        END_IF

    99: (* Error State *)
        bLineRunning := FALSE;
        rWebSpeedCmd := 0.0;
        bFormingValveCmd := FALSE;

        IF NOT bAlarmThermoforming AND NOT bAlarmInspection AND NOT bAlarmSealing AND NOT bEStop THEN
            iState := 0;
            sStatusMessage := 'STOPPED (RESET)';
        END_IF

END_CASE

END_FUNCTION_BLOCK
