//=============================================================================
// SYSTEM: Planetary Defense Consortium - NEA Mission Control
// MODULE: FB_Asteroid_CaptureDespin
// AUTHOR: Principal Orbital Dynamics Engineer
// DESCRIPTION:
// Master-tier controller for Near-Earth Asteroid (NEA) autonomous capture and
// yo-yo despin. Handles RPO (Rendezvous & Proximity Operations), LiDAR axis mapping,
// Nitinol capture net deployment, and Yo-Yo despin sequence based on real-time IMU
// feedback for a rotating 50-meter class asteroid.
// COMPLIANCE: IEC 61131-3, PackML State Machine.
//=============================================================================

TYPE E_PackML_State : 
(
    IDLE := 0,
    STARTING := 1,
    EXECUTE_RPO := 2,
    MAPPING_AXES := 3,
    DEPLOYING_NET := 4,
    SECURING_WINCHES := 5,
    CALCULATING_DESPIN := 6,
    EXECUTING_DESPIN := 7,
    COMPLETE := 8,
    ABORTING := 9,
    ABORTED := 10
) DINT;
END_TYPE

TYPE ST_Vector3 : 
STRUCT
    X : LREAL;
    Y : LREAL;
    Z : LREAL;
END_STRUCT
END_TYPE

TYPE ST_InertiaMatrix : 
STRUCT
    Ixx : LREAL;
    Iyy : LREAL;
    Izz : LREAL;
    Ixy : LREAL;
    Ixz : LREAL;
    Iyz : LREAL;
END_STRUCT
END_TYPE

FUNCTION_BLOCK FB_Asteroid_CaptureDespin
VAR_INPUT
    bEnable             : BOOL;                 // Command to initiate sequence
    bAbort              : BOOL;                 // Emergency abort command

    // Sensor Feedback
    stLidarPos          : ST_Vector3;           // Relative position to asteroid COM (m)
    stIMU_Omega         : ST_Vector3;           // Real-time angular velocity (rad/s)
    stIMU_Accel         : ST_Vector3;           // Linear acceleration (m/s^2)

    // Actuator Feedback
    fNetTensionCmd      : ARRAY[1..4] OF LREAL; // Commanded tension for each winch (N)
    fWinchTensionFb     : ARRAY[1..4] OF LREAL; // Actual tension feedback (N)
    bTethersDeployed    : BOOL;                 // Status of Yo-Yo tethers
END_VAR

VAR_OUTPUT
    eState              : E_PackML_State := E_PackML_State.IDLE; // Current state
    bDone               : BOOL;                 // Operation complete successfully
    bError              : BOOL;                 // System error
    nErrorID            : DINT;                 // Error code

    // Thruster & Actuator Commands
    stRCS_ThrustCmd     : ST_Vector3;           // Reaction Control System commands (N)
    bDeployNet          : BOOL;                 // Command to deploy Nitinol net
    fWinchDriveSpeed    : ARRAY[1..4] OF LREAL; // Drive speed command for winches (rad/s)
    bReleaseDespinMass  : BOOL;                 // Command to release Yo-Yo masses
    bCutTethers         : BOOL;                 // Command to cut Kevlar tethers
END_VAR

VAR
    // Internal State Variables
    tStateTimer         : TON;                  // Timer for state transitions
    stPrincipalAxes     : ST_InertiaMatrix;     // Mapped inertia tensor
    fAsteroidMass       : LREAL := 1.5E8;       // Estimated mass (kg) for 50m class

    // Despin Dynamics Parameters
    fTargetSpinRate     : LREAL := 0.0001;      // Acceptable residual spin (rad/s)
    fCurrentSpinMag     : LREAL;                // Magnitude of angular velocity
    fMassTetherLength   : LREAL := 0.0;
    fDespinMass         : LREAL := 500.0;       // Tungsten mass per tether (kg)

    fCalculatedReleaseTime : LREAL;             // Time delay for tether release
    tDespinCutTimer     : TON;                  // Timer to actuate cut

    i                   : INT;                  // Loop index
    fTensionError       : LREAL;
    fNetTensionKp       : LREAL := 0.5;
END_VAR

// ----------------------------------------------------------------------------
// 1. INPUT PROCESSING & EMERGENCY HANDLER
// ----------------------------------------------------------------------------
IF bAbort THEN
    eState := E_PackML_State.ABORTING;
END_IF

// Calculate total spin magnitude
fCurrentSpinMag := SQRT((stIMU_Omega.X * stIMU_Omega.X) + 
                        (stIMU_Omega.Y * stIMU_Omega.Y) + 
                        (stIMU_Omega.Z * stIMU_Omega.Z));

// ----------------------------------------------------------------------------
// 2. STATE MACHINE (PackML Aligned)
// ----------------------------------------------------------------------------
CASE eState OF

    // --- IDLE STATE ---
    E_PackML_State.IDLE:
        bDone := FALSE;
        bError := FALSE;
        bDeployNet := FALSE;
        bReleaseDespinMass := FALSE;
        bCutTethers := FALSE;

        IF bEnable THEN
            eState := E_PackML_State.STARTING;
        END_IF

    // --- STARTING STATE ---
    E_PackML_State.STARTING:
        // Initialize systems, warm up LiDAR and RCS
        tStateTimer(IN := TRUE, PT := T#5S);
        IF tStateTimer.Q THEN
            tStateTimer(IN := FALSE);
            eState := E_PackML_State.EXECUTE_RPO;
        END_IF

    // --- EXECUTE RPO (Rendezvous & Proximity Operations) ---
    E_PackML_State.EXECUTE_RPO:
        // Implement simple P-controller for station keeping at 100m
        stRCS_ThrustCmd.X := (100.0 - stLidarPos.X) * 10.0; 
        stRCS_ThrustCmd.Y := (0.0 - stLidarPos.Y) * 10.0;
        stRCS_ThrustCmd.Z := (0.0 - stLidarPos.Z) * 10.0;

        IF ABS(stLidarPos.X - 100.0) < 1.0 AND ABS(stLidarPos.Y) < 1.0 AND ABS(stLidarPos.Z) < 1.0 THEN
            stRCS_ThrustCmd.X := 0.0;
            stRCS_ThrustCmd.Y := 0.0;
            stRCS_ThrustCmd.Z := 0.0;
            eState := E_PackML_State.MAPPING_AXES;
        END_IF

    // --- MAPPING AXES ---
    E_PackML_State.MAPPING_AXES:
        // Simulate 6-DOF Mapping of Principal Axes
        tStateTimer(IN := TRUE, PT := T#15S);

        // Assign standard inertia matrix for an ellipsoid 50m x 40m x 30m
        stPrincipalAxes.Ixx := 0.2 * fAsteroidMass * (40.0*40.0 + 30.0*30.0);
        stPrincipalAxes.Iyy := 0.2 * fAsteroidMass * (50.0*50.0 + 30.0*30.0);
        stPrincipalAxes.Izz := 0.2 * fAsteroidMass * (50.0*50.0 + 40.0*40.0);

        IF tStateTimer.Q THEN
            tStateTimer(IN := FALSE);
            eState := E_PackML_State.DEPLOYING_NET;
        END_IF

    // --- DEPLOYING NET ---
    E_PackML_State.DEPLOYING_NET:
        bDeployNet := TRUE;
        tStateTimer(IN := TRUE, PT := T#10S);
        IF tStateTimer.Q THEN
            tStateTimer(IN := FALSE);
            eState := E_PackML_State.SECURING_WINCHES;
        END_IF

    // --- SECURING WINCHES (Closed-loop tensioning) ---
    E_PackML_State.SECURING_WINCHES:
        // Proportional control for Nitinol capture net winches
        FOR i := 1 TO 4 DO
            fTensionError := fNetTensionCmd[i] - fWinchTensionFb[i];
            fWinchDriveSpeed[i] := fTensionError * fNetTensionKp;

            // Cap speed
            IF fWinchDriveSpeed[i] > 5.0 THEN
                fWinchDriveSpeed[i] := 5.0;
            ELSIF fWinchDriveSpeed[i] < -5.0 THEN
                fWinchDriveSpeed[i] := -5.0;
            END_IF
        END_FOR

        // Check if all winches are at target tension (within 5%)
        IF ABS(fNetTensionCmd[1] - fWinchTensionFb[1]) < (0.05 * fNetTensionCmd[1]) THEN
            FOR i := 1 TO 4 DO
                fWinchDriveSpeed[i] := 0.0;
            END_FOR
            eState := E_PackML_State.CALCULATING_DESPIN;
        END_IF

    // --- CALCULATING DESPIN DYNAMICS ---
    E_PackML_State.CALCULATING_DESPIN:
        // Conservation of Angular Momentum: I_ast * w_0 = (I_ast + 2 * m * r^2) * w_f
        // We release mass m on tether length r to make w_f = 0
        // r = sqrt( (I_ast * w_0) / (2 * m * w_target) ) -- Simplified
        // We determine the cut time based on unwinding dynamics.

        fCalculatedReleaseTime := 45.5; // Calculated unwinding time in seconds (deterministic for this example)
        eState := E_PackML_State.EXECUTING_DESPIN;

    // --- EXECUTING DESPIN ---
    E_PackML_State.EXECUTING_DESPIN:
        bReleaseDespinMass := TRUE;

        // Actuate release timer based on unwound length / phase
        tDespinCutTimer(IN := TRUE, PT := LREAL_TO_TIME(fCalculatedReleaseTime * 1000.0));

        // Dynamic cut condition based on real-time IMU feedback
        IF fCurrentSpinMag <= fTargetSpinRate OR tDespinCutTimer.Q THEN
            bCutTethers := TRUE;
            tDespinCutTimer(IN := FALSE);
            eState := E_PackML_State.COMPLETE;
        END_IF

    // --- COMPLETE ---
    E_PackML_State.COMPLETE:
        bDone := TRUE;
        bDeployNet := FALSE;
        bReleaseDespinMass := FALSE;
        stRCS_ThrustCmd.X := 0.0;
        stRCS_ThrustCmd.Y := 0.0;
        stRCS_ThrustCmd.Z := 0.0;

        IF NOT bEnable THEN
            eState := E_PackML_State.IDLE;
        END_IF

    // --- ABORTING ---
    E_PackML_State.ABORTING:
        // Safe all outputs immediately
        bDeployNet := FALSE;
        bReleaseDespinMass := FALSE;
        bCutTethers := FALSE;
        FOR i := 1 TO 4 DO
            fWinchDriveSpeed[i] := 0.0;
        END_FOR
        stRCS_ThrustCmd.X := 0.0;
        stRCS_ThrustCmd.Y := 0.0;
        stRCS_ThrustCmd.Z := 0.0;

        eState := E_PackML_State.ABORTED;

    // --- ABORTED ---
    E_PackML_State.ABORTED:
        bError := TRUE;
        nErrorID := 999; // Abort code
        IF NOT bAbort AND NOT bEnable THEN
            eState := E_PackML_State.IDLE;
        END_IF

END_CASE

END_FUNCTION_BLOCK
