FUNCTION_BLOCK FB_BioReactor_mAb_Ferm_Ctrl
(* 
   Ultra-precision multi-parameter control for monoclonal antibody (mAb) 
   fermentation bioreactor. 
   Cascaded DO control, pH profiling, viable cell density integration, 
   and sterile boundary pressure cascade management.
*)

VAR_INPUT
    bEnable                 : BOOL;     (* System master enable signal *)
    bEmergencyStop          : BOOL;     (* Safety relay / E-Stop OK signal (Active HIGH = OK) *)
    rDissolvedOxygen        : REAL;     (* Current Dissolved Oxygen (DO) in % saturation *)
    rPhValue                : REAL;     (* Current pH value from sterile probes *)
    rTemperature            : REAL;     (* Bioreactor temperature in degrees Celsius *)
    rAgitatorSpeedFdbk      : REAL;     (* Current agitator speed feedback in RPM *)
    rViableCellDensity      : REAL;     (* VCD optical density reading in 10^6 cells/mL *)
    rNutrientFeedLevel      : REAL;     (* Nutrient feed tank level in % *)
END_VAR

VAR_OUTPUT
    bSystemReady            : BOOL;     (* System ready for active fermentation *)
    rAgitatorSpeedCmd       : REAL;     (* Control signal for agitator speed (DO cascade) in RPM *)
    rSpargerAirFlowCmd      : REAL;     (* Sparger air mass flow controller command in SLPM *)
    rSpargerO2FlowCmd       : REAL;     (* Sparger pure O2 mass flow controller command in SLPM *)
    rBasePumpCmd            : REAL;     (* Base (NaOH) dosing pump command in % *)
    rAcidPumpCmd            : REAL;     (* Acid (CO2) dosing valve command in % *)
    rNutrientPumpCmd        : REAL;     (* Perfusion/Feed nutrient pump command in % *)
    bSterileBoundaryAlarm   : BOOL;     (* High-priority sterile boundary integrity alarm *)
    bGeneralAlarm           : BOOL;     (* General fault alarm output *)
    iCurrentPhase           : INT;      (* Current fermentation phase indicator *)
END_VAR

VAR
    iState                  : INT := 0; (* Internal state machine variable *)
    tStateTimer             : TON;      (* Timer for state transitions and dosing holds *)
    tGrowthTimer            : TON;      (* Timer tracking overall growth phase duration *)

    (* PI Controller internal variables for DO cascade *)
    rDOError                : REAL;
    rDOIntegral             : REAL;
    rDO_Kp                  : REAL := 2.5;
    rDO_Ki                  : REAL := 0.15;
    rTotalGasDemand         : REAL;

    (* PI Controller internal variables for pH *)
    rPHError                : REAL;
    rPHIntegral             : REAL;
    rPH_Kp                  : REAL := 50.0;
    rPH_Ki                  : REAL := 2.0;

    rTargetDO               : REAL := 30.0; (* DO setpoint in % *)
    rTargetPH               : REAL := 7.00; (* pH setpoint *)

    bInitDone               : BOOL := FALSE;
END_VAR

(* === MAIN SAFETY INTERLOCKS === *)
IF NOT bEmergencyStop THEN
    bSystemReady := FALSE;
    bGeneralAlarm := TRUE;
    rAgitatorSpeedCmd := 0.0;
    rSpargerAirFlowCmd := 0.0;
    rSpargerO2FlowCmd := 0.0;
    rBasePumpCmd := 0.0;
    rAcidPumpCmd := 0.0;
    rNutrientPumpCmd := 0.0;
    iState := 999; (* FAULT STATE *)
    RETURN;
END_IF;

(* === INITIALIZATION === *)
IF NOT bInitDone THEN
    iState := 0;
    rDOIntegral := 0.0;
    rPHIntegral := 0.0;
    bInitDone := TRUE;
END_IF;

(* === BIOREACTOR STATE MACHINE === *)
CASE iState OF
    0: (* IDLE & PRE-CHECK *)
        bSystemReady := FALSE;
        rAgitatorSpeedCmd := 0.0;
        bGeneralAlarm := FALSE;
        bSterileBoundaryAlarm := FALSE;

        IF bEnable AND (rTemperature > 36.0) AND (rTemperature < 37.5) THEN
            iState := 10; (* Transition to INOCULATION *)
            tStateTimer(IN := FALSE);
        END_IF;

    10: (* INOCULATION PHASE *)
        bSystemReady := TRUE;
        iCurrentPhase := 1;

        (* Gentle agitation during inoculation *)
        rAgitatorSpeedCmd := 50.0;

        tStateTimer(IN := TRUE, PT := T#30M);
        IF tStateTimer.Q THEN
            tStateTimer(IN := FALSE);
            iState := 20; (* Transition to GROWTH *)
            tGrowthTimer(IN := FALSE);
        END_IF;

    20: (* EXPONENTIAL GROWTH PHASE *)
        iCurrentPhase := 2;
        tGrowthTimer(IN := TRUE, PT := T#120H); (* 5-day growth max *)

        (* === DO CASCADED CONTROL === *)
        rDOError := rTargetDO - rDissolvedOxygen;
        rDOIntegral := rDOIntegral + (rDOError * 0.1); (* Assuming 100ms cycle *)

        (* Anti-windup for DO integral *)
        IF rDOIntegral > 100.0 THEN rDOIntegral := 100.0; END_IF;
        IF rDOIntegral < -100.0 THEN rDOIntegral := -100.0; END_IF;

        rTotalGasDemand := (rDO_Kp * rDOError) + (rDO_Ki * rDOIntegral);

        IF rTotalGasDemand < 0.0 THEN rTotalGasDemand := 0.0; END_IF;

        (* Cascade split: Agitator -> Air -> O2 *)
        IF rTotalGasDemand < 30.0 THEN
            rAgitatorSpeedCmd := 100.0 + (rTotalGasDemand * 5.0); (* 100 to 250 RPM *)
            rSpargerAirFlowCmd := 0.5; (* Minimal air *)
            rSpargerO2FlowCmd := 0.0;
        ELSIF rTotalGasDemand < 70.0 THEN
            rAgitatorSpeedCmd := 250.0;
            rSpargerAirFlowCmd := 0.5 + ((rTotalGasDemand - 30.0) * 0.1);
            rSpargerO2FlowCmd := 0.0;
        ELSE
            rAgitatorSpeedCmd := 250.0;
            rSpargerAirFlowCmd := 4.5; (* Max air *)
            rSpargerO2FlowCmd := (rTotalGasDemand - 70.0) * 0.05;
        END_IF;

        (* === pH CONTROL (SPLIT RANGE) === *)
        rPHError := rTargetPH - rPhValue;
        rPHIntegral := rPHIntegral + (rPHError * 0.1);

        IF rPHIntegral > 50.0 THEN rPHIntegral := 50.0; END_IF;
        IF rPHIntegral < -50.0 THEN rPHIntegral := -50.0; END_IF;

        IF rPHError > 0.05 THEN
            (* Too acidic, add base *)
            rBasePumpCmd := (rPHError * rPH_Kp) + (rPHIntegral * rPH_Ki);
            rAcidPumpCmd := 0.0;
            IF rBasePumpCmd > 100.0 THEN rBasePumpCmd := 100.0; END_IF;
        ELSIF rPHError < -0.05 THEN
            (* Too basic, add acid (CO2) *)
            rBasePumpCmd := 0.0;
            rAcidPumpCmd := (ABS(rPHError) * rPH_Kp) + (ABS(rPHIntegral) * rPH_Ki);
            IF rAcidPumpCmd > 100.0 THEN rAcidPumpCmd := 100.0; END_IF;
        ELSE
            rBasePumpCmd := 0.0;
            rAcidPumpCmd := 0.0;
        END_IF;

        (* === NUTRIENT FEEDING STRATEGY === *)
        IF rViableCellDensity > 20.0 THEN
            (* High VCD triggers continuous feeding mode *)
            rNutrientPumpCmd := 15.0 + (rViableCellDensity * 0.5);
            IF rNutrientPumpCmd > 100.0 THEN rNutrientPumpCmd := 100.0; END_IF;
        ELSE
            rNutrientPumpCmd := 5.0; (* Basal feed *)
        END_IF;

        IF NOT bEnable THEN
            iState := 0; (* User aborted *)
        END_IF;

    999: (* FAULT HANDLING *)
        bSystemReady := FALSE;
        bGeneralAlarm := TRUE;
        rAgitatorSpeedCmd := 0.0;
        rSpargerAirFlowCmd := 0.0;
        rSpargerO2FlowCmd := 0.0;
        rBasePumpCmd := 0.0;
        rAcidPumpCmd := 0.0;
        rNutrientPumpCmd := 0.0;
        IF bEmergencyStop AND bEnable THEN
            iState := 0; (* Reset attempt *)
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
```

