FUNCTION_BLOCK FB_FlexoPressControl
VAR_INPUT
    bEnable : BOOL; // Enable press control
    rWebSpeedRef : REAL; // Reference web speed [m/min]
    rTensionRef : REAL; // Reference tension [N]
    rActualTension : REAL; // Load cell feedback [N]
    rCIDrumTempRef : REAL; // CI Drum temp setpoint [C]
    rCIDrumTempAct : REAL; // CI Drum actual temp [C]
    rColorDeckPosRef : ARRAY[1..8] OF LREAL; // Reference positions for 8 color decks
    rColorDeckPosAct : ARRAY[1..8] OF LREAL; // Actual positions for 8 color decks
    rColorDeckSyncMark : ARRAY[1..8] OF LREAL; // Sync marks for registration
END_VAR
VAR_OUTPUT
    rUnwindTorqueRef : REAL; // Torque reference for unwind motor [%]
    bHeaterOn : BOOL; // CI Drum heater control
    bChillerOn : BOOL; // CI Drum chiller control
    rColorDeckTorqueRef : ARRAY[1..8] OF REAL; // Torque output for color decks
    bPressReady : BOOL;
    bTensionError : BOOL;
    bTempError : BOOL;
    bRegistrationError : BOOL;
END_VAR
VAR
    // PID for Tension
    rTensionKp : REAL := 2.5;
    rTensionKi : REAL := 0.5;
    rTensionKd : REAL := 0.1;
    rTensionError : REAL;
    rTensionErrorPrev : REAL;
    rTensionIntegral : REAL;
    rTensionDerivative : REAL;

    // Thermal Regulation for CI Drum
    rTempDeadband : REAL := 1.0;
    rTempError : REAL;
    tCoolingTimer : TON;
    tHeatingTimer : TON;

    // Registration Control
    i : INT;
    rRegKp : LREAL := 15.0;
    rRegError : LREAL;

    // State machine
    eState : (INIT, RUNNING, FAULT) := INIT;
END_VAR

// Control Logic
CASE eState OF
    INIT:
        bPressReady := FALSE;
        rUnwindTorqueRef := 0.0;
        bHeaterOn := FALSE;
        bChillerOn := FALSE;
        FOR i := 1 TO 8 DO
            rColorDeckTorqueRef[i] := 0.0;
        END_FOR

        IF bEnable THEN
            eState := RUNNING;
            bPressReady := TRUE;
        END_IF

    RUNNING:
        IF NOT bEnable THEN
            eState := INIT;
        END_IF

        // 1. Unwind Web Tension PID Control
        rTensionError := rTensionRef - rActualTension;
        rTensionIntegral := rTensionIntegral + rTensionError * 0.01; // Assume 10ms cycle time

        // Anti-windup
        IF rTensionIntegral > 100.0 THEN
            rTensionIntegral := 100.0;
        ELSIF rTensionIntegral < -100.0 THEN
            rTensionIntegral := -100.0;
        END_IF

        rTensionDerivative := (rTensionError - rTensionErrorPrev) / 0.01;
        rUnwindTorqueRef := (rTensionKp * rTensionError) + (rTensionKi * rTensionIntegral) + (rTensionKd * rTensionDerivative);
        rTensionErrorPrev := rTensionError;

        IF ABS(rTensionError) > 50.0 THEN
            bTensionError := TRUE;
            eState := FAULT;
        ELSE
            bTensionError := FALSE;
        END_IF

        // 2. CI Drum Thermal Regulation
        rTempError := rCIDrumTempRef - rCIDrumTempAct;
        IF rTempError > rTempDeadband THEN
            bHeaterOn := TRUE;
            bChillerOn := FALSE;
        ELSIF rTempError < -rTempDeadband THEN
            bHeaterOn := FALSE;
            bChillerOn := TRUE;
        ELSE
            bHeaterOn := FALSE;
            bChillerOn := FALSE;
        END_IF

        IF ABS(rTempError) > 10.0 THEN
            bTempError := TRUE;
            eState := FAULT;
        ELSE
            bTempError := FALSE;
        END_IF

        // 3. Color Deck Servo Registration
        bRegistrationError := FALSE;
        FOR i := 1 TO 8 DO
            rRegError := rColorDeckPosRef[i] - rColorDeckPosAct[i] + rColorDeckSyncMark[i];
            rColorDeckTorqueRef[i] := LREAL_TO_REAL(rRegError * rRegKp);

            IF ABS(rRegError) > 5.0 THEN
                bRegistrationError := TRUE;
                eState := FAULT;
            END_IF
        END_FOR

    FAULT:
        bPressReady := FALSE;
        rUnwindTorqueRef := 0.0;
        bHeaterOn := FALSE;
        bChillerOn := FALSE;
        FOR i := 1 TO 8 DO
            rColorDeckTorqueRef[i] := 0.0;
        END_FOR

        IF NOT bEnable THEN
            eState := INIT;
            bTensionError := FALSE;
            bTempError := FALSE;
            bRegistrationError := FALSE;
        END_IF
END_CASE
END_FUNCTION_BLOCK
