FUNCTION_BLOCK FB_CorrugatorLineControl
TITLE = 'Corrugator Line Advanced Master Control'
// -----------------------------------------------------------------------------
// Advanced Control for Corrugated Cardboard Manufacturing
// Controls: Single-facer steam pressure profiling, glue roll adhesive film 
//           thickness tracking, and double-backer belt tension.
// -----------------------------------------------------------------------------

VAR_INPUT
    bEnable                 : BOOL;   // System enable
    rLineSpeedCmd_mmin      : REAL;   // Requested line speed (m/min)
    rLineSpeedAct_mmin      : REAL;   // Actual line speed feedback (m/min)

    // Single-Facer Parameters
    rPaperBasisWeight_gsm   : REAL;   // Fluting paper basis weight (g/m^2)
    rTargetSteamPress_bar   : REAL;   // Target steam pressure
    aSteamProfileAct_bar    : ARRAY[1..10] OF REAL; // Actual steam profile zones

    // Glue Station Parameters
    rTargetAdhesiveThick_um : REAL;   // Target glue film thickness (um)
    rGlueViscosity_cP       : REAL;   // Current adhesive viscosity (cP)
    rGlueRollGapAct_um      : REAL;   // Actual gap feedback

    // Double-Backer Parameters
    rTargetTension_N        : REAL;   // Target web tension
    rActualTension_N        : REAL;   // Actual measured tension from load cells
    rHeatPlateTemp_C        : REAL;   // Heat plate temperature
END_VAR

VAR_OUTPUT
    bSystemReady            : BOOL;   // System is ready
    bAlarm                  : BOOL;   // Active alarm

    // Single-Facer Outputs
    aSteamValveCmd_pct      : ARRAY[1..10] OF REAL; // Commands for 10 steam zones

    // Glue Station Outputs
    rGlueRollGapCmd_um      : REAL;   // Commanded gap for glue rolls
    rGlueRollSpeedRatio     : REAL;   // Speed ratio relative to line speed

    // Double-Backer Outputs
    rBeltTensionCmd_pct     : REAL;   // Brake/Drive command for tension (0-100%)
END_VAR

VAR
    // PID Controllers for Steam Zones
    aSteamPID_Err           : ARRAY[1..10] OF REAL;
    aSteamPID_Int           : ARRAY[1..10] OF REAL;

    // Constants
    Kp_Steam                : REAL := 2.5;
    Ki_Steam                : REAL := 0.1;
    Kd_Steam                : REAL := 0.05;

    Kp_Glue                 : REAL := 1.2;
    Kp_Tension              : REAL := 3.0;
    Ki_Tension              : REAL := 0.2;

    // State variables
    rTensionInt             : REAL := 0.0;
    i                       : INT;
    rViscosityComp          : REAL;
    rSpeedComp              : REAL;
    rTensionErr             : REAL;
END_VAR

// Enable Check
IF NOT bEnable THEN
    bSystemReady := FALSE;
    bAlarm := FALSE;
    FOR i := 1 TO 10 DO
        aSteamValveCmd_pct[i] := 0.0;
    END_FOR;
    rGlueRollGapCmd_um := 0.0;
    rGlueRollSpeedRatio := 1.0;
    rBeltTensionCmd_pct := 0.0;
    RETURN;
END_IF;

bSystemReady := TRUE;
bAlarm := FALSE;

// -----------------------------------------------------------------------------
// 1. Single-Facer Steam Pressure Profiling
// Adjusts 10 steam zones based on target pressure and basis weight compensation
// -----------------------------------------------------------------------------
// Calculate baseline offset based on paper weight and speed
rSpeedComp := (rLineSpeedAct_mmin / 150.0); // Normalised to 150 m/min max

FOR i := 1 TO 10 DO
    // Calculate Error
    aSteamPID_Err[i] := rTargetSteamPress_bar - aSteamProfileAct_bar[i];

    // Integrate Error
    aSteamPID_Int[i] := aSteamPID_Int[i] + (aSteamPID_Err[i] * 0.01); // Assuming 10ms task

    // PI Control (ignoring derivative for thermal inertia)
    aSteamValveCmd_pct[i] := (Kp_Steam * aSteamPID_Err[i]) + (Ki_Steam * aSteamPID_Int[i]);

    // Apply Speed & Paper Weight Feed-Forward
    aSteamValveCmd_pct[i] := aSteamValveCmd_pct[i] + (rSpeedComp * 10.0) + (rPaperBasisWeight_gsm * 0.05);

    // Limit bounds
    IF aSteamValveCmd_pct[i] > 100.0 THEN
        aSteamValveCmd_pct[i] := 100.0;
    ELSIF aSteamValveCmd_pct[i] < 0.0 THEN
        aSteamValveCmd_pct[i] := 0.0;
    END_IF;

    // Alarm on massive tracking error
    IF ABS(aSteamPID_Err[i]) > 2.0 THEN
        bAlarm := TRUE;
    END_IF;
END_FOR;

// -----------------------------------------------------------------------------
// 2. Glue Roll Adhesive Film Thickness Tracking
// Computes roll gap and speed ratio compensating for viscosity and speed
// -----------------------------------------------------------------------------
rViscosityComp := rGlueViscosity_cP / 800.0; // Nominal 800 cP
// If line is faster, we need a slightly higher speed ratio to transfer same amount
rGlueRollSpeedRatio := 0.95 + (rLineSpeedAct_mmin * 0.0005) * rViscosityComp;

// Calculate Gap Command
rGlueRollGapCmd_um := rTargetAdhesiveThick_um * rViscosityComp + (Kp_Glue * (rTargetAdhesiveThick_um - rGlueRollGapAct_um));

// -----------------------------------------------------------------------------
// 3. Double-Backer Belt Tension Control
// Uses a PI loop to regulate web tension in the double backer section
// -----------------------------------------------------------------------------
rTensionErr := rTargetTension_N - rActualTension_N;
rTensionInt := rTensionInt + (rTensionErr * 0.01);

// Anti-windup
IF rTensionInt > 50.0 THEN rTensionInt := 50.0; END_IF;
IF rTensionInt < -50.0 THEN rTensionInt := -50.0; END_IF;

rBeltTensionCmd_pct := (Kp_Tension * rTensionErr) + (Ki_Tension * rTensionInt);

// Feed-forward based on heat plate friction (hotter = less friction usually)
rBeltTensionCmd_pct := rBeltTensionCmd_pct + (rHeatPlateTemp_C * 0.02);

// Output limits
IF rBeltTensionCmd_pct > 100.0 THEN
    rBeltTensionCmd_pct := 100.0;
ELSIF rBeltTensionCmd_pct < 0.0 THEN
    rBeltTensionCmd_pct := 0.0;
END_IF;

// Tension Alarm
IF ABS(rTensionErr) > (rTargetTension_N * 0.2) THEN
    bAlarm := TRUE; // Error > 20%
END_IF;

END_FUNCTION_BLOCK
