FUNCTION_BLOCK FB_ContinuousBiscuitOvenControl
TITLE = 'Continuous Biscuit Baking Oven Advanced Control'
// -----------------------------------------------------------------------------
// DESCRIPTION:
// Advanced control logic for a continuous biscuit baking oven.
// Features: 
// 1) 4-Zone ribbon gas burner PID profiling
// 2) Steel wire mesh belt tension tracking and compensation
// 3) Exhaust stack damper control for constant negative draft
// -----------------------------------------------------------------------------

VAR_INPUT
    // Master Control
    bOvenEnable           : BOOL;      // Start/Stop oven sequence
    bSafetyOk             : BOOL;      // Hardwired safety circuit feedback

    // Process Variables (PV)
    rZone1_Temp_PV        : REAL;      // Zone 1 Burner Temp [°C]
    rZone2_Temp_PV        : REAL;      // Zone 2 Burner Temp [°C]
    rZone3_Temp_PV        : REAL;      // Zone 3 Burner Temp [°C]
    rZone4_Temp_PV        : REAL;      // Zone 4 Burner Temp [°C]

    rBeltTension_PV       : REAL;      // Mesh Belt Tension [N]
    rBeltSpeed_PV         : REAL;      // Belt Speed [m/min]
    rExhaustPressure_PV   : REAL;      // Stack Pressure [Pa] (negative draft)

    // Setpoints (SP)
    rZone1_Temp_SP        : REAL := 220.0;
    rZone2_Temp_SP        : REAL := 240.0;
    rZone3_Temp_SP        : REAL := 210.0;
    rZone4_Temp_SP        : REAL := 180.0;
    rBeltTension_SP       : REAL := 5500.0;
    rExhaustPressure_SP   : REAL := -20.0;
END_VAR

VAR_OUTPUT
    // Control Variables (CV)
    rZone1_GasValve_CV    : REAL;      // 0.0 - 100.0 %
    rZone2_GasValve_CV    : REAL;      // 0.0 - 100.0 %
    rZone3_GasValve_CV    : REAL;      // 0.0 - 100.0 %
    rZone4_GasValve_CV    : REAL;      // 0.0 - 100.0 %

    rBeltTensionMotor_CV  : REAL;      // Tensioning drive command [-100.0 to 100.0 %]
    rExhaustDamper_CV     : REAL;      // Exhaust Damper position 0.0 - 100.0 %

    // Status
    bOvenReady            : BOOL;
    bBeltTensionWarning   : BOOL;
    bDraftError           : BOOL;
    bSystemFault          : BOOL;
END_VAR

VAR
    // Internal States
    nState                : INT := 0;  // State machine index

    // Burner PID Accumulators (simplified P-I logic for demonstration)
    rKi                   : REAL := 0.02;
    rKp                   : REAL := 1.5;

    rZone1_Integ          : REAL;
    rZone2_Integ          : REAL;
    rZone3_Integ          : REAL;
    rZone4_Integ          : REAL;

    rDraftInteg           : REAL;

    // Timers
    tStartupDelay         : TON;
    tTensionFilter        : TON;

    // Working variables
    rErrZ1                : REAL;
    rErrZ2                : REAL;
    rErrZ3                : REAL;
    rErrZ4                : REAL;
    rErrDraft             : REAL;
    rErrTension           : REAL;

    // Const
    rMaxInteg             : REAL := 100.0;
    rMinInteg             : REAL := 0.0;
END_VAR

// -----------------------------------------------------------------------------
// IMPLEMENTATION
// -----------------------------------------------------------------------------

// 1. Safety Interlocks
IF NOT bSafetyOk THEN
    bSystemFault := TRUE;
    bOvenReady := FALSE;
    rZone1_GasValve_CV := 0.0;
    rZone2_GasValve_CV := 0.0;
    rZone3_GasValve_CV := 0.0;
    rZone4_GasValve_CV := 0.0;
    rBeltTensionMotor_CV := 0.0;
    rExhaustDamper_CV := 100.0; // Open damper full for purge
    RETURN;
END_IF;

bSystemFault := FALSE;

// 2. Draft Control (Exhaust Damper) - Always active if safety OK
rErrDraft := rExhaustPressure_SP - rExhaustPressure_PV;
rDraftInteg := rDraftInteg + (rErrDraft * 0.05);

IF rDraftInteg > 100.0 THEN rDraftInteg := 100.0; END_IF;
IF rDraftInteg < 0.0 THEN rDraftInteg := 0.0; END_IF;

rExhaustDamper_CV := (rErrDraft * 2.0) + rDraftInteg;
IF rExhaustDamper_CV > 100.0 THEN rExhaustDamper_CV := 100.0; END_IF;
IF rExhaustDamper_CV < 0.0 THEN rExhaustDamper_CV := 0.0; END_IF;

// Draft validation
bDraftError := (ABS(rErrDraft) > 15.0);

// 3. Belt Tension Tracking (Proportional Control with deadband)
rErrTension := rBeltTension_SP - rBeltTension_PV;
IF ABS(rErrTension) > 200.0 THEN
    // Tension too loose or tight, drive the tensioning motor
    rBeltTensionMotor_CV := rErrTension * 0.05; 
    IF rBeltTensionMotor_CV > 100.0 THEN rBeltTensionMotor_CV := 100.0; END_IF;
    IF rBeltTensionMotor_CV < -100.0 THEN rBeltTensionMotor_CV := -100.0; END_IF;
    bBeltTensionWarning := (ABS(rErrTension) > 1000.0);
ELSE
    rBeltTensionMotor_CV := 0.0;
    bBeltTensionWarning := FALSE;
END_IF;

// 4. Burner Control (Only active when enabled and drafted properly)
IF bOvenEnable AND NOT bDraftError THEN
    bOvenReady := TRUE;

    // Zone 1 PID
    rErrZ1 := rZone1_Temp_SP - rZone1_Temp_PV;
    rZone1_Integ := rZone1_Integ + (rErrZ1 * rKi);
    IF rZone1_Integ > rMaxInteg THEN rZone1_Integ := rMaxInteg; ELSIF rZone1_Integ < rMinInteg THEN rZone1_Integ := rMinInteg; END_IF;
    rZone1_GasValve_CV := (rErrZ1 * rKp) + rZone1_Integ;

    // Zone 2 PID
    rErrZ2 := rZone2_Temp_SP - rZone2_Temp_PV;
    rZone2_Integ := rZone2_Integ + (rErrZ2 * rKi);
    IF rZone2_Integ > rMaxInteg THEN rZone2_Integ := rMaxInteg; ELSIF rZone2_Integ < rMinInteg THEN rZone2_Integ := rMinInteg; END_IF;
    rZone2_GasValve_CV := (rErrZ2 * rKp) + rZone2_Integ;

    // Zone 3 PID
    rErrZ3 := rZone3_Temp_SP - rZone3_Temp_PV;
    rZone3_Integ := rZone3_Integ + (rErrZ3 * rKi);
    IF rZone3_Integ > rMaxInteg THEN rZone3_Integ := rMaxInteg; ELSIF rZone3_Integ < rMinInteg THEN rZone3_Integ := rMinInteg; END_IF;
    rZone3_GasValve_CV := (rErrZ3 * rKp) + rZone3_Integ;

    // Zone 4 PID
    rErrZ4 := rZone4_Temp_SP - rZone4_Temp_PV;
    rZone4_Integ := rZone4_Integ + (rErrZ4 * rKi);
    IF rZone4_Integ > rMaxInteg THEN rZone4_Integ := rMaxInteg; ELSIF rZone4_Integ < rMinInteg THEN rZone4_Integ := rMinInteg; END_IF;
    rZone4_GasValve_CV := (rErrZ4 * rKp) + rZone4_Integ;

    // Output Clamping
    IF rZone1_GasValve_CV > 100.0 THEN rZone1_GasValve_CV := 100.0; ELSIF rZone1_GasValve_CV < 0.0 THEN rZone1_GasValve_CV := 0.0; END_IF;
    IF rZone2_GasValve_CV > 100.0 THEN rZone2_GasValve_CV := 100.0; ELSIF rZone2_GasValve_CV < 0.0 THEN rZone2_GasValve_CV := 0.0; END_IF;
    IF rZone3_GasValve_CV > 100.0 THEN rZone3_GasValve_CV := 100.0; ELSIF rZone3_GasValve_CV < 0.0 THEN rZone3_GasValve_CV := 0.0; END_IF;
    IF rZone4_GasValve_CV > 100.0 THEN rZone4_GasValve_CV := 100.0; ELSIF rZone4_GasValve_CV < 0.0 THEN rZone4_GasValve_CV := 0.0; END_IF;

ELSE
    bOvenReady := FALSE;
    // Shut off gas when not enabled or draft error exists
    rZone1_GasValve_CV := 0.0;
    rZone2_GasValve_CV := 0.0;
    rZone3_GasValve_CV := 0.0;
    rZone4_GasValve_CV := 0.0;
    rZone1_Integ := 0.0;
    rZone2_Integ := 0.0;
    rZone3_Integ := 0.0;
    rZone4_Integ := 0.0;
END_IF;

END_FUNCTION_BLOCK
