FUNCTION_BLOCK FB_WaferWirebonding
VAR_INPUT
    bStartBonding : BOOL;
    rTargetForce_mN : REAL;
    rUltrasonicPower_W : REAL;
    rImpedance_Ohms : REAL;
    rOpticalX_um : REAL;
    rOpticalY_um : REAL;
    rOpticalTheta_deg : REAL;
    rCapillaryTemp_C : REAL;
    bVisionAligned : BOOL;
END_VAR
VAR_OUTPUT
    bBondComplete : BOOL;
    bError : BOOL;
    nErrorID : INT;
    rCurrentForce_mN : REAL;
    rActualPower_W : REAL;
    sBondState : STRING(30);
END_VAR
VAR
    nState : INT := 0;
    rForceProfile : ARRAY[1..10] OF REAL := [10.0, 15.0, 20.0, 25.0, 30.0, 35.0, 30.0, 20.0, 10.0, 0.0];
    nProfileIndex : INT := 1;
    tTimer : TON;
    rImpedanceMismatch : REAL;
    rCompensatedPower : REAL;
    rPositionErrorX : REAL;
    rPositionErrorY : REAL;
    rPositionErrorTheta : REAL;
    bZAxisMoving : BOOL := FALSE;
    bUltrasonicActive : BOOL := FALSE;
END_VAR

// Impedance Matching and Capillary Profiling Logic
rImpedanceMismatch := ABS(50.0 - rImpedance_Ohms);
rCompensatedPower := rUltrasonicPower_W * (1.0 + (rImpedanceMismatch * 0.05));

CASE nState OF
    0: // Idle
        sBondState := 'IDLE';
        bBondComplete := FALSE;
        bError := FALSE;
        nErrorID := 0;
        IF bStartBonding THEN
            nState := 10;
        END_IF

    10: // Optical Alignment
        sBondState := 'ALIGNING';
        IF NOT bVisionAligned THEN
            rPositionErrorX := 0.0 - rOpticalX_um;
            rPositionErrorY := 0.0 - rOpticalY_um;
            rPositionErrorTheta := 0.0 - rOpticalTheta_deg;
            IF ABS(rPositionErrorX) < 0.5 AND ABS(rPositionErrorY) < 0.5 AND ABS(rPositionErrorTheta) < 0.1 THEN
                nState := 20;
            ELSE
                bError := TRUE;
                nErrorID := 101; // Alignment Failed
                nState := 999;
            END_IF
        ELSE
            nState := 20;
        END_IF

    20: // Approach and Force Profiling
        sBondState := 'APPROACH';
        bZAxisMoving := TRUE;
        tTimer(IN:=TRUE, PT:=T#50MS);
        IF tTimer.Q THEN
            tTimer(IN:=FALSE);
            rCurrentForce_mN := rForceProfile[nProfileIndex];
            nProfileIndex := nProfileIndex + 1;
            IF nProfileIndex > 10 THEN
                nProfileIndex := 10;
                bZAxisMoving := FALSE;
                nState := 30;
            END_IF
        END_IF

    30: // Ultrasonic Welding
        sBondState := 'WELDING';
        bUltrasonicActive := TRUE;
        rActualPower_W := rCompensatedPower;
        tTimer(IN:=TRUE, PT:=T#20MS);
        IF tTimer.Q THEN
            tTimer(IN:=FALSE);
            bUltrasonicActive := FALSE;
            rActualPower_W := 0.0;
            nState := 40;
        END_IF

    40: // Retract
        sBondState := 'RETRACTING';
        bZAxisMoving := TRUE;
        rCurrentForce_mN := 0.0;
        tTimer(IN:=TRUE, PT:=T#50MS);
        IF tTimer.Q THEN
            tTimer(IN:=FALSE);
            bZAxisMoving := FALSE;
            nState := 50;
        END_IF

    50: // Complete
        sBondState := 'COMPLETE';
        bBondComplete := TRUE;
        nProfileIndex := 1;
        IF NOT bStartBonding THEN
            nState := 0;
        END_IF

    999: // Error State
        sBondState := 'ERROR';
        bUltrasonicActive := FALSE;
        rActualPower_W := 0.0;
        bZAxisMoving := FALSE;
        IF NOT bStartBonding THEN
            nState := 0;
        END_IF

END_CASE
END_FUNCTION_BLOCK
