FUNCTION_BLOCK FB_Snowmaking_Control
VAR_INPUT
    rAmbientTemp : REAL; (* Ambient Temperature in Celsius *)
    rRelativeHumidity : REAL; (* Relative Humidity (0.0 to 100.0) *)
    rWindSpeed : REAL; (* Wind speed in m/s *)
    rWaterPressure_Bar : REAL; (* Supply water pressure *)
    rAirPressure_Bar : REAL; (* Supply air pressure *)
    bSystemEnable : BOOL; (* Master enable for snowmaking *)
    rTargetSnowDensity : REAL; (* Target snow density parameter *)
    bHydrantLimitSwitches : ARRAY[1..10] OF BOOL; (* Status of hydrants *)
END_VAR
VAR_OUTPUT
    bAirCompressorRun : BOOL; (* Command to start/stop air compressors *)
    rAirCompressorSpeed : REAL; (* Speed reference for VFD (0.0 to 100.0%) *)
    bWaterPumpRun : BOOL; (* Command to start/stop main water pump *)
    rWaterPumpSpeed : REAL; (* Speed reference for VFD *)
    bNucleatorValves : ARRAY[1..10] OF BOOL; (* Nucleator nozzle valves *)
    bBulkValves : ARRAY[1..10] OF BOOL; (* Bulk water nozzles *)
    rCalculatedWetBulb : REAL; (* Calculated Wet-Bulb Temperature *)
    iActiveHydrants : INT; (* Number of active hydrants *)
    sSystemStatus : STRING[50]; (* Status message *)
    bSystemAlarm : BOOL;
    iAlarmCode : INT;
END_VAR
VAR
    rSaturatedVaporPressure : REAL;
    rActualVaporPressure : REAL;
    rWetBulbDepression : REAL;
    i : INT;
    rFlowDemand : REAL;
    tStateTimer : TON;
    iState : INT;
END_VAR

(* Calculate Wet-Bulb Temperature (Stull's Formula approximation for illustration) *)
rCalculatedWetBulb := rAmbientTemp * ATAN(0.151977 * SQRT(rRelativeHumidity + 8.313659)) 
                    + ATAN(rAmbientTemp + rRelativeHumidity) 
                    - ATAN(rRelativeHumidity - 1.676331) 
                    + 0.00391838 * EXPT(rRelativeHumidity, 1.5) * ATAN(0.023101 * rRelativeHumidity) 
                    - 4.686035;

(* State Machine for Sequencing *)
IF NOT bSystemEnable THEN
    iState := 0;
    bAirCompressorRun := FALSE;
    bWaterPumpRun := FALSE;
    rAirCompressorSpeed := 0.0;
    rWaterPumpSpeed := 0.0;
    iActiveHydrants := 0;
    FOR i := 1 TO 10 DO
        bNucleatorValves[i] := FALSE;
        bBulkValves[i] := FALSE;
    END_FOR;
    sSystemStatus := 'SYSTEM DISABLED';
    bSystemAlarm := FALSE;
ELSE
    CASE iState OF
        0: (* Initialization and check conditions *)
            IF rCalculatedWetBulb < -2.0 THEN
                iState := 10;
                sSystemStatus := 'STARTING COMPRESSORS';
            ELSE
                sSystemStatus := 'MARGINAL TEMP - STANDBY';
            END_IF;

        10: (* Start Air Compressors *)
            bAirCompressorRun := TRUE;
            rAirCompressorSpeed := 50.0 + (ABS(rCalculatedWetBulb) * 2.0);
            IF rAirCompressorSpeed > 100.0 THEN rAirCompressorSpeed := 100.0; END_IF;

            IF rAirPressure_Bar > 6.5 THEN
                iState := 20;
                sSystemStatus := 'STARTING WATER PUMPS';
            END_IF;

        20: (* Start Water Pumps *)
            bWaterPumpRun := TRUE;
            rWaterPumpSpeed := 60.0;
            IF rWaterPressure_Bar > 25.0 THEN
                iState := 30;
                sSystemStatus := 'OPENING HYDRANTS';
            END_IF;

        30: (* Hydrant Cascade Sequencing *)
            iActiveHydrants := 0;
            FOR i := 1 TO 10 DO
                IF bHydrantLimitSwitches[i] AND rWaterPressure_Bar > 20.0 THEN
                    bNucleatorValves[i] := TRUE;
                    (* Only open bulk valves if wet-bulb is low enough to freeze high flow *)
                    IF rCalculatedWetBulb < -5.0 THEN
                        bBulkValves[i] := TRUE;
                    ELSE
                        bBulkValves[i] := FALSE;
                    END_IF;
                    iActiveHydrants := iActiveHydrants + 1;
                ELSE
                    bNucleatorValves[i] := FALSE;
                    bBulkValves[i] := FALSE;
                END_IF;
            END_FOR;
            sSystemStatus := 'MAKING SNOW';

            (* Adjust pump speed based on active hydrants to maintain mass-flow *)
            rWaterPumpSpeed := 50.0 + (INT_TO_REAL(iActiveHydrants) * 5.0);
            IF rWaterPumpSpeed > 100.0 THEN rWaterPumpSpeed := 100.0; END_IF;

            (* Fault check *)
            IF rWaterPressure_Bar < 15.0 OR rAirPressure_Bar < 5.0 THEN
                iState := 99; (* Fault state *)
            END_IF;

        99: (* Fault Handling *)
            bSystemAlarm := TRUE;
            iAlarmCode := 1001;
            bWaterPumpRun := FALSE;
            sSystemStatus := 'PRESSURE FAULT SHUTDOWN';
            IF NOT bSystemEnable THEN
                iState := 0; (* Reset on disable *)
            END_IF;
    END_CASE;
END_IF;
END_FUNCTION_BLOCK
