(*
================================================================================
FORMULA 1 AERODYNAMIC WIND TUNNEL CONTROL SYSTEM
High-Speed Rolling Road, Active Yaw/Pitch Matrix & Boundary Layer Suction
================================================================================
Description:
Controls the synchronisation of a steel-belt rolling road up to 300 km/h with 
the main axial fan to simulate accurate ground effects. Dynamically adjusts 
the test article's angle of attack (yaw/pitch) via a kinematic strut matrix 
using pre-programmed aerodynamic sweep profiles. Regulates the boundary layer 
suction system (vacuum pumps) using differential pressure feedback to prevent 
turbulent boundary layer buildup ahead of the rolling road.

Version: 1.0 (Enterprise Grade)
================================================================================
*)

FUNCTION_BLOCK FB_F1_WindTunnelController
VAR_INPUT
    Enable_System           : BOOL;      // Main system enable
    Target_AirSpeed_kmh     : REAL;      // Main axial fan air speed setpoint (0 - 300 km/h)
    Actual_AirSpeed_kmh     : REAL;      // Measured wind speed from Pitot array
    ActiveSweepProfile_ID   : INT;       // Identifier for aero sweep map

    // Boundary Layer Suction Sensor Inputs
    Diff_Pressure_Pitot1_Pa : REAL;      // Upstream static pressure
    Diff_Pressure_Pitot2_Pa : REAL;      // Downstream static pressure near rolling road

    // Strut Position Feedback
    Strut_FL_Actual_mm      : REAL;
    Strut_FR_Actual_mm      : REAL;
    Strut_R_Actual_mm       : REAL;
END_VAR

VAR_OUTPUT
    // Rolling Road outputs
    RollingRoad_SpeedCmd_m_s: REAL;      // Command to VFD for belt speed
    Belt_Sync_Achieved      : BOOL;      // True if belt speed matches air speed within tolerance

    // Kinematic Strut Matrix Commands
    Strut_FL_Cmd_mm         : REAL;
    Strut_FR_Cmd_mm         : REAL;
    Strut_R_Cmd_mm          : REAL;
    Sweep_Active            : BOOL;

    // Boundary Layer Suction Commands
    VacuumPump_SpeedCmd_pct : REAL;      // 0 - 100% command to suction pumps
    BL_Suction_Active       : BOOL;      

    // System Status
    System_Fault            : BOOL;
    System_Status_Code      : INT;
END_VAR

VAR
    // Constants
    MAX_SPEED_KMH           : REAL := 300.0;
    KMH_TO_MS               : REAL := 0.277778;
    SYNC_TOLERANCE_MS       : REAL := 0.5;   // 0.5 m/s sync tolerance

    // PID Controllers for Rolling Road
    RR_PID_Kp               : REAL := 2.5;
    RR_PID_Ki               : REAL := 1.2;
    RR_PID_Error            : REAL;
    RR_PID_Integral         : REAL;
    RR_Speed_Target_m_s     : REAL;
    RR_Actual_Speed_m_s     : REAL;

    // PID for Suction System
    BL_PID_Kp               : REAL := 0.8;
    BL_PID_Ki               : REAL := 0.4;
    BL_PID_Error            : REAL;
    BL_PID_Integral         : REAL;
    BL_Target_Pressure_Pa   : REAL := 50.0; // Desired delta P for boundary layer attachment

    // Sweep Profile Interpolation
    SweepTimer              : TON;
    Current_Pitch_deg       : REAL;
    Current_Yaw_deg         : REAL;
    Current_RideHeight_mm   : REAL;

    // Internal State Machine
    State                   : INT;

    // Wheelbase kinematics constants
    WHEELBASE_MM            : REAL := 3600.0;
    TRACK_WIDTH_MM          : REAL := 1600.0;
    PI                      : REAL := 3.14159265359;
END_VAR

// -----------------------------------------------------------------------------
// MAIN CONTROL LOGIC
// -----------------------------------------------------------------------------

IF NOT Enable_System THEN
    RollingRoad_SpeedCmd_m_s := 0.0;
    VacuumPump_SpeedCmd_pct := 0.0;
    Sweep_Active := FALSE;
    Belt_Sync_Achieved := FALSE;
    RR_PID_Integral := 0.0;
    BL_PID_Integral := 0.0;
    System_Fault := FALSE;
    System_Status_Code := 0; // Stopped
    RETURN;
END_IF;

// 1. ROLLING ROAD SYNCHRONISATION
// The belt speed must dynamically track the actual measured wind speed.
RR_Speed_Target_m_s := Actual_AirSpeed_kmh * KMH_TO_MS;

// Simple PI Controller for Belt Drive VFD (assuming ideal feedback loop inside VFD)
RR_PID_Error := (Target_AirSpeed_kmh - Actual_AirSpeed_kmh) * KMH_TO_MS;
RR_PID_Integral := RR_PID_Integral + (RR_PID_Error * 0.01); // Assuming 10ms cycle time

// Clamp Integral
IF RR_PID_Integral > 5.0 THEN RR_PID_Integral := 5.0; END_IF;
IF RR_PID_Integral < -5.0 THEN RR_PID_Integral := -5.0; END_IF;

RollingRoad_SpeedCmd_m_s := RR_Speed_Target_m_s + (RR_PID_Error * RR_PID_Kp) + RR_PID_Integral;

// Clamp Output to safety limits
IF RollingRoad_SpeedCmd_m_s > (MAX_SPEED_KMH * KMH_TO_MS) THEN
    RollingRoad_SpeedCmd_m_s := MAX_SPEED_KMH * KMH_TO_MS;
ELSIF RollingRoad_SpeedCmd_m_s < 0.0 THEN
    RollingRoad_SpeedCmd_m_s := 0.0;
END_IF;

IF ABS(RR_PID_Error) < SYNC_TOLERANCE_MS THEN
    Belt_Sync_Achieved := TRUE;
ELSE
    Belt_Sync_Achieved := FALSE;
END_IF;


// 2. BOUNDARY LAYER SUCTION CONTROL
// Maintain delta pressure to ensure turbulent layer is stripped off.
BL_PID_Error := BL_Target_Pressure_Pa - (Diff_Pressure_Pitot1_Pa - Diff_Pressure_Pitot2_Pa);
BL_PID_Integral := BL_PID_Integral + (BL_PID_Error * 0.01); // Assuming 10ms cycle time

// Clamp Suction Integral
IF BL_PID_Integral > 50.0 THEN BL_PID_Integral := 50.0; END_IF;
IF BL_PID_Integral < 0.0 THEN BL_PID_Integral := 0.0; END_IF;

VacuumPump_SpeedCmd_pct := (BL_PID_Error * BL_PID_Kp) + BL_PID_Integral;

// Clamp Output
IF VacuumPump_SpeedCmd_pct > 100.0 THEN VacuumPump_SpeedCmd_pct := 100.0; END_IF;
IF VacuumPump_SpeedCmd_pct < 0.0 THEN VacuumPump_SpeedCmd_pct := 0.0; END_IF;

BL_Suction_Active := VacuumPump_SpeedCmd_pct > 5.0;


// 3. ACTIVE YAW AND PITCH KINEMATIC MATRIX
// Only execute aero sweeps if the belt and wind speed are synchronised.
IF Belt_Sync_Achieved THEN
    Sweep_Active := TRUE;
    SweepTimer(IN:=TRUE, PT:=T#10s); // 10 second sweep duration per step

    // Simulated Pre-programmed Aero Map (Lookup based on ActiveSweepProfile_ID)
    CASE ActiveSweepProfile_ID OF
        1: // High-Speed Cornering Map (Low RH, High Yaw, High Pitch)
            Current_RideHeight_mm := 25.0;
            Current_Pitch_deg := 1.2;
            Current_Yaw_deg := 3.5;
        2: // Top Speed Straight Map (Low RH, Low Drag, Zero Yaw)
            Current_RideHeight_mm := 15.0;
            Current_Pitch_deg := -0.5;
            Current_Yaw_deg := 0.0;
        3: // Braking Zone Map (High Pitch Down, Low Front RH)
            Current_RideHeight_mm := 30.0;
            Current_Pitch_deg := 2.5;
            Current_Yaw_deg := 0.0;
        ELSE
            Current_RideHeight_mm := 50.0; // Safe position
            Current_Pitch_deg := 0.0;
            Current_Yaw_deg := 0.0;
    END_CASE;

    // Kinematic Transformation Matrix
    // Calculates absolute strut extension based on vehicle coordinates (Origin: CG)
    // Pitch calculation (positive pitch = nose down)
    // Yaw calculation (positive yaw = nose right)

    Strut_FL_Cmd_mm := Current_RideHeight_mm 
                       - (WHEELBASE_MM / 2.0 * SIN(Current_Pitch_deg * PI / 180.0))
                       + (TRACK_WIDTH_MM / 2.0 * SIN(Current_Yaw_deg * PI / 180.0));

    Strut_FR_Cmd_mm := Current_RideHeight_mm 
                       - (WHEELBASE_MM / 2.0 * SIN(Current_Pitch_deg * PI / 180.0))
                       - (TRACK_WIDTH_MM / 2.0 * SIN(Current_Yaw_deg * PI / 180.0));

    Strut_R_Cmd_mm  := Current_RideHeight_mm 
                       + (WHEELBASE_MM / 2.0 * SIN(Current_Pitch_deg * PI / 180.0));

    IF SweepTimer.Q THEN
        SweepTimer(IN:=FALSE); // Reset timer for next step
    END_IF;
ELSE
    Sweep_Active := FALSE;
    // Return to safe neutral position
    Strut_FL_Cmd_mm := 50.0;
    Strut_FR_Cmd_mm := 50.0;
    Strut_R_Cmd_mm  := 50.0;
END_IF;

System_Status_Code := 1; // Running nominal

END_FUNCTION_BLOCK
