FUNCTION_BLOCK FB_ContinuousMDFHotPress
VAR_INPUT
    bEnable : BOOL; (* Master enable for continuous hot press operation *)
    rMatThickness : REAL; (* Incoming MDF mat thickness at infeed (mm) *)
    rTargetThickness : REAL; (* Target final board thickness (mm) *)
    rPressSpeed : REAL; (* Current requested press belt speed (m/s) *)
    arCylPressures_Actual : ARRAY[1..10] OF REAL; (* Actual hydraulic pressure of 10 daylight cylinder zones (bar) *)
    arSteamTemp_Actual : ARRAY[1..5] OF REAL; (* Actual steam injection temperature across 5 zones (deg C) *)
    bBlisterDetected : BOOL; (* Outfeed ultrasonic blister detection sensor flag *)
END_VAR
VAR_OUTPUT
    arCylPressures_Cmd : ARRAY[1..10] OF REAL; (* Commanded daylight cylinder pressure (bar) *)
    arSteamTemp_Cmd : ARRAY[1..5] OF REAL; (* Commanded steam temperature (deg C) *)
    rMainDriveSpeed : REAL; (* Commanded master drive speed (m/s) *)
    bEmergencyStop : BOOL; (* Trigger physical E-Stop contactor on critical process fault *)
    bAlarmBlister : BOOL; (* HMI Blister alarm flag *)
END_VAR
VAR
    i : INT;
    rThicknessError : REAL;
    rKp_Pressure : REAL := 2.5; (* Proportional gain for pressure profile *)
    rKi_Pressure : REAL := 0.1; (* Integral gain for pressure profile *)
    arPressureIntegral : ARRAY[1..10] OF REAL;
    tBlisterTimer : TON;
    rBasePressure : REAL := 150.0; (* Base operating pressure for typical density *)
END_VAR

(* 
    ======================================================================
    MDF Continuous Hot Press Control Logic
    ======================================================================
*)

(* Master safety and enable logic *)
IF NOT bEnable THEN
    FOR i := 1 TO 10 DO
        arCylPressures_Cmd[i] := 0.0;
    END_FOR;
    FOR i := 1 TO 5 DO
        arSteamTemp_Cmd[i] := 0.0;
    END_FOR;
    rMainDriveSpeed := 0.0;
    bEmergencyStop := FALSE;
    RETURN;
END_IF;

(* Continuous Blister detection outfeed monitoring *)
(* If a blister is detected for more than 2 seconds continuously, we must shut down the line *)
tBlisterTimer(IN := bBlisterDetected, PT := T#2S);
IF tBlisterTimer.Q THEN
    bAlarmBlister := TRUE;
    bEmergencyStop := TRUE;
    rMainDriveSpeed := 0.0;
END_IF;

(* Mat thickness control via multi-zone hydraulic pressure profiling *)
(* The continuous press requires staged pressure reduction from infeed to outfeed *)
rThicknessError := rMatThickness - rTargetThickness;

FOR i := 1 TO 10 DO
    (* Simple PI control for each cylinder zone with stagger adjustments *)
    arPressureIntegral[i] := arPressureIntegral[i] + (rThicknessError * rKi_Pressure);

    (* Anti-windup protection for the integral term *)
    IF arPressureIntegral[i] > 50.0 THEN
        arPressureIntegral[i] := 50.0;
    ELSIF arPressureIntegral[i] < -50.0 THEN
        arPressureIntegral[i] := -50.0;
    END_IF;

    (* Calculate target pressure: Zone 1 is highest, Zone 10 is lowest *)
    arCylPressures_Cmd[i] := (rThicknessError * rKp_Pressure) + arPressureIntegral[i] + rBasePressure - (INT_TO_REAL(i)*5.0);

    (* Absolute pressure hardware limits *)
    IF arCylPressures_Cmd[i] > 300.0 THEN
        arCylPressures_Cmd[i] := 300.0;
    ELSIF arCylPressures_Cmd[i] < 10.0 THEN
        arCylPressures_Cmd[i] := 10.0;
    END_IF;
END_FOR;

(* Steam injection control loop for mat core heating *)
FOR i := 1 TO 5 DO
    (* Base steam temp is dynamically linked to line speed to ensure core cure *)
    arSteamTemp_Cmd[i] := 180.0 + (rPressSpeed * 10.0);

    (* Maximum safe steam temperature limit to prevent surface burns *)
    IF arSteamTemp_Cmd[i] > 220.0 THEN
        arSteamTemp_Cmd[i] := 220.0;
    END_IF;
END_FOR;

(* Pass-through main drive speed unless faulted *)
IF NOT bEmergencyStop THEN
    rMainDriveSpeed := rPressSpeed;
END_IF;
END_FUNCTION_BLOCK
