    CASE #SelfTestState OF
        1: // Sim High Temp
            #Sim_Temp := 150.0;
            #Sim_Pressure := 1.0;
            #Sim_Current := 5.0;
            IF #ChilledWaterValve > 90.0 THEN #SelfTestState := 2; END_IF;
