            #Sim_Current := #AgitatorCurrentHighLimit + 5.0;
            IF NOT #AgitatorCmd THEN #SelfTestState := 4; END_IF;
        4: // Pass
            #SelfTestPassed := TRUE;
            #SelfTestState := 0;
