    IF NOT #SimulationMode THEN RETURN; END_IF;
END_IF;

// RBAC Check
IF #UserRole < 1 THEN
    #RunCmd := FALSE; // Only Operator+ can run
END_IF;

// SCADA Watchdog
IF #ScadaWatchdog = #LastScadaWatchdog THEN
    #ScadaCommsLoss := TRUE;
ELSE
    #ScadaCommsLoss := FALSE;
END_IF;
#LastScadaWatchdog := #ScadaWatchdog;

// PLC Redundancy Failover
#HB_Timer(IN := NOT #SecondaryPLCHB, PT := T#2S);
#PrimaryActive := NOT #HB_Timer.Q;

IF NOT #PrimaryActive THEN
    RETURN; // Yield control to secondary PLC
END_IF;

// Profinet Diagnostics
#CommFault := (#ProfinetStatusWord <> 16#0000);

// Interlocks
#AgitatorOverload := (#SimulationMode AND #Sim_Current > #AgitatorCurrentHighLimit) OR 
                     (NOT #SimulationMode AND #AgitatorCurrent > #AgitatorCurrentHighLimit);
#PressureHigh := (#SimulationMode AND #Sim_Pressure > #PressureHighLimit) OR 
                 (NOT #SimulationMode AND #ReactorPressure > #PressureHighLimit);
#PressureCritical := (#SimulationMode AND #Sim_Pressure > #PressureCriticalLimit) OR 
                     (NOT #SimulationMode AND #ReactorPressure > #PressureCriticalLimit);

IF #Stop OR #AgitatorOverload OR #PressureCritical OR #CommFault OR #ScadaCommsLoss OR #TempDrift THEN
    #RunCmd := FALSE;
ELSIF #Start AND NOT #PressureHigh AND #UserRole >= 1 AND #SelfTestPassed THEN
    #RunCmd := TRUE;
END_IF;

#AgitatorCmd := #RunCmd;

// Multi-stage pressure relief sequence
IF #PressureCritical THEN
    #ReliefSeqStep := 2;
ELSIF #PressureHigh THEN
    #ReliefSeqStep := 1;
ELSE
    #ReliefSeqStep := 0;
END_IF;

CASE #ReliefSeqStep OF
    0:
        #VentValve := FALSE;
        #EmergencyShutoff := FALSE;
    1:
        #VentValve := TRUE;
        #EmergencyShutoff := FALSE;
    2:
        #VentValve := TRUE;
        #EmergencyShutoff := TRUE;
END_CASE;

// PID Control
#PID_ChilledWater(
    Setpoint := #TempSetpoint,
    Input := #AvgReactorTemp,
    Reset := NOT #RunCmd,
    Output => #ChilledWaterValve
);

// Diagnostic Error Codes
#FaultCode := 16#0000;
IF #AgitatorOverload THEN #FaultCode := #FaultCode OR 16#0001; END_IF;
IF #PressureHigh THEN #FaultCode := #FaultCode OR 16#0002; END_IF;
IF #PressureCritical THEN #FaultCode := #FaultCode OR 16#0004; END_IF;
IF #CommFault THEN #FaultCode := #FaultCode OR 16#0008; END_IF;
IF #ScadaCommsLoss THEN #FaultCode := #FaultCode OR 16#0010; END_IF;
IF #TempDrift THEN #FaultCode := #FaultCode OR 16#0020; END_IF;

END_FUNCTION_BLOCK
