        HIL_Comm_Loss := FALSE;
        Last_HIL_Heartbeat := HIL_Heartbeat_In;
        HIL_Heartbeat_Out := HIL_Heartbeat_In + 1; // Echo sync
    END_IF;

    // Automated Pre-Flight Self-Test Routine
    IF Self_Test_Trigger AND State = 0 THEN
        State := 100;
        Self_Test_Step := 1;
    END_IF;

    CASE State OF
        0: // Idle
            System_Ready := TRUE;
            IF Start_Cycle AND NOT Sensor_Drift_Alarm AND NOT HIL_Comm_Loss THEN
                State := 1;
            END_IF;
        1: // Operation (Simplified)
            Vacuum_Pump_Run := TRUE;
        100: // Self-Test Routine
            System_Ready := FALSE;
            CASE Self_Test_Step OF
                1: // Simulate Sensor Drift
                    Simulated_Fault := TRUE;
                    Self_Test_Timer(IN:= TRUE, PT:= t#3s);
                    IF Self_Test_Timer.Q THEN
                        Self_Test_Step := 2;
                        Self_Test_Timer(IN:= FALSE, PT:= t#3s);
                    END_IF;
                2: // Verify system catches simulation
                    Simulated_Fault := FALSE;
                    State := 0; // Test Complete
            END_CASE;
    END_CASE;

    Status := State;
END_FUNCTION_BLOCK
