FUNCTION_BLOCK FB_MaglevGuidewaySwitch
VAR_INPUT
    (* Physical and structural measurement inputs *)
    bSystemEnable           : BOOL;     (* Main safety interlocking enable signal *)
    bEmergencyStopOk        : BOOL;     (* Dual-channel safety relay OK signal from master safety controller *)
    rTrainApproachingSpeed  : REAL;     (* Target train approaching velocity in km/h *)
    rTrainDistanceTarget    : REAL;     (* Distance to guideway switch in meters *)
    bSwitchCommandLeft      : BOOL;     (* Command to actuate switch to left track *)
    bSwitchCommandRight     : BOOL;     (* Command to actuate switch to right track *)
    rAmbientTemp            : REAL;     (* Guideway structure temperature in Celsius for thermal compensation *)
    rNullFluxCoilCurrent    : REAL;     (* Active null-flux coil current feedback in Amperes *)
END_VAR
VAR_OUTPUT
    (* Actuation, status, and safety outputs *)
    bSwitchLockedLeft       : BOOL;     (* Switch mechanically and electrically locked in left position *)
    bSwitchLockedRight      : BOOL;     (* Switch mechanically and electrically locked in right position *)
    bClearanceGranted       : BOOL;     (* 600km/h passing clearance dynamic confirmation signal *)
    rActuatorControlCurrent : REAL;     (* Command signal to sub-second mechanical turnout actuator *)
    bSystemFault            : BOOL;     (* Critical fault requiring immediate safe state *)
    iErrorCode              : INT;      (* Diagnostics code for fault classification *)
END_VAR
VAR
    (* Internal control state variables *)
    iSwitchState            : INT := 0; (* Internal state machine for switch actuation sequence *)
    tActuationTimer         : TON;      (* Sub-second turnout actuation watchdog timer *)
    tClearanceTimer         : TON;      (* Dynamic clearance validation timer *)
    rDynamicClearance       : REAL;     (* Calculated clearance based on speed and thermal expansion *)
    bLeftCommandLatched     : BOOL;
    bRightCommandLatched    : BOOL;
    rThermalExpansionCoef   : REAL := 0.000012; (* Structural steel expansion coefficient *)
    rBaseLength             : REAL := 25.0;     (* Switch base length in meters *)
END_VAR

(* === MAIN LOGIC === *)
(* 1. Safety Interlock Evaluation *)
IF NOT bEmergencyStopOk OR NOT bSystemEnable THEN
    bSwitchLockedLeft := FALSE;
    bSwitchLockedRight := FALSE;
    bClearanceGranted := FALSE;
    rActuatorControlCurrent := 0.0;
    bSystemFault := TRUE;
    iErrorCode := 999; (* Critical Safety Interlock Tripped *)
    iSwitchState := 0;
    RETURN;
END_IF;

(* 2. Thermal Expansion & Clearance Calculation *)
rDynamicClearance := rBaseLength * rThermalExpansionCoef * (rAmbientTemp - 20.0);

(* 3. Switch Command Processing *)
IF bSwitchCommandLeft AND NOT bSwitchCommandRight AND iSwitchState = 0 THEN
    bLeftCommandLatched := TRUE;
    bRightCommandLatched := FALSE;
    iSwitchState := 10;
ELSIF bSwitchCommandRight AND NOT bSwitchCommandLeft AND iSwitchState = 0 THEN
    bRightCommandLatched := TRUE;
    bLeftCommandLatched := FALSE;
    iSwitchState := 20;
END_IF;

(* 4. Main State Machine for Turnout Actuation *)
CASE iSwitchState OF
    0: (* IDLE & LOCKED *)
        rActuatorControlCurrent := 0.0;
        tActuationTimer(IN := FALSE);
        tClearanceTimer(IN := FALSE);
        bSystemFault := FALSE;
        iErrorCode := 0;

    10: (* ACTUATING TO LEFT *)
        bSwitchLockedLeft := FALSE;
        bSwitchLockedRight := FALSE;
        rActuatorControlCurrent := -150.0; (* Negative current for left actuation *)
        tActuationTimer(IN := TRUE, PT := T#800MS); (* Max 800ms for sub-second actuation *)

        IF rNullFluxCoilCurrent < -145.0 THEN
            iSwitchState := 15;
        ELSIF tActuationTimer.Q THEN
            (* Actuation failed to complete in time *)
            bSystemFault := TRUE;
            iErrorCode := 101; (* Actuation Timeout Left *)
            iSwitchState := 99;
        END_IF;

    15: (* VERIFYING LEFT CLEARANCE *)
        rActuatorControlCurrent := -5.0; (* Holding current *)
        bSwitchLockedLeft := TRUE;
        IF (rTrainApproachingSpeed > 550.0) AND (rDynamicClearance < 0.01) THEN
            tClearanceTimer(IN := TRUE, PT := T#50MS);
            IF tClearanceTimer.Q THEN
                bClearanceGranted := TRUE;
                iSwitchState := 0;
                bLeftCommandLatched := FALSE;
            END_IF;
        ELSE
            (* Clearance not sufficient or speed invalid *)
            bSystemFault := TRUE;
            iErrorCode := 201; (* Dynamic Clearance Violation Left *)
            iSwitchState := 99;
        END_IF;

    20: (* ACTUATING TO RIGHT *)
        bSwitchLockedLeft := FALSE;
        bSwitchLockedRight := FALSE;
        rActuatorControlCurrent := 150.0; (* Positive current for right actuation *)
        tActuationTimer(IN := TRUE, PT := T#800MS); (* Max 800ms for sub-second actuation *)

        IF rNullFluxCoilCurrent > 145.0 THEN
            iSwitchState := 25;
        ELSIF tActuationTimer.Q THEN
            (* Actuation failed to complete in time *)
            bSystemFault := TRUE;
            iErrorCode := 102; (* Actuation Timeout Right *)
            iSwitchState := 99;
        END_IF;

    25: (* VERIFYING RIGHT CLEARANCE *)
        rActuatorControlCurrent := 5.0; (* Holding current *)
        bSwitchLockedRight := TRUE;
        IF (rTrainApproachingSpeed > 550.0) AND (rDynamicClearance < 0.01) THEN
            tClearanceTimer(IN := TRUE, PT := T#50MS);
            IF tClearanceTimer.Q THEN
                bClearanceGranted := TRUE;
                iSwitchState := 0;
                bRightCommandLatched := FALSE;
            END_IF;
        ELSE
            (* Clearance not sufficient or speed invalid *)
            bSystemFault := TRUE;
            iErrorCode := 202; (* Dynamic Clearance Violation Right *)
            iSwitchState := 99;
        END_IF;

    99: (* FAULT STATE *)
        rActuatorControlCurrent := 0.0;
        bSwitchLockedLeft := FALSE;
        bSwitchLockedRight := FALSE;
        bClearanceGranted := FALSE;
        tActuationTimer(IN := FALSE);
        tClearanceTimer(IN := FALSE);

END_CASE;

END_FUNCTION_BLOCK
```

