FUNCTION_BLOCK FB_VentMicrobialSampler
VAR_INPUT
    bEnable            : BOOL;     (* System master enable *)
    bEmergencyStop     : BOOL;     (* Safety loop status (Active HIGH = OK) *)
    rAmbientTemp       : REAL;     (* External ocean temperature [°C] *)
    rAmbientPress      : REAL;     (* External ocean pressure [bar] *)
    rChamberTemp       : REAL;     (* Internal chamber temperature [°C] *)
    rChamberPress      : REAL;     (* Internal chamber pressure [bar] *)
    rFluidPH           : REAL;     (* Sample fluid pH level *)
    rFluidRedox        : REAL;     (* Sample fluid Oxidation-Reduction Potential [mV] *)
END_VAR
VAR_OUTPUT
    bSystemReady       : BOOL;     (* System is ready for operation *)
    rHeaterControl     : REAL;     (* Command to titanium vessel heater (0.0-100.0%) *)
    rPumpSpeed         : REAL;     (* Multiplexed pump speed command (0.0-100.0%) *)
    bInletValveOpen    : BOOL;     (* Isobaric inlet valve control *)
    bAlarm             : BOOL;     (* General system warning/alarm *)
    bCriticalFault     : BOOL;     (* Critical fault requiring ROV intervention *)
END_VAR
VAR
    iState             : INT := 0; (* Internal state machine *)
    tHeatingTimer      : TON;      (* Heating duration timer *)
    tSamplingTimer     : TON;      (* Sampling phase timer *)
    rPressureError     : REAL;     (* Delta between ambient and chamber pressure *)
    bIsobaricStable    : BOOL;     (* Flag indicating pressure parity is achieved *)
END_VAR

(* === MAIN SAFETY INTERLOCKS === *)
IF NOT bEmergencyStop THEN
    bSystemReady    := FALSE;
    rHeaterControl  := 0.0;
    rPumpSpeed      := 0.0;
    bInletValveOpen := FALSE;
    bAlarm          := TRUE;
    bCriticalFault  := TRUE;
    iState          := 999; (* FAULT STATE *)
    RETURN;
END_IF;

(* === CONTINUOUS MONITORING === *)
(* Calculate pressure delta for isobaric sampling (must remain within 0.5 bar) *)
rPressureError := ABS(rAmbientPress - rChamberPress);
bIsobaricStable := (rPressureError < 0.5);

IF (rChamberTemp > 415.0) OR (rChamberPress > 500.0) THEN
    bCriticalFault := TRUE;
    bAlarm := TRUE;
    iState := 999;
END_IF;

(* === MAIN STATE MACHINE === *)
CASE iState OF
    0: (* IDLE & SELF-TEST *)
        bSystemReady := TRUE;
        bInletValveOpen := FALSE;
        rHeaterControl := 0.0;
        rPumpSpeed := 0.0;

        IF bEnable AND bIsobaricStable THEN
            bSystemReady := FALSE;
            iState := 10; (* TRANSITION TO PRE-HEAT *)
        END_IF;

    10: (* PRE-HEAT VESSEL TO 400°C *)
        IF rChamberTemp < 400.0 THEN
            rHeaterControl := 85.0; (* Aggressive heating curve *)
        ELSE
            rHeaterControl := 15.0; (* Maintain temp *)
            tHeatingTimer(IN := TRUE, PT := T#60S);
        END_IF;

        IF tHeatingTimer.Q THEN
            tHeatingTimer(IN := FALSE);
            iState := 20; (* TRANSITION TO SAMPLING *)
        END_IF;

    20: (* ISOBARIC FLUID ROUTING & SAMPLING *)
        bInletValveOpen := TRUE;
        rPumpSpeed := 45.0; (* Gentle aspiration to preserve extremophile morphology *)
        rHeaterControl := 15.0; 

        (* Monitor pH and Redox - abort if sterile seawater intrudes (pH > 7.5) *)
        IF rFluidPH > 7.5 THEN
            bAlarm := TRUE;
            iState := 30; (* ABORT SAMPLING *)
        END_IF;

        tSamplingTimer(IN := TRUE, PT := T#300S);
        IF tSamplingTimer.Q THEN
            tSamplingTimer(IN := FALSE);
            iState := 30; (* TRANSITION TO ISOLATION *)
        END_IF;

    30: (* ISOLATION & COOLDOWN *)
        bInletValveOpen := FALSE;
        rPumpSpeed := 0.0;
        rHeaterControl := 0.0;

        IF rChamberTemp < 50.0 THEN
            bSystemReady := TRUE;
            IF NOT bEnable THEN
                iState := 0; (* RESET TO IDLE *)
            END_IF;
        END_IF;

    999: (* FAULT HANDLING *)
        bInletValveOpen := FALSE;
        rPumpSpeed := 0.0;
        rHeaterControl := 0.0;
        IF NOT bEnable THEN
            bAlarm := FALSE;
            bCriticalFault := FALSE;
            iState := 0;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
