FUNCTION_BLOCK FB_HighSpeedDNASynthesizer
VAR_INPUT
    (* Required physical inputs with types and comments *)
    bEnable            : BOOL;     (* System master enable signal *)
    bEmergencyStop     : BOOL;     (* Safety relay OK signal (TRUE = Safe) *)
    rBlockTemp         : REAL;     (* Current thermal cycling block temperature in Deg C *)
    rFlowCellPressure  : REAL;     (* Current pressure in flow cell (mbar) *)
    bReagentLevelsOk   : BOOL;     (* TRUE if all reagent reservoirs are nominal *)
    iTargetCycleCount  : INT;      (* Number of base pairs to synthesize in sequence *)
END_VAR
VAR_OUTPUT
    (* Required physical outputs with types and comments *)
    bSystemReady       : BOOL;     (* System ready status flag *)
    rHeaterPWM         : REAL;     (* 0-100% control signal to thermal block heater/cooler *)
    rPumpSpeed         : REAL;     (* Main reagent pump speed setpoint (0-10V) *)
    iActiveValveID     : INT;      (* Nano-liter precision manifold valve ID to open *)
    bAlarm             : BOOL;     (* Fault alarm output flag *)
    bSequenceComplete  : BOOL;     (* TRUE when synthesis cycle is fully complete *)
END_VAR
VAR
    (* Internal state variables *)
    iState             : INT := 0; (* Main state machine variable *)
    iCurrentCycle      : INT := 0; (* Current base addition cycle *)

    (* Thermal Block PID Variables *)
    rTempSetpoint      : REAL := 25.0; (* Thermal block setpoint *)
    rTempError         : REAL;
    rTempErrorPrev     : REAL;
    rTempIntegral      : REAL;
    rTempDerivative    : REAL;
    rKp                : REAL := 2.5;  (* Proportional gain *)
    rKi                : REAL := 0.1;  (* Integral gain *)
    rKd                : REAL := 10.0; (* Derivative gain *)

    (* Precision Timing Control *)
    tDispenseTimer     : TON;
    tWashTimer         : TON;
    tFlushTimer        : TON;
END_VAR

(* === MAIN SAFETY AND INTERLOCK LOGIC === *)
IF NOT bEmergencyStop THEN
    bSystemReady := FALSE;
    rHeaterPWM := 0.0;
    rPumpSpeed := 0.0;
    iActiveValveID := 0;
    bAlarm := TRUE;
    iState := 999; (* FAULT STATE *)
    RETURN;
END_IF;

IF rFlowCellPressure > 2500.0 THEN (* 2.5 bar overpressure threshold *)
    bSystemReady := FALSE;
    rPumpSpeed := 0.0;
    iActiveValveID := 0;
    bAlarm := TRUE;
    iState := 999; (* FAULT STATE *)
    RETURN;
END_IF;

(* === THERMAL BLOCK PID CONTROL LOGIC === *)
(* Executes unconditionally unless ESTOP is pressed *)
rTempError := rTempSetpoint - rBlockTemp;
rTempIntegral := rTempIntegral + (rTempError * 0.1); (* Assuming 100ms cycle time *)

(* Anti-windup constraints *)
IF rTempIntegral > 50.0 THEN rTempIntegral := 50.0; END_IF;
IF rTempIntegral < -50.0 THEN rTempIntegral := -50.0; END_IF;

rTempDerivative := (rTempError - rTempErrorPrev) / 0.1;
rHeaterPWM := (rKp * rTempError) + (rKi * rTempIntegral) + (rKd * rTempDerivative);

(* Clamp output to physical limits *)
IF rHeaterPWM > 100.0 THEN rHeaterPWM := 100.0; END_IF;
IF rHeaterPWM < -100.0 THEN rHeaterPWM := -100.0; (* Negative implies Peltier cooling *) END_IF;
rTempErrorPrev := rTempError;

(* === SYNTHESIS SEQUENCE STATE MACHINE === *)
CASE iState OF
    0: (* IDLE *)
        bSystemReady := TRUE;
        bSequenceComplete := FALSE;
        bAlarm := FALSE;
        rPumpSpeed := 0.0;
        iActiveValveID := 0;
        rTempSetpoint := 25.0; (* Maintain standard storage temperature *)

        IF bEnable AND bReagentLevelsOk THEN
            bSystemReady := FALSE;
            iCurrentCycle := 0;
            iState := 10; (* Transition to PREP *)
        END_IF;

    10: (* PREP - Pre-heat block to optimal reaction temperature *)
        rTempSetpoint := 65.0; (* Denaturation/Extension temp threshold *)
        IF ABS(rBlockTemp - rTempSetpoint) < 0.5 THEN
            iState := 20; (* Ready for cycle start *)
        END_IF;

    20: (* CYCLE START - Check if we have completed target cycles *)
        IF iCurrentCycle >= iTargetCycleCount THEN
            iState := 100; (* Proceed to FINAL FLUSH *)
        ELSE
            iCurrentCycle := iCurrentCycle + 1;
            iState := 30; (* DISPENSE REAGENT *)
        END_IF;

    30: (* DISPENSE REAGENT - High precision nano-liter injection *)
        (* Cycle through A, C, G, T building blocks simulated via modulo *)
        iActiveValveID := (iCurrentCycle MOD 4) + 1; 
        rPumpSpeed := 5.0; (* Precise, slow pump speed for stable dispensing *)
        tDispenseTimer(IN := TRUE, PT := T#50MS); (* 50 millisecond ultra-fast burst *)

        IF tDispenseTimer.Q THEN
            tDispenseTimer(IN := FALSE);
            iActiveValveID := 0; (* Close precision valve immediately *)
            rPumpSpeed := 0.0;
            iState := 40; (* WASH *)
        END_IF;

    40: (* WASH - Flush flow cell to remove unbound nucleotides and chemical byproducts *)
        iActiveValveID := 5; (* Dedicated wash buffer manifold valve *)
        rPumpSpeed := 50.0; (* High speed flush velocity *)
        tWashTimer(IN := TRUE, PT := T#2S);

        IF tWashTimer.Q THEN
            tWashTimer(IN := FALSE);
            iActiveValveID := 0;
            rPumpSpeed := 0.0;
            iState := 20; (* Return to cycle loop evaluation *)
        END_IF;

    100: (* FINAL FLUSH - Complete system stabilization and sample preservation *)
        iActiveValveID := 6; (* Storage buffer solution *)
        rPumpSpeed := 25.0;
        rTempSetpoint := 4.0; (* Active cool down to 4C to preserve final DNA sample *)
        tFlushTimer(IN := TRUE, PT := T#10S);

        IF tFlushTimer.Q AND (rBlockTemp < 10.0) THEN
            tFlushTimer(IN := FALSE);
            iActiveValveID := 0;
            rPumpSpeed := 0.0;
            iState := 110; (* COMPLETE *)
        END_IF;

    110: (* COMPLETE *)
        bSequenceComplete := TRUE;
        bSystemReady := TRUE;

        (* Wait for operator to clear the line by disabling *)
        IF NOT bEnable THEN
            iState := 0;
        END_IF;

    999: (* FAULT RECOVERY - Await manual clear or reset *)
        IF NOT bAlarm AND NOT bEnable THEN
            iState := 0; (* Reset to IDLE if alarm cleared and system disabled *)
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
