FUNCTION_BLOCK FB_DeepSpaceAntennaTracker
VAR_INPUT
    bEnable                 : BOOL;     (* System master enable *)
    bEmergencyStop          : BOOL;     (* Safety circuit OK *)
    rAzimuthTarget          : LREAL;    (* Ephemeris Azimuth Target in Degrees *)
    rElevationTarget        : LREAL;    (* Ephemeris Elevation Target in Degrees *)
    rWindSpeed              : REAL;     (* Wind speed in m/s for feed-forward *)
    rWindDirection          : REAL;     (* Wind direction in degrees *)
    bCryoCoolerOk           : BOOL;     (* LNA cryo-cooler status OK *)
    rLnaTemperature         : REAL;     (* LNA physical temperature in K *)
END_VAR
VAR_OUTPUT
    bSystemReady            : BOOL;     (* Tracker is active and ready *)
    bTrackingLocked         : BOOL;     (* Target error is within tolerances *)
    rAzimuthCommand         : LREAL;    (* Velocity command for Az drive *)
    rElevationCommand       : LREAL;    (* Velocity command for El drive *)
    bCryoFault              : BOOL;     (* Cryo cooling malfunction *)
    bGeneralAlarm           : BOOL;     (* High severity alarm *)
END_VAR
VAR
    iState                  : INT := 0; (* Internal state machine *)
    rAzimuthError           : LREAL;
    rElevationError         : LREAL;
    rAzimuthIntegral        : LREAL := 0.0;
    rElevationIntegral      : LREAL := 0.0;
    tSafetyTimer            : TON;
    tLockTimer              : TON;
    rWindForceCompensation  : LREAL;

    (* Constants for PID Control *)
    Kp_Az                   : LREAL := 25.5;
    Ki_Az                   : LREAL := 0.05;
    Kp_El                   : LREAL := 30.2;
    Ki_El                   : LREAL := 0.08;

    TOLERANCE_DEG           : LREAL := 0.0001; (* Pointing tolerance *)
END_VAR

(* === MAIN LOGIC === *)
IF NOT bEmergencyStop THEN
    bSystemReady := FALSE;
    bTrackingLocked := FALSE;
    rAzimuthCommand := 0.0;
    rElevationCommand := 0.0;
    bGeneralAlarm := TRUE;
    iState := 0;
    RETURN;
END_IF;

(* LNA Cryogenic Monitoring *)
IF NOT bCryoCoolerOk OR (rLnaTemperature > 25.0) THEN
    bCryoFault := TRUE;
    bGeneralAlarm := TRUE;
    iState := 99; (* Fault state *)
ELSE
    bCryoFault := FALSE;
    bGeneralAlarm := FALSE;
END_IF;

CASE iState OF
    0: (* IDLE *)
        bSystemReady := FALSE;
        bTrackingLocked := FALSE;
        IF bEnable AND NOT bGeneralAlarm THEN
            tSafetyTimer(IN := TRUE, PT := T#2S);
            IF tSafetyTimer.Q THEN
                tSafetyTimer(IN := FALSE);
                iState := 10;
            END_IF;
        ELSE
            tSafetyTimer(IN := FALSE);
        END_IF;

    10: (* RUNNING / TRACKING *)
        bSystemReady := TRUE;

        (* Calculate pointing errors *)
        rAzimuthError := rAzimuthTarget; (* Simplified for synthetic scenario *)
        rElevationError := rElevationTarget;

        (* Calculate Integrals with anti-windup *)
        rAzimuthIntegral := rAzimuthIntegral + (rAzimuthError * 0.01);
        rElevationIntegral := rElevationIntegral + (rElevationError * 0.01);

        (* Wind shear feed-forward compensation based on wind direction and antenna orientation *)
        rWindForceCompensation := rWindSpeed * 0.005;

        (* PI Control + Feed-forward *)
        rAzimuthCommand := (Kp_Az * rAzimuthError) + (Ki_Az * rAzimuthIntegral) + rWindForceCompensation;
        rElevationCommand := (Kp_El * rElevationError) + (Ki_El * rElevationIntegral) + rWindForceCompensation;

        (* Check tracking lock status *)
        IF (ABS(rAzimuthError) < TOLERANCE_DEG) AND (ABS(rElevationError) < TOLERANCE_DEG) THEN
            tLockTimer(IN := TRUE, PT := T#3S);
            IF tLockTimer.Q THEN
                bTrackingLocked := TRUE;
            END_IF;
        ELSE
            tLockTimer(IN := FALSE);
            bTrackingLocked := FALSE;
        END_IF;

        IF NOT bEnable THEN
            iState := 0;
        END_IF;

    99: (* FAULT HANDLING *)
        bSystemReady := FALSE;
        bTrackingLocked := FALSE;
        rAzimuthCommand := 0.0;
        rElevationCommand := 0.0;
        IF bEnable = FALSE AND bGeneralAlarm = FALSE THEN
            iState := 0;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
