FUNCTION_BLOCK FB_ChocolateTemperingEnrobing
VAR_INPUT
    // Physical I/O - Temperatures (REAL)
    rTempMeltingZone : REAL; // Zone 1: Complete melting (45.0 C)
    rTempCoolingZone : REAL; // Zone 2: Pre-crystallization (27.0 C)
    rTempReheatZone  : REAL; // Zone 3: Form V crystallization (31.0 C)
    rAmbientTemp     : REAL; // Environmental monitoring

    // Physical I/O - Process Variables
    rPumpPressure    : REAL; // Chocolate mass pressure (bar)
    rBeltSpeed       : REAL; // Conveyor speed (m/min)
    rCurtainThick    : REAL; // Ultrasonic curtain thickness (mm)
    rTunnelAirVel    : REAL; // Cooling tunnel air velocity (m/s)

    // System Control
    bEnable          : BOOL;
    bEmergencyStop   : BOOL;
    bReset           : BOOL;
END_VAR

VAR_OUTPUT
    // Actuators
    rMeltingHeaterCV : REAL; // 0-100%
    rCoolingValveCV  : REAL; // 0-100%
    rReheatHeaterCV  : REAL; // 0-100%
    rPumpSpeedCommand: REAL; // VFD 0-100%
    rBlowerVFD       : REAL; // Tunnel cooling blower 0-100%
    rAirKnifePress   : REAL; // Enrober air knife pressure command

    // Status & Alarms
    iState           : INT;
    bReadyToEnrobe   : BOOL;
    bFormV_Stable    : BOOL;
    bAlarm           : BOOL;
    iAlarmCode       : INT;
END_VAR

VAR
    // Internal State
    eTempState : (INIT, MELTING, COOLING, REHEAT, HOLDING, FAULT);
    tMeltingTimer : TON;
    tCoolingTimer : TON;
    tReheatTimer  : TON;

    // Internal Limits & Setpoints
    rSpMelt   : REAL := 45.0;
    rSpCool   : REAL := 27.2;
    rSpReheat : REAL := 31.5;
    rSpThick  : REAL := 2.5; // Target thickness 2.5mm

    // PI Controller Accumulators (simplified)
    rMeltIntegral   : REAL;
    rCoolIntegral   : REAL;
    rReheatIntegral : REAL;
    rThickIntegral  : REAL;
END_VAR

// =====================================================================
// CORE LOGIC: Tempering & Enrobing Control
// =====================================================================

// Safety and Emergency Handling
IF bEmergencyStop THEN
    eTempState := FAULT;
    iAlarmCode := 9999;
    bAlarm := TRUE;
    rMeltingHeaterCV := 0.0;
    rCoolingValveCV := 100.0; // Max cooling on estop
    rReheatHeaterCV := 0.0;
    rPumpSpeedCommand := 0.0;
    rBlowerVFD := 100.0;
    rAirKnifePress := 0.0;
    bReadyToEnrobe := FALSE;
    bFormV_Stable := FALSE;
    RETURN;
END_IF;

// Reset Logic
IF bReset AND eTempState = FAULT THEN
    eTempState := INIT;
    bAlarm := FALSE;
    iAlarmCode := 0;
END_IF;

IF NOT bEnable THEN
    eTempState := INIT;
END_IF;

// State Machine for Tempering (Form V Cocoa Butter Crystals)
CASE eTempState OF
    INIT:
        bReadyToEnrobe := FALSE;
        bFormV_Stable := FALSE;
        IF bEnable THEN
            eTempState := MELTING;
        END_IF;

    MELTING:
        // Goal: Destroy all crystal history (Form I-VI)
        // PI Control for Melting Heater
        rMeltingHeaterCV := (rSpMelt - rTempMeltingZone) * 5.0 + rMeltIntegral;
        IF rMeltingHeaterCV > 100.0 THEN rMeltingHeaterCV := 100.0; END_IF;
        IF rMeltingHeaterCV < 0.0 THEN rMeltingHeaterCV := 0.0; END_IF;

        tMeltingTimer(IN:= (rTempMeltingZone >= rSpMelt - 0.5), PT:= T#10M);
        IF tMeltingTimer.Q THEN
            eTempState := COOLING;
        END_IF;

    COOLING:
        // Goal: Create unstable crystals (Forms IV and V)
        rCoolingValveCV := (rTempCoolingZone - rSpCool) * 8.0 + rCoolIntegral;
        IF rCoolingValveCV > 100.0 THEN rCoolingValveCV := 100.0; END_IF;
        IF rCoolingValveCV < 0.0 THEN rCoolingValveCV := 0.0; END_IF;

        tCoolingTimer(IN:= (rTempCoolingZone <= rSpCool + 0.2), PT:= T#5M);
        IF tCoolingTimer.Q THEN
            eTempState := REHEAT;
        END_IF;

    REHEAT:
        // Goal: Melt out unstable Form IV, leaving only stable Form V
        rReheatHeaterCV := (rSpReheat - rTempReheatZone) * 6.0 + rReheatIntegral;
        IF rReheatHeaterCV > 100.0 THEN rReheatHeaterCV := 100.0; END_IF;
        IF rReheatHeaterCV < 0.0 THEN rReheatHeaterCV := 0.0; END_IF;

        tReheatTimer(IN:= (rTempReheatZone >= rSpReheat - 0.2 AND rTempReheatZone <= rSpReheat + 0.2), PT:= T#8M);
        IF tReheatTimer.Q THEN
            eTempState := HOLDING;
            bFormV_Stable := TRUE;
        END_IF;

    HOLDING:
        bReadyToEnrobe := TRUE;
        // Maintain Form V temperature
        rReheatHeaterCV := (rSpReheat - rTempReheatZone) * 4.0;
        // Thickness Control loop for Enrober Air Knife
        rThickIntegral := rThickIntegral + (rCurtainThick - rSpThick) * 0.01;
        rAirKnifePress := (rCurtainThick - rSpThick) * 2.5 + rThickIntegral;

        // Blower curve based on ambient and belt speed
        rBlowerVFD := (rAmbientTemp - 20.0) * 2.0 + (rBeltSpeed * 10.0);
        IF rBlowerVFD > 100.0 THEN rBlowerVFD := 100.0; END_IF;
        IF rBlowerVFD < 0.0 THEN rBlowerVFD := 0.0; END_IF;

        IF rTempReheatZone < 29.0 OR rTempReheatZone > 33.0 THEN
            eTempState := FAULT;
            iAlarmCode := 101; // Tempering Loss
        END_IF;

    FAULT:
        bReadyToEnrobe := FALSE;
        bFormV_Stable := FALSE;
        rMeltingHeaterCV := 0.0;
        rReheatHeaterCV := 0.0;
        rPumpSpeedCommand := 0.0;
        rBlowerVFD := 0.0;
        rAirKnifePress := 0.0;
END_CASE;

iState := eTempState;

END_FUNCTION_BLOCK
