        // Protections
        #vibration_timer(IN := (#vibration_level > 7.0), PT := T#2S);
        #alarm_vibration := #vibration_timer.Q;

        #sample_timer(IN := NOT #sample_timer.Q, PT := T#100MS);
        IF #sample_timer.Q THEN
            #roc_pressure := (#penstock_pressure - #prev_pressure) / 0.1;
            #prev_pressure := #penstock_pressure;
        END_IF;
        #alarm_water_hammer := (#penstock_pressure > 15.0) OR (#roc_pressure > 5.0);

        // Sync
        #sync_ok := (ABS(#grid_voltage - #gen_voltage) < 5.0) AND (ABS(#grid_freq - #gen_freq) < 0.1);

        // Diagnostics
        IF #alarm_vibration THEN #pn_io_out.diag_code := 1001;
        ELSIF #alarm_water_hammer THEN #pn_io_out.diag_code := 1002;
        ELSIF #pn_io_in.ack_faults AND has_control_rights THEN #pn_io_out.diag_code := 0;
        END_IF;

        // Secure Control Logic
        IF #pn_io_out.diag_code >= 1000 THEN
            #turbine_running := FALSE;
        ELSIF #pn_io_in.remote_start AND has_control_rights THEN
            #turbine_running := TRUE;
        ELSIF #pn_io_in.remote_stop AND has_control_rights THEN
            #turbine_running := FALSE;
        END_IF;

        #breaker_close_cmd := #turbine_running AND #sync_ok;
    ELSE
        // Secure Standby State
        #wicket_gate_pos := 0.0;
        #breaker_close_cmd := FALSE;
    END_IF;

    // SCADA Feedback
    IF #turbine_running THEN
        #scada_out.active_power := 50.0; // Simulated MW
    ELSE
        #scada_out.active_power := 0.0;
    END_IF;
END_FUNCTION_BLOCK
