FUNCTION_BLOCK FB_DAC_VTSA_Controller
TITLE = 'Direct Air Capture VTSA Controller'
VERSION : '1.0'

(*
    Mega-Facility Direct Air Capture (DAC) VTSA Controller
    - Modulates massive axial fan arrays (500,000 m3/hr).
    - Controls Adsorption / Vacuum Temperature Swing Desorption.
    - Prevents pore condensation using absolute humidity tracking.
    - Manages steam injection thermal ramping (100 C) and vacuum (<50 mbar).
    - Enthalpy recovery using sensible heat cross-exchangers.
*)

VAR_INPUT
    bEnable                 : BOOL;   // System enable
    bEstop                  : BOOL;   // Emergency Stop
    fAmbientTemp            : LREAL;  // [DegC] Ambient Air Temperature
    fAmbientRH              : LREAL;  // [%] Ambient Relative Humidity
    fSorbentTemp            : LREAL;  // [DegC] Sorbent Bed Temperature
    fVesselPressure         : LREAL;  // [mbar] Vessel Absolute Pressure
    fCO2Concentration       : LREAL;  // [ppm] Incoming CO2 Concentration
    fProductCO2Purity       : LREAL;  // [%] Desorbed CO2 Purity
END_VAR

VAR_OUTPUT
    ePackMLState            : INT;    // 1=Stopped, 2=Starting, 3=Idle, 4=Running, 5=Completing, 6=Aborted
    fFanSpeedCmd            : LREAL;  // [RPM] Axial fan array command
    fVacuumPumpVFD          : LREAL;  // [%] Vacuum pump speed command
    fSteamValvePos          : LREAL;  // [%] Steam injection valve
    fHeatRecoveryValvePos   : LREAL;  // [%] Enthalpy recovery valve
    bAirDamperOpen          : BOOL;   // Open inlet/outlet air dampers
    bCO2ProductValveOpen    : BOOL;   // Open CO2 outlet line
    bAlarm                  : BOOL;   // Active Alarm
    sAlarmMessage           : STRING(255);
END_VAR

VAR
    // State Machine
    ePhase                  : INT := 0; // 0=Wait, 1=Adsorption, 2=HeatRecoveryIn, 3=Desorption(VTSA), 4=HeatRecoveryOut, 5=Cooling
    fTimer                  : LREAL := 0.0;

    // Internal calculations
    fSatVaporPressure       : LREAL;  // [mbar]
    fAbsoluteHumidity       : LREAL;  // [g/m3]
    fDewPointTemp           : LREAL;  // [DegC]

    // Tuning parameters
    fTargetDesorbTemp       : LREAL := 100.0;  // [DegC]
    fTargetDesorbPress      : LREAL := 50.0;   // [mbar]
    fAdsorptionTime         : LREAL := 7200.0; // [sec] 2 hours
    fDesorptionTime         : LREAL := 1800.0; // [sec] 30 minutes
    fFanMaxSpeed            : LREAL := 1500.0; // [RPM]
END_VAR

// -----------------------------------------------------------------------------
// Thermodynamic Calculations (Magnus-Tetens formula approx)
// -----------------------------------------------------------------------------
// Saturation vapor pressure (mbar)
fSatVaporPressure := 6.112 * EXP((17.67 * fAmbientTemp) / (fAmbientTemp + 243.5));

// Absolute humidity (g/m^3)
fAbsoluteHumidity := (fSatVaporPressure * fAmbientRH * 2.16679) / (273.15 + fAmbientTemp);

// Dew point (DegC) approximation
fDewPointTemp := (243.5 * LN((fAmbientRH/100.0) * fSatVaporPressure / 6.112)) / 
                 (17.67 - LN((fAmbientRH/100.0) * fSatVaporPressure / 6.112));

// -----------------------------------------------------------------------------
// PackML State Machine Mapping & Safety
// -----------------------------------------------------------------------------
IF bEstop THEN
    ePackMLState := 6; // Aborted
    ePhase := 0;
    fFanSpeedCmd := 0.0;
    fVacuumPumpVFD := 0.0;
    fSteamValvePos := 0.0;
    fHeatRecoveryValvePos := 0.0;
    bAirDamperOpen := FALSE;
    bCO2ProductValveOpen := FALSE;
    bAlarm := TRUE;
    sAlarmMessage := 'EMERGENCY STOP ACTIVE. ALL SYSTEMS SECURED.';
    RETURN;
END_IF;

IF NOT bEnable THEN
    ePackMLState := 1; // Stopped
    ePhase := 0;
    fFanSpeedCmd := 0.0;
    fVacuumPumpVFD := 0.0;
    fSteamValvePos := 0.0;
    fHeatRecoveryValvePos := 0.0;
    bAirDamperOpen := FALSE;
    bCO2ProductValveOpen := FALSE;
    RETURN;
END_IF;

IF ePackMLState = 1 OR ePackMLState = 6 THEN
    ePackMLState := 3; // Idle
END_IF;

// -----------------------------------------------------------------------------
// Process Sequence Control
// -----------------------------------------------------------------------------
CASE ePhase OF
    0: // Wait / Idle
        ePackMLState := 3;
        fFanSpeedCmd := 0.0;
        fVacuumPumpVFD := 0.0;
        fSteamValvePos := 0.0;
        fHeatRecoveryValvePos := 0.0;
        bAirDamperOpen := FALSE;
        bCO2ProductValveOpen := FALSE;

        IF bEnable THEN
            ePhase := 1;
            fTimer := 0.0;
            ePackMLState := 4; // Running
        END_IF;

    1: // Adsorption Phase
        ePackMLState := 4;
        bAirDamperOpen := TRUE;
        bCO2ProductValveOpen := FALSE;
        fVacuumPumpVFD := 0.0;
        fSteamValvePos := 0.0;
        fHeatRecoveryValvePos := 0.0;

        // Condensation Protection Check
        IF fAmbientTemp <= (fDewPointTemp + 2.0) THEN
            // Throttle airflow to prevent pore condensation
            fFanSpeedCmd := fFanMaxSpeed * 0.4;
            sAlarmMessage := 'WARNING: High moisture, throttling airflow';
            bAlarm := TRUE;
        ELSE
            fFanSpeedCmd := fFanMaxSpeed; // Pull 500,000 m3/hr
            bAlarm := FALSE;
            sAlarmMessage := '';
        END_IF;

        fTimer := fTimer + 1.0; // Assuming 1 sec execution task
        IF fTimer >= fAdsorptionTime THEN
            fTimer := 0.0;
            ePhase := 2; // Move to Heat Recovery Pre-heating
            fFanSpeedCmd := 0.0; // Stop fans
            bAirDamperOpen := FALSE; // Seal vessel
        END_IF;

    2: // Heat Recovery IN
        ePackMLState := 4;
        fHeatRecoveryValvePos := 100.0; // Fully open cross-exchange

        // Wait until bed reaches intermediate temp or timeout
        fTimer := fTimer + 1.0;
        IF fSorbentTemp >= 60.0 OR fTimer >= 300.0 THEN
            fTimer := 0.0;
            ePhase := 3;
            fHeatRecoveryValvePos := 0.0; // Close cross-exchange
        END_IF;

    3: // Desorption (VTSA) Phase
        ePackMLState := 4;
        bCO2ProductValveOpen := TRUE;

        // Steam injection PID approx (proportional control)
        IF fSorbentTemp < fTargetDesorbTemp THEN
            fSteamValvePos := (fTargetDesorbTemp - fSorbentTemp) * 2.5;
            IF fSteamValvePos > 100.0 THEN fSteamValvePos := 100.0; END_IF;
        ELSE
            fSteamValvePos := 0.0;
        END_IF;

        // Vacuum pump PID approx (proportional control)
        IF fVesselPressure > fTargetDesorbPress THEN
            fVacuumPumpVFD := (fVesselPressure - fTargetDesorbPress) * 1.5;
            IF fVacuumPumpVFD > 100.0 THEN fVacuumPumpVFD := 100.0; END_IF;
        ELSE
            fVacuumPumpVFD := 20.0; // Maintain base vacuum
        END_IF;

        fTimer := fTimer + 1.0;
        IF fTimer >= fDesorptionTime THEN
            fTimer := 0.0;
            ePhase := 4;
            fSteamValvePos := 0.0;
            fVacuumPumpVFD := 0.0;
            bCO2ProductValveOpen := FALSE;
        END_IF;

    4: // Heat Recovery OUT (Cool down)
        ePackMLState := 4;
        fHeatRecoveryValvePos := 100.0; // Send heat to next module

        fTimer := fTimer + 1.0;
        IF fSorbentTemp <= 50.0 OR fTimer >= 300.0 THEN
            fTimer := 0.0;
            ePhase := 5;
            fHeatRecoveryValvePos := 0.0;
        END_IF;

    5: // Final Cooling / Repressurization
        ePackMLState := 4;
        bAirDamperOpen := TRUE; // Crack dampers to repressurize and cool
        fFanSpeedCmd := fFanMaxSpeed * 0.1; // Slow flow for cooling

        fTimer := fTimer + 1.0;
        IF fSorbentTemp <= (fAmbientTemp + 5.0) OR fTimer >= 600.0 THEN
            fTimer := 0.0;
            ePhase := 1; // Loop back to Adsorption
        END_IF;

    ELSE
        ePhase := 0;
END_CASE;
END_FUNCTION_BLOCK
