FUNCTION_BLOCK FB_FlyByWire_Control
TITLE = 'Commercial Aviation FBW Control System'
VERSION : '3.1'
AUTHOR : 'Lumina Elite Data Architect'

VAR_INPUT
    bSystemEnable : BOOL; // Main system enable flag

    // Triple Redundant Pitch Sensors (degrees)
    fPitchSensorA : REAL; 
    fPitchSensorB : REAL; 
    fPitchSensorC : REAL; 

    // Triple Redundant AoA Sensors (Angle of Attack)
    fAoASensorA : REAL; 
    fAoASensorB : REAL; 
    fAoASensorC : REAL; 

    // Pilot Stick Inputs
    fPilotPitchCommand : REAL; // -100.0 to 100.0 %
    fPilotRollCommand  : REAL; // -100.0 to 100.0 %

    // Aircraft State
    fAirspeedKnots : REAL; // Current indicated airspeed
    fAltitudeFeet  : REAL; // Current pressure altitude

    // Structural Sensors for Flutter Suppression
    fWingTipAccelLeft  : REAL; // Left wing tip acceleration
    fWingTipAccelRight : REAL; // Right wing tip acceleration
END_VAR

VAR_OUTPUT
    fElevatorActuatorCmd : REAL; // Command to pitch elevator servo
    fAileronActuatorCmd  : REAL; // Command to roll aileron servo
    bAoALimitActive      : BOOL; // True if alpha protection is overriding pilot
    bSensorFault         : BOOL; // True if sensor discrepancy detected
    bFlutterActive       : BOOL; // True if active flutter suppression is engaging
END_VAR

VAR
    // Voting logic variables
    fVotedPitch : REAL;
    fVotedAoA   : REAL;
    fPitchDiffAB, fPitchDiffBC, fPitchDiffCA : REAL;
    fAoADiffAB, fAoADiffBC, fAoADiffCA : REAL;

    // Internal state and protection logic
    fAlphaLimit : REAL := 15.0; // Max allowed AoA before protection kicks in
    fMaxPitchRate : REAL := 10.0;

    fPitchCommandNormalized : REAL;
    fFlutterDampingSignal   : REAL;

    // Timers & Filters
    TON_SensorFault : TON;
    tFaultDelay : TIME := T#500MS;

    bFaultA, bFaultB, bFaultC : BOOL;

    // Constants
    TOLERANCE : REAL := 2.5; // Sensor tolerance in degrees
END_VAR

(* 
    TRIPLE REDUNDANCY VOTING LOGIC (Pitch and AoA)
*)
// Calculate differences for Pitch
fPitchDiffAB := ABS(fPitchSensorA - fPitchSensorB);
fPitchDiffBC := ABS(fPitchSensorB - fPitchSensorC);
fPitchDiffCA := ABS(fPitchSensorC - fPitchSensorA);

// Simple Mid-Value Select or Majority Vote for Pitch
IF (fPitchDiffAB <= TOLERANCE AND fPitchDiffBC <= TOLERANCE AND fPitchDiffCA <= TOLERANCE) THEN
    // All agree, take average
    fVotedPitch := (fPitchSensorA + fPitchSensorB + fPitchSensorC) / 3.0;
    bFaultA := FALSE; bFaultB := FALSE; bFaultC := FALSE;
ELSIF (fPitchDiffAB <= TOLERANCE) THEN
    // C is outlier
    fVotedPitch := (fPitchSensorA + fPitchSensorB) / 2.0;
    bFaultC := TRUE;
ELSIF (fPitchDiffBC <= TOLERANCE) THEN
    // A is outlier
    fVotedPitch := (fPitchSensorB + fPitchSensorC) / 2.0;
    bFaultA := TRUE;
ELSIF (fPitchDiffCA <= TOLERANCE) THEN
    // B is outlier
    fVotedPitch := (fPitchSensorA + fPitchSensorC) / 2.0;
    bFaultB := TRUE;
ELSE
    // Total disagreement, freeze last known good value (not shown for brevity, keeping current)
    bSensorFault := TRUE;
END_IF;

// Calculate differences for Angle of Attack (AoA)
fAoADiffAB := ABS(fAoASensorA - fAoASensorB);
fAoADiffBC := ABS(fAoASensorB - fAoASensorC);
fAoADiffCA := ABS(fAoASensorC - fAoASensorA);

IF (fAoADiffAB <= TOLERANCE AND fAoADiffBC <= TOLERANCE AND fAoADiffCA <= TOLERANCE) THEN
    fVotedAoA := (fAoASensorA + fAoASensorB + fAoASensorC) / 3.0;
ELSIF (fAoADiffAB <= TOLERANCE) THEN
    fVotedAoA := (fAoASensorA + fAoASensorB) / 2.0;
ELSIF (fAoADiffBC <= TOLERANCE) THEN
    fVotedAoA := (fAoASensorB + fAoASensorC) / 2.0;
ELSIF (fAoADiffCA <= TOLERANCE) THEN
    fVotedAoA := (fAoASensorA + fAoASensorC) / 2.0;
ELSE
    bSensorFault := TRUE;
END_IF;

// Fault timer integration
TON_SensorFault(IN := (bFaultA OR bFaultB OR bFaultC), PT := tFaultDelay);
IF TON_SensorFault.Q THEN
    bSensorFault := TRUE;
END_IF;

(*
    ALPHA LIMITER ENVELOPE PROTECTION
    Limits the pilot''s pitch command if the Angle of Attack approaches the critical stall angle.
*)
fPitchCommandNormalized := fPilotPitchCommand; // Default pass-through

IF fVotedAoA > (fAlphaLimit - 2.0) THEN
    bAoALimitActive := TRUE;
    // Apply soft limiting
    IF fPilotPitchCommand > 0.0 THEN
        // Scale down nose-up command as we approach limit
        fPitchCommandNormalized := fPilotPitchCommand * (fAlphaLimit - fVotedAoA) / 2.0;
        IF fPitchCommandNormalized < 0.0 THEN
            fPitchCommandNormalized := 0.0; // Hard clamp at limit
        END_IF;
    END_IF;

    // Auto-nose down if limit exceeded
    IF fVotedAoA >= fAlphaLimit THEN
        fPitchCommandNormalized := -15.0; // Commanded nose down recovery
    END_IF;
ELSE
    bAoALimitActive := FALSE;
END_IF;

(*
    ACTIVE FLUTTER SUPPRESSION
    Use wing tip accelerometers to inject high-frequency damping into control surfaces
    to prevent structural resonance and aerodynamic flutter.
*)
IF fAirspeedKnots > 250.0 THEN
    // Simple out-of-phase feedback to oppose wing tip acceleration
    fFlutterDampingSignal := (fWingTipAccelLeft + fWingTipAccelRight) * -0.5;

    IF ABS(fFlutterDampingSignal) > 1.0 THEN
        bFlutterActive := TRUE;
    ELSE
        bFlutterActive := FALSE;
    END_IF;
ELSE
    fFlutterDampingSignal := 0.0;
    bFlutterActive := FALSE;
END_IF;

(*
    ACTUATOR COMMAND GENERATION
    Summation of pilot inputs, envelope protection, and flutter suppression.
*)
IF bSystemEnable THEN
    // Pitch is primarily pilot (or envelope protection) plus a slight compensation for flutter
    fElevatorActuatorCmd := fPitchCommandNormalized + (fFlutterDampingSignal * 0.1);

    // Roll is pilot plus anti-symmetric flutter damping (aileron response)
    fAileronActuatorCmd  := fPilotRollCommand + (fFlutterDampingSignal * 0.8);
ELSE
    fElevatorActuatorCmd := 0.0;
    fAileronActuatorCmd  := 0.0;
END_IF;

END_FUNCTION_BLOCK
