TYPE E_PackML_State :
(
    eSTATE_UNDEFINED     := 0,
    eSTATE_IDLE          := 1,
    eSTATE_STARTING      := 2,
    eSTATE_EXECUTE       := 3,
    eSTATE_COMPLETING    := 4,
