    eSTATE_ABORTED       := 15,
    eSTATE_CLEARING      := 16
);
END_TYPE

TYPE ST_Vector3D :
STRUCT
    X : LREAL;
    Y : LREAL;
    Z : LREAL;
END_STRUCT
END_TYPE

TYPE ST_SwarmAgentInfo :
STRUCT
    AgentID      : UDINT;
    Position     : ST_Vector3D;
    Velocity     : ST_Vector3D;
    StatusFlag   : DWORD;
END_STRUCT
END_TYPE

FUNCTION_BLOCK FB_Habitat_Swarm3DPrinter
VAR_INPUT
    bEnable                 : BOOL;                 (* Enable block *)
    bStart                  : BOOL;                 (* Start operation *)
    bAbort                  : BOOL;                 (* Abort operation *)

    (* Swarm Tracking & UWB Inter-Agent Data *)
    MyAgentID               : UDINT;                (* Unique ID of this unit *)
    MyCurrentPos            : ST_Vector3D;          (* Current position from local SLAM/UWB *)
    TargetPrintPos          : ST_Vector3D;          (* Next G-code coordinate to extrude at *)
    TargetVelocity          : LREAL;                (* Desired printing feedrate [m/s] *)

    aNeighborAgents         : ARRAY[1..20] OF ST_SwarmAgentInfo; (* Nearest 20 neighbors via UWB *)
    iNumNeighbors           : INT;                  (* Valid neighbors in array *)

    (* Rheology & Material Properties (Lunar Regolith) *)
    lrAmbientTemp           : LREAL;                (* Vacuum ambient temp [K] *)
    lrMaterialTemp          : LREAL;                (* Extruder nozzle temp [K] *)
    lrYieldStress           : LREAL := 2500.0;      (* Bingham Yield Stress [Pa] *)
    lrPlasticViscosity      : LREAL := 150.0;       (* Plastic Viscosity [Pa.s] *)
    lrRequiredFlowRate      : LREAL;                (* Required volumetric flow [m^3/s] *)
END_VAR

VAR_OUTPUT
    (* Status & PackML *)
    eCurrentState           : E_PackML_State;       (* Current ISA-88/PackML State *)
    bReady                  : BOOL;                 (* Ready for G-code stream *)
    bError                  : BOOL;                 (* Active error flag *)
    dwErrorCode             : DWORD;                (* Error code *)

    (* Kinematic Actuation (APF Computed Outputs) *)
    CmdVelocity             : ST_Vector3D;          (* Output velocity vector for chassis *)
    CmdHeading              : LREAL;                (* Output yaw/heading command [rad] *)

    (* Extruder Subsystem *)
    CmdAugerRPM             : LREAL;                (* Computed RPM for Bingham plastic *)
    CmdMicrowavePower       : LREAL;                (* Microwave sintering power [W] *)
    CmdNozzleHeater         : LREAL;                (* PID Output for Nozzle Heater [0-100%] *)
END_VAR

VAR
    (* Internal APF Constants *)
    K_ATTRACT               : LREAL := 5.0;         (* Attractive gain to target *)
    K_REPULSE               : LREAL := 250.0;       (* Repulsive gain against neighbors *)
    R_SAFE                  : LREAL := 1.5;         (* Safe radius [m] *)
    V_MAX                   : LREAL := 0.2;         (* Max rover velocity [m/s] *)

    (* Internal State *)
    F_Attract               : ST_Vector3D;
    F_Repulse               : ST_Vector3D;
    F_Total                 : ST_Vector3D;

    i                       : INT;
    lrDistX, lrDistY, lrDistZ : LREAL;
    lrDistance              : LREAL;
    lrRepulseMag            : LREAL;
    lrSpeed                 : LREAL;

    (* Extrusion Math *)
    lrAugerDiameter         : LREAL := 0.05;        (* 50mm auger *)
    lrAugerPitch            : LREAL := 0.03;        (* 30mm pitch *)
    lrEffectiveArea         : LREAL;
    lrPressureGradient      : LREAL;
    lrSinteringEnergyReq    : LREAL := 1500000.0;   (* Specific energy [J/kg] *)
    lrRegolithDensity       : LREAL := 1800.0;      (* [kg/m^3] *)
END_VAR

(* =============================================================================================
   STATE MACHINE IMPLEMENTATION (ISA-88 / PackML)
============================================================================================= *)
IF bAbort THEN
    eCurrentState := eSTATE_ABORTING;
END_IF

CASE eCurrentState OF
    eSTATE_UNDEFINED:
        IF bEnable THEN
            eCurrentState := eSTATE_CLEARING;
        END_IF

    eSTATE_CLEARING:
        bError := FALSE;
        dwErrorCode := 0;
        eCurrentState := eSTATE_STOPPED;

    eSTATE_STOPPED:
        CmdVelocity.X := 0.0;
        CmdVelocity.Y := 0.0;
        CmdVelocity.Z := 0.0;
        CmdAugerRPM := 0.0;
        CmdMicrowavePower := 0.0;
        IF bStart THEN
            eCurrentState := eSTATE_STARTING;
        END_IF

    eSTATE_STARTING:
        bReady := TRUE;
        eCurrentState := eSTATE_EXECUTE;

    eSTATE_EXECUTE:
        IF NOT bStart THEN
            eCurrentState := eSTATE_STOPPING;
        END_IF

        (* ---------------------------------------------------------------------------------
           1. 3D ARTIFICIAL POTENTIAL FIELD (APF) KINEMATIC SOLVER
           --------------------------------------------------------------------------------- *)
        (* Calculate Attractive Force towards TargetPrintPos *)
        F_Attract.X := K_ATTRACT * (TargetPrintPos.X - MyCurrentPos.X);
        F_Attract.Y := K_ATTRACT * (TargetPrintPos.Y - MyCurrentPos.Y);
        F_Attract.Z := K_ATTRACT * (TargetPrintPos.Z - MyCurrentPos.Z);

        (* Calculate Repulsive Force away from nearby agents (V2V UWB) *)
        F_Repulse.X := 0.0;
        F_Repulse.Y := 0.0;
        F_Repulse.Z := 0.0;

        IF iNumNeighbors > 0 AND iNumNeighbors <= 20 THEN
            FOR i := 1 TO iNumNeighbors DO
                lrDistX := MyCurrentPos.X - aNeighborAgents[i].Position.X;
                lrDistY := MyCurrentPos.Y - aNeighborAgents[i].Position.Y;
                lrDistZ := MyCurrentPos.Z - aNeighborAgents[i].Position.Z;
                lrDistance := SQRT(lrDistX*lrDistX + lrDistY*lrDistY + lrDistZ*lrDistZ);

                IF lrDistance > 0.001 AND lrDistance < R_SAFE THEN
                    (* APF Repulsion Equation: F = K * (1/d - 1/R_SAFE) * (1/d^2) * (delta / d) *)
                    lrRepulseMag := K_REPULSE * ((1.0 / lrDistance) - (1.0 / R_SAFE)) * (1.0 / (lrDistance * lrDistance));

                    F_Repulse.X := F_Repulse.X + (lrRepulseMag * (lrDistX / lrDistance));
                    F_Repulse.Y := F_Repulse.Y + (lrRepulseMag * (lrDistY / lrDistance));
                    F_Repulse.Z := F_Repulse.Z + (lrRepulseMag * (lrDistZ / lrDistance));
                END_IF
            END_FOR
        END_IF

        (* Superposition of Potential Fields *)
        F_Total.X := F_Attract.X + F_Repulse.X;
        F_Total.Y := F_Attract.Y + F_Repulse.Y;
        F_Total.Z := F_Attract.Z + F_Repulse.Z;

        (* Normalize and cap to max velocity *)
        lrSpeed := SQRT(F_Total.X*F_Total.X + F_Total.Y*F_Total.Y + F_Total.Z*F_Total.Z);
        IF lrSpeed > V_MAX THEN
            CmdVelocity.X := (F_Total.X / lrSpeed) * V_MAX;
            CmdVelocity.Y := (F_Total.Y / lrSpeed) * V_MAX;
            CmdVelocity.Z := (F_Total.Z / lrSpeed) * V_MAX;
        ELSE
            CmdVelocity.X := F_Total.X;
            CmdVelocity.Y := F_Total.Y;
            CmdVelocity.Z := F_Total.Z;
        END_IF

        (* Compute Chassis Heading using ATAN2 *)
        CmdHeading := ATAN2(CmdVelocity.Y, CmdVelocity.X);

        (* ---------------------------------------------------------------------------------
           2. VISCOPLASTIC REGOLITH EXTRUSION & BINGHAM RHEOLOGY
           --------------------------------------------------------------------------------- *)
        (* Flow modeling for Bingham plastic moving through an Archimedes screw.
           Assuming simplified Hagen-Poiseuille modification for yield stress. *)
        lrEffectiveArea := 3.14159 * (lrAugerDiameter/2.0) * (lrAugerDiameter/2.0);

        (* Required RPM calculation based on volumetric displacement and slip factor. 
           Volumetric flow Q = (RPM/60) * Pitch * Area * Efficiency *)
        IF lrRequiredFlowRate > 0.0 THEN
            (* Basic geometric RPM *)
            CmdAugerRPM := (lrRequiredFlowRate * 60.0) / (lrAugerPitch * lrEffectiveArea * 0.85); (* 0.85 efficiency / slip *)

            (* Rheological compensation: If flow rate demands high shear, increase RPM to overcome yield *)
            lrPressureGradient := (8.0 * lrPlasticViscosity * lrRequiredFlowRate) / (3.14159 * EXPT(lrAugerDiameter/2.0, 4)) 
                                + (4.0 * lrYieldStress) / (3.14159 * EXPT(lrAugerDiameter/2.0, 3));

            (* Apply non-linear compensation factor based on calculated pressure drop *)
            CmdAugerRPM := CmdAugerRPM * (1.0 + (lrPressureGradient * 0.00001)); 

            (* Microwave Sintering Energy Calculation
               Power (W) = Mass Flow (kg/s) * Specific Heat Energy (J/kg) *)
            CmdMicrowavePower := (lrRequiredFlowRate * lrRegolithDensity) * lrSinteringEnergyReq;

            (* Prevent thermal runaway in vacuum *)
            IF CmdMicrowavePower > 10000.0 THEN
                CmdMicrowavePower := 10000.0; (* Hard limit 10kW per unit *)
            END_IF
        ELSE
            CmdAugerRPM := 0.0;
            CmdMicrowavePower := 0.0;
        END_IF

        (* Extruder PID loop placeholder for maintaining material temperature *)
        CmdNozzleHeater := 50.0; (* Nominal heating *)

    eSTATE_STOPPING:
        CmdVelocity.X := 0.0;
        CmdVelocity.Y := 0.0;
        CmdVelocity.Z := 0.0;
        CmdAugerRPM := 0.0;
        CmdMicrowavePower := 0.0;
        bReady := FALSE;
        eCurrentState := eSTATE_STOPPED;

    eSTATE_ABORTING:
        CmdVelocity.X := 0.0;
        CmdVelocity.Y := 0.0;
        CmdVelocity.Z := 0.0;
        CmdAugerRPM := 0.0;
        CmdMicrowavePower := 0.0;
        bReady := FALSE;
        bError := TRUE;
        dwErrorCode := 16#F0000001;
        eCurrentState := eSTATE_ABORTED;

    eSTATE_ABORTED:
        IF NOT bAbort AND bEnable THEN
            eCurrentState := eSTATE_CLEARING;
        END_IF

END_CASE

END_FUNCTION_BLOCK
