FUNCTION_BLOCK FB_KilnOptimizer_M3
VAR_INPUT
    KilnTemp : REAL;
    TargetTemp : REAL;
    ProductionRate : REAL;
    CoolerBedDepth : REAL;
    SecAirTemp : REAL;
    PN_CommStatus : BOOL;
    CoalMillTrip : BOOL;
    KilnDriveTrip : BOOL;
    SCADA_OverrideEnable : BOOL;
    SCADA_CoalFeedSetpt : REAL;
    SCADA_KilnSpeedSetpt : REAL;
    SecurityViolation : BOOL;
    PartnerPLC_Active : BOOL;
END_VAR
VAR_OUTPUT
    CoalMillFeed : REAL;
    KilnSpeed : REAL;
    GrateSpeed : REAL;
    CoolingFanCap : REAL;
    SystemFault : BOOL;
    FaultCode : INT;
    StandbyActive : BOOL;
    SecurityLockdown : BOOL;
END_VAR
VAR
    TempError : REAL;
END_VAR
BEGIN
    SecurityLockdown := FALSE;
    StandbyActive := FALSE;

    // IEC 62443 Security Check
    IF SecurityViolation THEN
        SecurityLockdown := TRUE;
        SystemFault := TRUE;
        FaultCode := 999;
        CoalMillFeed := 0.0;
        KilnSpeed := 0.1;
        GrateSpeed := 0.0;
        CoolingFanCap := 100.0;
        RETURN;
    END_IF;

    // Hot-Standby Failover
    IF NOT PN_CommStatus AND PartnerPLC_Active THEN
        StandbyActive := TRUE;
        RETURN;
    END_IF;

    // Diagnostics
    SystemFault := FALSE;
    FaultCode := 0;

    IF CoalMillTrip THEN
        SystemFault := TRUE;
        FaultCode := 201; 
    ELSIF KilnDriveTrip THEN
        SystemFault := TRUE;
        FaultCode := 202; 
    ELSIF KilnTemp < 0.0 OR KilnTemp > 2500.0 THEN
        SystemFault := TRUE;
        FaultCode := 301;
    END_IF;

    IF SystemFault THEN
        CoalMillFeed := 0.0;
        KilnSpeed := 0.1; 
        GrateSpeed := 10.0;
        CoolingFanCap := 100.0; 
        RETURN;
    END_IF;

    // SCADA Integration vs Auto Optimization
    IF SCADA_OverrideEnable THEN
        CoalMillFeed := SCADA_CoalFeedSetpt;
        KilnSpeed := SCADA_KilnSpeedSetpt;
    ELSE
        TempError := TargetTemp - KilnTemp;
        CoalMillFeed := (ProductionRate * 0.15) + (TempError * 0.5);
        IF CoalMillFeed > 50.0 THEN CoalMillFeed := 50.0; ELSIF CoalMillFeed < 5.0 THEN CoalMillFeed := 5.0; END_IF;

        KilnSpeed := (ProductionRate * 0.05) + (TempError * 0.02);
        IF KilnSpeed > 5.0 THEN KilnSpeed := 5.0; ELSIF KilnSpeed < 0.5 THEN KilnSpeed := 0.5; END_IF;
    END_IF;

    // Clinker Cooler Optimization
    GrateSpeed := (CoolerBedDepth - 600.0) * 0.1 + (ProductionRate * 0.1);
    IF GrateSpeed > 100.0 THEN GrateSpeed := 100.0; ELSIF GrateSpeed < 10.0 THEN GrateSpeed := 10.0; END_IF;

    CoolingFanCap := 50.0 + (1000.0 - SecAirTemp) * 0.5;
    IF CoolingFanCap > 100.0 THEN CoolingFanCap := 100.0; ELSIF CoolingFanCap < 20.0 THEN CoolingFanCap := 20.0; END_IF;
END_FUNCTION_BLOCK
