FUNCTION_BLOCK "MilkPasteurizer_Regen"
VAR_INPUT
    Start : BOOL;
    Stop : BOOL;
    TempRegenOut : REAL;
    TempPastOut : REAL;
    TempCoolOut : REAL;
    PressRawSide : REAL;
    PressPastSide : REAL;
    SP_PastTemp : REAL := 72.0;
    HoldingTime : TIME := T#15S;
END_VAR

VAR_OUTPUT
    HeaterPID_Out : REAL;
    CoolerPID_Out : REAL;
    MainPump : BOOL;
    BoosterPump : BOOL;
    FDV_Forward : BOOL;
    FDV_Divert : BOOL;
    RegenPressureAlarm : BOOL;
    SystemFault : BOOL;
END_VAR

VAR
    State : INT := 0; // 0=Off, 1=WaterCirc, 2=Prod, 3=Fault
    PID_Heater : "PID_Compact";
    PID_Cooler : "PID_Compact";
    TMR_Hold : TON;
    TMR_DP : TON;
    TempOk : BOOL;
    PressOk : BOOL;
END_VAR

BEGIN
    // State Machine
    IF Stop OR SystemFault THEN
        State := 0;
    ELSIF Start AND State = 0 THEN
        State := 1; // Start with water circulation
    END_IF;

    // Pressure Differential Monitoring (Pasteurized side must be higher pressure)
    PressOk := (PressPastSide > PressRawSide + 0.5);
    TMR_DP(IN := NOT PressOk AND (State > 0), PT := T#2S);
    IF TMR_DP.Q THEN
        RegenPressureAlarm := TRUE;
        SystemFault := TRUE;
    END_IF;

    // Temperature Control
    PID_Heater(
        sMode := 3,
        Setpoint := SP_PastTemp,
        Input := TempPastOut,
        Output => HeaterPID_Out
    );

    PID_Cooler(
        sMode := 3,
        Setpoint := 4.0, // 4C target
        Input := TempCoolOut,
        Output => CoolerPID_Out
    );

    // Holding Logic
    TempOk := (TempPastOut >= SP_PastTemp);
    TMR_Hold(IN := TempOk AND State > 0, PT := HoldingTime);

    // Outputs
    MainPump := (State > 0);
    BoosterPump := MainPump AND PressOk;

    // FDV Logic
    IF State = 2 AND TMR_Hold.Q AND PressOk THEN
        FDV_Forward := TRUE;
        FDV_Divert := FALSE;
    ELSE
        FDV_Forward := FALSE;
        FDV_Divert := TRUE;
    END_IF;
END_FUNCTION_BLOCK
