FUNCTION_BLOCK FB_CMP_SlurryBlending
VAR_INPUT
    (* Physical Input Signals *)
    bSystemEnable           : BOOL;     (* Overall system enable signal *)
    bE_Stop_OK              : BOOL;     (* Safety circuit loop intact, E-Stop released *)
    rSlurryFlowRateIn       : REAL;     (* Incoming unmixed slurry flow rate in L/min *)
    rNanoCeriaConcentration : REAL;     (* Spectrometric reading of Nano-Ceria abrasive wt% *)
    rAcousticEmissionRaw    : REAL;     (* Pad acoustic emission raw rms value, mV *)
    rTargetPH               : REAL;     (* Setpoint for point-of-use pH closed-loop titration *)
    rCurrentPH              : REAL;     (* Actual measured pH at point-of-use *)
    bUltrasonicFilterOK     : BOOL;     (* Ultrasonic filter health status, TRUE=OK *)
END_VAR
VAR_OUTPUT
    (* Physical Output Signals *)
    bReadyToPolish          : BOOL;     (* Blending complete and within specification *)
    rTitrationPumpSpeed     : REAL;     (* Output 0-100% to pH adjustment dosing pump *)
    rUltrasonicAmplitude    : REAL;     (* Output 0-100% to agglomeration filter ultrasonic driver *)
    bCriticalAlarm          : BOOL;     (* System fault, requires immediate abort *)
    iMachineState           : INT;      (* Current operating state code for SCADA *)
END_VAR
VAR
    (* Internal state and filtering *)
    iState                  : INT := 0; 
    tStabilizationTimer     : TON;
    tAcousticFilterTimer    : TON;
    rFilteredPH             : REAL := 7.0;
    rPHError                : REAL;
    rPHIntegral             : REAL := 0.0;
    rKp                     : REAL := 12.5; (* PID Proportional Gain *)
    rKi                     : REAL := 2.1;  (* PID Integral Gain *)
    rSlurryViscosityEst     : REAL;         (* Derived from flow and concentration *)
END_VAR

(* === MAIN LOGIC === *)

(* Safety and Hardware Interlocks *)
IF NOT bE_Stop_OK OR NOT bSystemEnable THEN
    bReadyToPolish := FALSE;
    bCriticalAlarm := TRUE;
    rTitrationPumpSpeed := 0.0;
    rUltrasonicAmplitude := 0.0;
    iState := 0; (* Force to IDLE / FAULT state *)
    iMachineState := 0;
    RETURN;
END_IF;

(* First Order Low Pass Filter for pH measurement *)
rFilteredPH := rFilteredPH + 0.1 * (rCurrentPH - rFilteredPH);
rPHError := rTargetPH - rFilteredPH;

(* Main State Machine *)
CASE iState OF
    0: (* INIT AND DIAGNOSTICS *)
        bReadyToPolish := FALSE;
        bCriticalAlarm := FALSE;
        rPHIntegral := 0.0;

        IF bUltrasonicFilterOK THEN
            iState := 10; (* Move to priming state *)
        ELSE
            bCriticalAlarm := TRUE;
        END_IF;

    10: (* PRIMING & ACOUSTIC BASELINE *)
        (* Activate ultrasonic filter at nominal amplitude to break nano-ceria agglomerates *)
        rUltrasonicAmplitude := 45.0; 

        tStabilizationTimer(IN := TRUE, PT := T#15S);
        IF tStabilizationTimer.Q THEN
            tStabilizationTimer(IN := FALSE);
            iState := 20; (* Start active blending *)
        END_IF;

    20: (* ACTIVE SLURRY BLENDING & TITRATION *)
        (* Calculate dynamic viscosity estimation based on concentration and flow *)
        rSlurryViscosityEst := rNanoCeriaConcentration * 1.05 + (10.0 / (rSlurryFlowRateIn + 0.01));

        (* Adjust ultrasonic amplitude dynamically based on viscosity estimation *)
        IF rSlurryViscosityEst > 50.0 THEN
            rUltrasonicAmplitude := 85.0; (* High energy for dense agglomerates *)
        ELSE
            rUltrasonicAmplitude := 60.0; (* Normal energy *)
        END_IF;

        (* Execute PI Control for point-of-use pH titration *)
        rPHIntegral := rPHIntegral + (rPHError * 0.1); (* Assuming 100ms cycle time *)

        (* Anti-windup for integral term *)
        IF rPHIntegral > 50.0 THEN rPHIntegral := 50.0; END_IF;
        IF rPHIntegral < -50.0 THEN rPHIntegral := -50.0; END_IF;

        rTitrationPumpSpeed := (rPHError * rKp) + rKi * rPHIntegral;

        (* Clamp pump speed output *)
        IF rTitrationPumpSpeed > 100.0 THEN
            rTitrationPumpSpeed := 100.0;
        ELSIF rTitrationPumpSpeed < 0.0 THEN
            rTitrationPumpSpeed := 0.0;
        END_IF;

        (* Check if pH is stable within specification for polish *)
        IF ABS(rPHError) < 0.05 THEN
            tAcousticFilterTimer(IN := TRUE, PT := T#5S);
            IF tAcousticFilterTimer.Q THEN
                bReadyToPolish := TRUE;
                iState := 30; (* Ready State *)
            END_IF;
        ELSE
            tAcousticFilterTimer(IN := FALSE);
            bReadyToPolish := FALSE;
        END_IF;

    30: (* POLISHING ENDPOINT MONITORING *)
        (* Maintain pH and ultrasonic filtering while monitoring pad acoustic emission *)

        rTitrationPumpSpeed := (rPHError * rKp) + rKi * rPHIntegral; (* Continual control *)

        (* Simulated endpoint detection via acoustic emission spike thresholding *)
        IF rAcousticEmissionRaw > 850.0 THEN
            (* Wafer cleared, transition film breached, stop polishing *)
            bReadyToPolish := FALSE;
            rTitrationPumpSpeed := 0.0;
            iState := 0; (* Reset for next wafer *)
        END_IF;

        (* Re-evaluate stability *)
        IF ABS(rPHError) > 0.2 THEN
            iState := 20; (* Return to active blending, lost spec *)
            bReadyToPolish := FALSE;
        END_IF;

END_CASE;

(* Update external machine state tracking *)
iMachineState := iState;

END_FUNCTION_BLOCK
