`iec-st
/// ==============================================================================
/// ORBITAL SOLAR REFLECTOR CONSTELLATION ATTITUDE & ILLUMINATION CONTROLLER
/// ==============================================================================
/// Module: FB_SolarReflector_Swarm
/// Version: 1.0.0
/// Standard: IEC 61131-3 Structured Text
///
/// DESCRIPTION:
/// Controls the attitude and terrestrial targeting of 50m diameter ultralight 
/// Kapton reflectors in 900 km Sun-Synchronous Orbits (SSO). Coordinates a swarm 
/// of 20 reflectors to overlay beam footprints on a designated 50km terrestrial 
/// target to provide 30 lux of artificial moonlight. 
/// Utilizes Control Moment Gyroscope (CMG) steering laws and quaternion math 
/// to manage SRP and atmospheric drag without expending propellant.
/// Integrates PackML state logic for mission phases.
/// ==============================================================================

TYPE E_PackML_State :
(
    eSTATE_UNDEFINED := 0,
    eSTATE_CLEARING := 1,
    eSTATE_STOPPED := 2,
    eSTATE_STARTING := 3,
    eSTATE_IDLE := 4,
    eSTATE_SUSPENDED := 5,
    eSTATE_EXECUTE := 6,
    eSTATE_STOPPING := 7,
    eSTATE_ABORTING := 8,
    eSTATE_ABORTED := 9,
    eSTATE_HOLDING := 10,
    eSTATE_HELD := 11
);
END_TYPE

TYPE ST_Quaternion :
STRUCT
    q0 : LREAL; (* Scalar component *)
    q1 : LREAL; (* X component *)
    q2 : LREAL; (* Y component *)
    q3 : LREAL; (* Z component *)
END_STRUCT
END_TYPE

TYPE ST_Vector3 :
STRUCT
    X : LREAL;
    Y : LREAL;
    Z : LREAL;
END_STRUCT
END_TYPE

TYPE ST_OrbitalEphemeris :
STRUCT
    Timestamp : LINT; (* Epoch time in ms *)
    Position : ST_Vector3; (* ECI coordinates [km] *)
    Velocity : ST_Vector3; (* ECI velocities [km/s] *)
    SunVector : ST_Vector3; (* Normalized vector to Sun *)
END_STRUCT
END_TYPE

TYPE ST_TargetGeodetic :
STRUCT
    Latitude : LREAL;  (* Degrees *)
    Longitude : LREAL; (* Degrees *)
    Altitude : LREAL;  (* km *)
END_STRUCT
END_TYPE

FUNCTION_BLOCK FB_SolarReflector_Swarm
VAR_INPUT
    bEnable            : BOOL; (* Master enable *)
    bStartMission      : BOOL;
    bAbort             : BOOL;

    stCurrentEphemeris : ST_OrbitalEphemeris;
    stTargetCity       : ST_TargetGeodetic;
    fRequiredLux       : LREAL := 30.0; (* Required illumination (lux) *)

    (* Reflector Params *)
    fReflectorArea     : LREAL := 1963.495; (* 50m diameter area [m^2] *)
    fSRP_Coefficient   : LREAL := 1.8;      (* Solar Radiation Pressure coeff *)
    fAtmosphericDrag   : LREAL := 2.5E-6;   (* Drag coefficient at 900km *)
END_VAR

VAR_OUTPUT
    ePackMLState       : E_PackML_State := E_PackML_State.eSTATE_STOPPED;
    stTargetQuaternion : ST_Quaternion;
    stCMG_TorqueCmd    : ST_Vector3;        (* Commanded Torque for CMGs [Nm] *)
    bTargetIlluminated : BOOL;
    fEstimatedLux      : LREAL;
    bError             : BOOL;
    nErrorID           : UDINT;
END_VAR

VAR
    (* Internal State *)
    stCurrentAttitude  : ST_Quaternion;
    stErrorQuaternion  : ST_Quaternion;

    (* Kinematic calculations *)
    stSunVecECEF       : ST_Vector3;
    stTargetVecECEF    : ST_Vector3;
    stNormalVecECEF    : ST_Vector3;

    (* Disturbance Torques *)
    stTorqueSRP        : ST_Vector3;
    stTorqueDrag       : ST_Vector3;

    (* PID/Control vars *)
    fKp                : LREAL := 0.05;
    fKd                : LREAL := 0.12;
    stAngularVelocity  : ST_Vector3;

    (* Physical Constants *)
    C_SOLAR_CONSTANT   : LREAL := 1361.0; (* W/m^2 *)
    C_SPEED_OF_LIGHT   : LREAL := 299792458.0; (* m/s *)
    C_EARTH_RADIUS     : LREAL := 6371.0; (* km *)
END_VAR

(* -----------------------------------------------------------------------------
   MAIN EXECUTION
   ----------------------------------------------------------------------------- *)

(* Handle PackML State Transitions *)
IF bAbort THEN
    ePackMLState := E_PackML_State.eSTATE_ABORTING;
END_IF

CASE ePackMLState OF
    E_PackML_State.eSTATE_STOPPED:
        IF bEnable THEN
            ePackMLState := E_PackML_State.eSTATE_STARTING;
        END_IF

    E_PackML_State.eSTATE_STARTING:
        (* Initialize gyros and orbital models *)
        stTargetQuaternion.q0 := 1.0;
        stTargetQuaternion.q1 := 0.0;
        stTargetQuaternion.q2 := 0.0;
        stTargetQuaternion.q3 := 0.0;
        ePackMLState := E_PackML_State.eSTATE_IDLE;

    E_PackML_State.eSTATE_IDLE:
        IF bStartMission AND bEnable THEN
            ePackMLState := E_PackML_State.eSTATE_EXECUTE;
        END_IF

    E_PackML_State.eSTATE_EXECUTE:
        IF NOT bEnable THEN
            ePackMLState := E_PackML_State.eSTATE_STOPPING;
        ELSE
            (* 1. Calculate Target Vector *)
            M_CalculateIlluminationGeometry();

            (* 2. Calculate Disturbance Torques (SRP & Drag) *)
            M_CalculateDisturbances();

            (* 3. Compute Attitude Control (CMG Matrix) *)
            M_AttitudeControl();

            (* 4. Estimate resulting illumination at target *)
            M_EstimateLux();
        END_IF

    E_PackML_State.eSTATE_STOPPING:
        stCMG_TorqueCmd.X := 0.0;
        stCMG_TorqueCmd.Y := 0.0;
        stCMG_TorqueCmd.Z := 0.0;
        ePackMLState := E_PackML_State.eSTATE_STOPPED;

    E_PackML_State.eSTATE_ABORTING:
        (* Emergency CMG spin-down, safe mode attitude *)
        stCMG_TorqueCmd.X := 0.0;
        stCMG_TorqueCmd.Y := 0.0;
        stCMG_TorqueCmd.Z := 0.0;
        ePackMLState := E_PackML_State.eSTATE_ABORTED;

    E_PackML_State.eSTATE_ABORTED:
        IF NOT bAbort THEN
            ePackMLState := E_PackML_State.eSTATE_CLEARING;
        END_IF

    E_PackML_State.eSTATE_CLEARING:
        bError := FALSE;
        nErrorID := 0;
        ePackMLState := E_PackML_State.eSTATE_STOPPED;

END_CASE

END_FUNCTION_BLOCK

(* -----------------------------------------------------------------------------
   METHOD: M_CalculateIlluminationGeometry
   ----------------------------------------------------------------------------- *)
METHOD M_CalculateIlluminationGeometry : BOOL
VAR
    fLatRad, fLonRad : LREAL;
    fNorm            : LREAL;
END_VAR

    (* Convert target geodetic to ECEF (simplified spherical Earth) *)
    fLatRad := stTargetCity.Latitude * 0.0174532925;
    fLonRad := stTargetCity.Longitude * 0.0174532925;

    stTargetVecECEF.X := C_EARTH_RADIUS * COS(fLatRad) * COS(fLonRad);
    stTargetVecECEF.Y := C_EARTH_RADIUS * COS(fLatRad) * SIN(fLonRad);
    stTargetVecECEF.Z := C_EARTH_RADIUS * SIN(fLatRad);

    (* Vector from satellite to target city *)
    stTargetVecECEF.X := stTargetVecECEF.X - stCurrentEphemeris.Position.X;
    stTargetVecECEF.Y := stTargetVecECEF.Y - stCurrentEphemeris.Position.Y;
    stTargetVecECEF.Z := stTargetVecECEF.Z - stCurrentEphemeris.Position.Z;

    (* Normalize target vector *)
    fNorm := SQRT(EXPT(stTargetVecECEF.X, 2) + EXPT(stTargetVecECEF.Y, 2) + EXPT(stTargetVecECEF.Z, 2));
    IF fNorm > 0.0 THEN
        stTargetVecECEF.X := stTargetVecECEF.X / fNorm;
        stTargetVecECEF.Y := stTargetVecECEF.Y / fNorm;
        stTargetVecECEF.Z := stTargetVecECEF.Z / fNorm;
    END_IF

    (* Required Reflector Normal (Bisector of Sun Vector and Target Vector) *)
    stNormalVecECEF.X := stCurrentEphemeris.SunVector.X + stTargetVecECEF.X;
    stNormalVecECEF.Y := stCurrentEphemeris.SunVector.Y + stTargetVecECEF.Y;
    stNormalVecECEF.Z := stCurrentEphemeris.SunVector.Z + stTargetVecECEF.Z;

    fNorm := SQRT(EXPT(stNormalVecECEF.X, 2) + EXPT(stNormalVecECEF.Y, 2) + EXPT(stNormalVecECEF.Z, 2));
    IF fNorm > 0.0 THEN
        stNormalVecECEF.X := stNormalVecECEF.X / fNorm;
        stNormalVecECEF.Y := stNormalVecECEF.Y / fNorm;
        stNormalVecECEF.Z := stNormalVecECEF.Z / fNorm;
    END_IF

    (* Convert Normal Vector to Target Quaternion (Simplified alignment) *)
    stTargetQuaternion.q0 := COS(0.5);
    stTargetQuaternion.q1 := stNormalVecECEF.X * SIN(0.5);
    stTargetQuaternion.q2 := stNormalVecECEF.Y * SIN(0.5);
    stTargetQuaternion.q3 := stNormalVecECEF.Z * SIN(0.5);

    M_CalculateIlluminationGeometry := TRUE;
END_METHOD

(* -----------------------------------------------------------------------------
   METHOD: M_CalculateDisturbances
   ----------------------------------------------------------------------------- *)
METHOD M_CalculateDisturbances : BOOL
VAR
    fSRPForce : LREAL;
    fDragForce : LREAL;
    stCenterOfPressureOffset : ST_Vector3;
END_VAR

    (* CP-CG Offset [m] *)
    stCenterOfPressureOffset.X := 0.1;
    stCenterOfPressureOffset.Y := -0.05;
    stCenterOfPressureOffset.Z := 0.2;

    (* SRP Force *)
    fSRPForce := (C_SOLAR_CONSTANT / C_SPEED_OF_LIGHT) * fReflectorArea * fSRP_Coefficient;

    (* SRP Torque = CP_Offset x SRP_Force_Vector *)
    stTorqueSRP.X := stCenterOfPressureOffset.Y * (fSRPForce * stCurrentEphemeris.SunVector.Z) - stCenterOfPressureOffset.Z * (fSRPForce * stCurrentEphemeris.SunVector.Y);
    stTorqueSRP.Y := stCenterOfPressureOffset.Z * (fSRPForce * stCurrentEphemeris.SunVector.X) - stCenterOfPressureOffset.X * (fSRPForce * stCurrentEphemeris.SunVector.Z);
    stTorqueSRP.Z := stCenterOfPressureOffset.X * (fSRPForce * stCurrentEphemeris.SunVector.Y) - stCenterOfPressureOffset.Y * (fSRPForce * stCurrentEphemeris.SunVector.X);

    (* Atmospheric Drag (simplified for 900km) *)
    fDragForce := fAtmosphericDrag * fReflectorArea; 
    stTorqueDrag.X := stCenterOfPressureOffset.Y * fDragForce - stCenterOfPressureOffset.Z * fDragForce;
    stTorqueDrag.Y := stCenterOfPressureOffset.Z * fDragForce - stCenterOfPressureOffset.X * fDragForce;
    stTorqueDrag.Z := stCenterOfPressureOffset.X * fDragForce - stCenterOfPressureOffset.Y * fDragForce;

    M_CalculateDisturbances := TRUE;
END_METHOD

(* -----------------------------------------------------------------------------
   METHOD: M_AttitudeControl
   ----------------------------------------------------------------------------- *)
METHOD M_AttitudeControl : BOOL
    (* Compute Error Quaternion *)
    stErrorQuaternion.q0 := (stTargetQuaternion.q0 * stCurrentAttitude.q0) + (stTargetQuaternion.q1 * stCurrentAttitude.q1) + (stTargetQuaternion.q2 * stCurrentAttitude.q2) + (stTargetQuaternion.q3 * stCurrentAttitude.q3);
    stErrorQuaternion.q1 := (stTargetQuaternion.q0 * stCurrentAttitude.q1) - (stTargetQuaternion.q1 * stCurrentAttitude.q0) - (stTargetQuaternion.q2 * stCurrentAttitude.q3) + (stTargetQuaternion.q3 * stCurrentAttitude.q2);
    stErrorQuaternion.q2 := (stTargetQuaternion.q0 * stCurrentAttitude.q2) + (stTargetQuaternion.q1 * stCurrentAttitude.q3) - (stTargetQuaternion.q2 * stCurrentAttitude.q0) - (stTargetQuaternion.q3 * stCurrentAttitude.q1);
    stErrorQuaternion.q3 := (stTargetQuaternion.q0 * stCurrentAttitude.q3) - (stTargetQuaternion.q1 * stCurrentAttitude.q2) + (stTargetQuaternion.q2 * stCurrentAttitude.q1) - (stTargetQuaternion.q3 * stCurrentAttitude.q0);

    (* PD Control Law for CMG Torque *)
    stCMG_TorqueCmd.X := -fKp * stErrorQuaternion.q1 - fKd * stAngularVelocity.X - (stTorqueSRP.X + stTorqueDrag.X);
    stCMG_TorqueCmd.Y := -fKp * stErrorQuaternion.q2 - fKd * stAngularVelocity.Y - (stTorqueSRP.Y + stTorqueDrag.Y);
    stCMG_TorqueCmd.Z := -fKp * stErrorQuaternion.q3 - fKd * stAngularVelocity.Z - (stTorqueSRP.Z + stTorqueDrag.Z);

    M_AttitudeControl := TRUE;
END_METHOD

(* -----------------------------------------------------------------------------
   METHOD: M_EstimateLux
   ----------------------------------------------------------------------------- *)
METHOD M_EstimateLux : BOOL
VAR
    fSlantRange : LREAL;
    fBaseLuxAt1000km : LREAL := 3.5;
END_VAR

    (* Calculate slant range to target *)
    fSlantRange := SQRT(EXPT(stTargetVecECEF.X, 2) + EXPT(stTargetVecECEF.Y, 2) + EXPT(stTargetVecECEF.Z, 2));

    IF fSlantRange > 0.0 THEN
        fEstimatedLux := 20.0 * fBaseLuxAt1000km * EXPT(1000.0 / fSlantRange, 2);
    ELSE
        fEstimatedLux := 0.0;
    END_IF

    bTargetIlluminated := (fEstimatedLux >= fRequiredLux) AND (ABS(stErrorQuaternion.q0) > 0.999);

    M_EstimateLux := TRUE;
END_METHOD
`
