FUNCTION_BLOCK "Lyophilizer_Mut4"
VAR_INPUT
    Start : Bool;
    Stop : Bool;
    StartDefrost : Bool;
    VacuumSetPoint : Real;
    TempSetPoint : Real;
    ActualVacuum_1 : Real;
    ActualVacuum_2 : Real;
    ActualTemp_1 : Real;
    ActualTemp_2 : Real;
    CondenserTemp : Real;
    PN_Comm_OK : Bool;
    RemoteStart : Bool;
    User_Role : Int;
    HIL_Mode_Enable : Bool;
    HIL_Sim_Vacuum : Real;
    HIL_Sim_Temp : Real;
END_VAR
VAR_OUTPUT
    VacuumValveControl : Real;
    HeaterControl : Real;
    CoolingControl : Real;
    DefrostHeater : Bool;
    DrainValve : Bool;
    Fault_Active : Bool;
    Fault_Code : Int;
    SCADA_State : Int;
    SelfTest_Passed : Bool;
END_VAR
VAR
    PID_Vacuum : "PID_Compact";
    PID_Temp : "PID_Compact";
    State : Int;
    DefrostTimer : TON;
    SelfTestTimer : TON;
    ValidVacuum : Real;
    ValidTemp : Real;
    Drift_Accum_Vac : Real;
    Drift_Accum_Temp : Real;
END_VAR

BEGIN
    Fault_Active := FALSE;
    Fault_Code := 0;

    IF User_Role < 1 THEN
        Fault_Active := TRUE;
        Fault_Code := 403;
    END_IF;

    IF HIL_Mode_Enable THEN
        ValidVacuum := HIL_Sim_Vacuum;
        ValidTemp := HIL_Sim_Temp;
    ELSE
        Drift_Accum_Vac := Drift_Accum_Vac + ABS(ActualVacuum_1 - ActualVacuum_2);
        Drift_Accum_Temp := Drift_Accum_Temp + ABS(ActualTemp_1 - ActualTemp_2);

        IF Drift_Accum_Vac > 1000.0 THEN
            Fault_Active := TRUE;
            Fault_Code := 501;
        END_IF;
        IF Drift_Accum_Temp > 500.0 THEN
            Fault_Active := TRUE;
            Fault_Code := 502;
        END_IF;

        IF ABS(ActualVacuum_1 - ActualVacuum_2) > 10.0 THEN
            Fault_Active := TRUE;
            Fault_Code := 301;
            ValidVacuum := ActualVacuum_1;
        ELSE
            ValidVacuum := (ActualVacuum_1 + ActualVacuum_2) / 2.0;
        END_IF;

        IF ABS(ActualTemp_1 - ActualTemp_2) > 5.0 THEN
            Fault_Active := TRUE;
            Fault_Code := 302;
            ValidTemp := ActualTemp_1;
        ELSE
            ValidTemp := (ActualTemp_1 + ActualTemp_2) / 2.0;
        END_IF;
    END_IF;

    IF NOT PN_Comm_OK THEN
        Fault_Active := TRUE;
        Fault_Code := 101;
    END_IF;

    IF Fault_Active THEN
        State := 99;
    ELSIF Stop THEN
        State := 0;
    ELSIF (Start OR RemoteStart) AND State = 0 AND User_Role >= 1 THEN
        State := 10;
    ELSIF StartDefrost AND State = 0 AND User_Role = 2 THEN
        State := 2;
    END_IF;

    SCADA_State := State;

    CASE State OF
        0:
            VacuumValveControl := 0.0;
            HeaterControl := 0.0;
            CoolingControl := 0.0;
            DefrostHeater := FALSE;
            DrainValve := FALSE;
            SelfTest_Passed := FALSE;
            SelfTestTimer(IN:=FALSE, PT:=T#5S);
        10:
            VacuumValveControl := 10.0;
            HeaterControl := 5.0;
            CoolingControl := 5.0;
            SelfTestTimer(IN:=TRUE, PT:=T#5S);
            IF SelfTestTimer.Q THEN
                SelfTest_Passed := TRUE;
                SelfTestTimer(IN:=FALSE, PT:=T#5S);
                State := 1;
            END_IF;
        1:
            PID_Vacuum(Setpoint:=VacuumSetPoint, Input:=ValidVacuum, Output=>VacuumValveControl);
            PID_Temp(Setpoint:=TempSetPoint, Input:=ValidTemp, Output=>HeaterControl);
            CoolingControl := 100.0 - HeaterControl;
            DefrostHeater := FALSE;
            DrainValve := FALSE;
        2:
            DefrostHeater := TRUE;
            DrainValve := TRUE;
            DefrostTimer(IN:=TRUE, PT:=T#30M);
            IF DefrostTimer.Q OR CondenserTemp > 20.0 THEN
                DefrostHeater := FALSE;
                DrainValve := FALSE;
                DefrostTimer(IN:=FALSE, PT:=T#30M);
                State := 0;
            END_IF;
        99:
            VacuumValveControl := 0.0;
            HeaterControl := 0.0;
            CoolingControl := 100.0;
            DefrostHeater := FALSE;
            DrainValve := FALSE;
    END_CASE;
END_FUNCTION_BLOCK
