FUNCTION_BLOCK FB_HPHT_DiamondPress
VAR_INPUT
    (* System and Safety Signals *)
    bEnable                     : BOOL;     (* Main system sequence enable signal *)
    bEmergencyStop              : BOOL;     (* Hardware safety relay status (TRUE = OK, FALSE = TRIPPED) *)
    bManualOverride             : BOOL;     (* Manual operation mode toggle *)
    bWaterCoolingFlowOK         : BOOL;     (* Primary cooling loop flow verification *)

    (* Anvil Hydraulic Pressure Sensors (Bar) *)
    rPressTop                   : REAL;     (* Top anvil cylinder pressure feedback *)
    rPressBottom                : REAL;     (* Bottom anvil cylinder pressure feedback *)
    rPressLeft                  : REAL;     (* Left anvil cylinder pressure feedback *)
    rPressRight                 : REAL;     (* Right anvil cylinder pressure feedback *)
    rPressFront                 : REAL;     (* Front anvil cylinder pressure feedback *)
    rPressBack                  : REAL;     (* Back anvil cylinder pressure feedback *)

    (* Chamber Temperature Sensors (Celsius) *)
    rTempCore1                  : REAL;     (* Primary core temperature thermocouple (Type C) *)
    rTempCore2                  : REAL;     (* Redundant core temperature thermocouple (Type C) *)
END_VAR

VAR_OUTPUT
    (* System Status *)
    bSystemReady                : BOOL;     (* System is ready for sequence initiation *)
    bAlarm                      : BOOL;     (* Critical fault alarm active *)
    bWarning                    : BOOL;     (* Non-critical warning active *)
    iCurrentState               : INT;      (* Current sequence state step *)
    bPhaseTransitionActive      : BOOL;     (* True when graphite-to-diamond latent heat absorption is detected *)

    (* Proportional Valve Control Outputs (0-100%) *)
    rValveCtrlTop               : REAL;
    rValveCtrlBottom            : REAL;
    rValveCtrlLeft              : REAL;
    rValveCtrlRight             : REAL;
    rValveCtrlFront             : REAL;
    rValveCtrlBack              : REAL;

    (* Heater Output *)
    rHeaterPowerCmd             : REAL;     (* Thyristor heater power command (0-100%) *)
END_VAR

VAR
    (* Internal State Variables *)
    iState                      : INT := 0; 
    tStateTimer                 : TON;
    tSoakTimer                  : TON;

    (* Filtering and Math *)
    rAvgPressure                : REAL;
    rMaxPressDeviation          : REAL;
    rFilteredTemp               : REAL;
    rPrevTemp                   : REAL;
    rTempDerivative             : REAL;

    (* Process Setpoints *)
    rTargetPressure             : REAL := 60000.0; (* 60 kBar target *)
    rTargetTemp                 : REAL := 1550.0;  (* 1550 °C target *)

    (* Error tracking *)
    rPressErrTop, rPressErrBot  : REAL;
    rPressErrLeft, rPressErrRight : REAL;
    rPressErrFront, rPressErrBack : REAL;

    rProportionalGain           : REAL := 0.25;
    rIntegralAccumulator        : REAL := 0.0;
END_VAR

(* === MAIN LOGIC === *)

(* Step 1: Critical Safety Interlocks & E-Stop Handler *)
IF NOT bEmergencyStop OR NOT bWaterCoolingFlowOK THEN
    bSystemReady := FALSE;
    bAlarm := TRUE;
    iState := 999; (* FAULT STATE *)

    (* Safe shutdown of all power and pressure *)
    rHeaterPowerCmd := 0.0;
    rValveCtrlTop := 0.0;
    rValveCtrlBottom := 0.0;
    rValveCtrlLeft := 0.0;
    rValveCtrlRight := 0.0;
    rValveCtrlFront := 0.0;
    rValveCtrlBack := 0.0;
    iCurrentState := iState;
    RETURN;
END_IF;

(* Step 2: Sensor Fusion and Noise Filtering *)
(* Average the dual redundant thermocouples *)
rFilteredTemp := (rTempCore1 + rTempCore2) / 2.0;

(* Calculate dT/dt for phase transition mapping (latent heat signature detection) *)
rTempDerivative := rFilteredTemp - rPrevTemp;
rPrevTemp := rFilteredTemp;

(* Calculate global average pressure across all 6 anvils *)
rAvgPressure := (rPressTop + rPressBottom + rPressLeft + rPressRight + rPressFront + rPressBack) / 6.0;

(* Anvil Synchronization Integrity Check *)
rMaxPressDeviation := MAX(
    ABS(rPressTop - rAvgPressure),
    MAX(ABS(rPressBottom - rAvgPressure),
    MAX(ABS(rPressLeft - rAvgPressure),
    MAX(ABS(rPressRight - rAvgPressure),
    MAX(ABS(rPressFront - rAvgPressure), ABS(rPressBack - rAvgPressure)))))
);

IF rMaxPressDeviation > 500.0 THEN
    bWarning := TRUE;
    IF rMaxPressDeviation > 1500.0 THEN
        bAlarm := TRUE;
        iState := 999; (* Asymmetric stress fault, abort to prevent anvil catastrophic failure *)
    END_IF;
ELSE
    bWarning := FALSE;
END_IF;

(* Step 3: Core HPHT State Machine *)
CASE iState OF
    0: (* IDLE: System initialization and pre-flight checks *)
        bSystemReady := TRUE;
        rHeaterPowerCmd := 0.0;
        IF bEnable AND NOT bAlarm THEN
            bSystemReady := FALSE;
            iState := 10;
        END_IF;

    10: (* RAM_ENGAGE: Low pressure approach of all 6 anvils *)
        rValveCtrlTop := 5.0; rValveCtrlBottom := 5.0;
        rValveCtrlLeft := 5.0; rValveCtrlRight := 5.0;
        rValveCtrlFront := 5.0; rValveCtrlBack := 5.0;

        IF rAvgPressure > 100.0 THEN
            iState := 20;
        END_IF;

    20: (* PRESSURE_RAMP: Synchronized high-pressure buildup to 60 kBar *)
        (* Implement individual proportional correction to maintain centering *)
        rPressErrTop := rAvgPressure - rPressTop;
        rValveCtrlTop := 20.0 + (rPressErrTop * rProportionalGain);

        rPressErrBot := rAvgPressure - rPressBottom;
        rValveCtrlBottom := 20.0 + (rPressErrBot * rProportionalGain);

        rPressErrLeft := rAvgPressure - rPressLeft;
        rValveCtrlLeft := 20.0 + (rPressErrLeft * rProportionalGain);

        rPressErrRight := rAvgPressure - rPressRight;
        rValveCtrlRight := 20.0 + (rPressErrRight * rProportionalGain);

        rPressErrFront := rAvgPressure - rPressFront;
        rValveCtrlFront := 20.0 + (rPressErrFront * rProportionalGain);

        rPressErrBack := rAvgPressure - rPressBack;
        rValveCtrlBack := 20.0 + (rPressErrBack * rProportionalGain);

        IF rAvgPressure >= rTargetPressure THEN
            iState := 30;
        END_IF;

    30: (* HEATER_RAMP: Bring temperature to 1550 °C slowly to prevent thermal shock *)
        IF rFilteredTemp < rTargetTemp THEN
            rHeaterPowerCmd := rHeaterPowerCmd + 0.01; 
            IF rHeaterPowerCmd > 85.0 THEN rHeaterPowerCmd := 85.0; END_IF;
        ELSE
            iState := 40;
        END_IF;

    40: (* HPHT_SOAK & PHASE TRANSITION MAPPING *)
        (* Maintain P and T, detect graphite -> diamond transition (endothermic) *)
        tSoakTimer(IN := TRUE, PT := T#4H); 

        IF (rHeaterPowerCmd > 60.0) AND (rTempDerivative < -0.1) THEN
            (* Endothermic reaction absorbing heat faster than input *)
            bPhaseTransitionActive := TRUE;
        ELSE
            bPhaseTransitionActive := FALSE;
        END_IF;

        IF tSoakTimer.Q THEN
            tSoakTimer(IN := FALSE);
            iState := 50;
        END_IF;

    50: (* COOLING: Must cool under pressure to maintain crystal lattice structure *)
        rHeaterPowerCmd := rHeaterPowerCmd - 0.05;
        IF rHeaterPowerCmd < 0.0 THEN rHeaterPowerCmd := 0.0; END_IF;

        IF rFilteredTemp < 100.0 THEN
            iState := 60;
        END_IF;

    60: (* DEPRESSURIZE: Slow controlled release to prevent explosive decompression *)
        rValveCtrlTop := rValveCtrlTop - 0.01;
        rValveCtrlBottom := rValveCtrlBottom - 0.01;
        rValveCtrlLeft := rValveCtrlLeft - 0.01;
        rValveCtrlRight := rValveCtrlRight - 0.01;
        rValveCtrlFront := rValveCtrlFront - 0.01;
        rValveCtrlBack := rValveCtrlBack - 0.01;

        IF rAvgPressure < 10.0 THEN
            iState := 70;
        END_IF;

    70: (* COMPLETE: Safe extraction state *)
        bSystemReady := TRUE;
        IF NOT bEnable THEN
            iState := 0;
        END_IF;

    999: (* FAULT_RECOVERY: Await operator reset *)
        IF bEnable = FALSE AND bEmergencyStop = TRUE AND bWaterCoolingFlowOK = TRUE THEN
            bAlarm := FALSE;
            iState := 0;
        END_IF;

END_CASE;

iCurrentState := iState;

END_FUNCTION_BLOCK
